POL = []


def _pol(key, var, fuel='', sector='', kind='mt', mt=None):
    POL.append((key, var, fuel, sector, kind, mt))


def _mt_rows():
    import openpyxl
    src = openpyxl.load_workbook(MT_TEMPLATE)['MTInputs']
    MT_LABELS.update({r: src.cell(r, 2).value for r in range(1, src.max_row + 1)})
    MT_HEADS.update(r for r in range(8, src.max_row + 1) if src.cell(r, 6).value is None and src.cell(r, 2).value)
    return {src.cell(r, 8).value: r for r in range(8, src.max_row + 1) if src.cell(r, 8).value}


MT_LABELS = {}                          # MTInputs row -> label in column B (template)
MT_HEADS = set()                        # MTInputs heading rows (no value in F 'Used for calculation')


def mt_locator(row):
    """v0.2.4: how the workbook finds an MTInputs row: (NameOfParameter, '', '') where column H names it, else
    ('', heading, label): the first row labelled `label` below the (unique) MTInputs heading row above it."""
    name = next((n for n, r in MT_NAMES.items() if r == row), None)
    if name:
        return name, '', ''
    lab = MT_LABELS[row]
    labs = [MT_LABELS.get(r) for r in range(1, max(MT_LABELS) + 1)]
    for a in range(row - 1, 0, -1):          # nearest unique heading above
        if a in MT_HEADS and labs.count(MT_LABELS[a]) == 1:
            assert labs[a:].index(lab) + a + 1 == row, (row, a)
            return '', MT_LABELS[a], lab
    raise ValueError(row)


