TR_PAR = {r['key']: r for r in csv.DictReader(open(os.path.join(DATA, 'transport_params.csv'), encoding='utf-8'))}
TR_CLS = [('pas', 'pass', 'Passenger', 'Pas'), ('fre', 'fre', 'Freight', 'Fre'), ('cyc', 'cyc', '2-3 wheeler', 'Cyc')]
