                                 (4586, 'ice', 'pau', lambda x: f'{x.P("life|pas")}-{x.P("own|pas")}', 4475),
                                 (4588, 'bev', 'pau', lambda x: f'{x.P("life|pas")}-{x.P("own|pas")}', 4476),
                                 (4628, 'ice', 'fre', lambda x: x.P('life|fre'), 4491),
                                 (4630, 'bev', 'fre', lambda x: x.P('life|fre'), 4494),
                                 (4685, 'ice', 'cyc', lambda x: x.P('life|cyc'), 4502),
