def TRC(pk):
    """Absolute cell of a section-5b parameter (columns D:G of its parameter row)."""
    key, col = TR_P[pk]
    return f'${col}{R_TR[key]}'


class _TX:
    """Cell references of a section-5b formula in row r, column number c (see _tr)."""

    def __init__(self, r, c):
        self.r, self.colnum, self.col, self.prev = r, c, L(c), L(c - 1)
        self.yr, self.dk = f'{self.col}{R_YEAR}', f'{self.col}{R_TR["tr.dk"]}'      # row-relative references
        self.cn, self.pol = f'{self.col}{R_TR["tr.col"]}', f'{self.col}{R_TR["tr.pol"]}'
        self.self_p = f'{self.prev}{r}'
        self.D, self.E, self.F, self.G = (f'${k}{r}' for k in 'DEFG')

    def c(self, k):
        return f'{self.col}{R_TR[k]}'

    def ca(self, k):
        return f'{self.col}{R_TR[k]}'

    def p(self, k):
        return f'{self.prev}{R_TR[k]}'

    def pa(self, k):
        return f'{self.prev}{R_TR[k]}'

    def rga(self, k1, k2):
        return f'{self.col}{R_TR[k1]}:{self.col}{R_TR[k2]}'

    def prga(self, k1, k2):
        return f'{self.prev}{R_TR[k1]}:{self.prev}{R_TR[k2]}'

    def X(self, row, rel=True):
        return f'{self.col}{row}'

    def XP(self, row, rel=True):
        return f'{self.prev}{row}'

    @staticmethod
    def P(pk):
        return TRC(pk)

    def M(self, k):
        return f'{self.col}{R_TR[TR_MT_NAME[k]]}'


def _top_simple(a):
    """True if the argument text needs no brackets inside an expression (a reference, number, name, string or one
    function call)."""
    depth, s = 0, re.sub(r'"[^"]*"', '""', a)
    for i, ch in enumerate(s):
        depth += (ch == '(') - (ch == ')')
        if depth == 0 and ch in '+-*/^&=<>,' and not (ch == '-' and i == 0 and False):
            return False
    return True


def lambda_plain(name, args):
    """The plain formula of a LAMBDA call: its body with the arguments substituted (one pass), brackets only
    where an argument is not a whole function argument and not a single term."""
    params, body = LAMBDAS[name]
    assert len(params) == len(args), (name, args)
    rx = re.compile(r'(?<![A-Za-z_.\d])(' + '|'.join(sorted(params, key=len, reverse=True)) + r')(?![A-Za-z_\d(])')
    out = []
    for part in re.split(r'("[^"]*")', body):
        if part.startswith('"'):
            out.append(part)
            continue
        pos, buf = 0, ''
        for m in rx.finditer(part):
            a = args[params.index(m.group(1))]
            before = part[m.start() - 1] if m.start() else '('
            after = part[m.end()] if m.end() < len(part) else ')'
            whole = before in '(,' and after in ',)'
            buf += part[pos:m.start()] + (a if whole or _top_simple(a) else f'({a})')
            pos = m.end()
        out.append(buf + part[pos:])
    return ''.join(out)


R_TR = {}            # section-5b row key -> Mitigation row
REN_ROWS = ('ener.avi.ren', 'ener.nav.ren')   # v0.9.0 (R10.7): 5b rows of fuel use outside the fuel blocks
TR_RES = (5325, 'trbio')   # section-5b result rows read by ener (gasoline, diesel, LPG, gas, label row, biofuels)
TR_LAYOUT = []       # (row, kind, item): 'head' text, 'label' (first row item of the run), 'row' item, 'sum'
TR_OWNBASE = set()   # rows with their own base-year formula (the Lambdas variant keeps it)
TR_LAMROWS = set()   # rows calling a LAMBDA in 2041


def _layout_tr(r0):
    """Rows of section 5b from row r0 (band): heading rows, a label row above every run of rows of one variable that
    has values in D:G (consecutive MTInputs rows share one), the rows; then a blank row and the summary row."""
    _build_tr_spec()
    r = r0 + 2                       # v0.3.9: one blank row after the band
    prev_var, prev_kind = None, None
    items = TR_ROWS
    for i, it in enumerate(items):
        if it['kind'] == 'head':
            if i:
                r += 1               # v0.4.1: one blank row before each sub-section heading
            TR_LAYOUT.append((r, 'head', it))
            r += 1
            prev_var = prev_kind = None
            continue
        if it['var'] != prev_var and not (it['kind'] == 'mt' and prev_kind == 'mt'):
            run = [x for x in items[i:] if x['kind'] != 'head']
            run = run[:next((k for k, x in enumerate(run) if x['var'] != it['var']), len(run))]
            if any(any(p is not None for p in x['par']) for x in run) or it['kind'] == 'mt':
                if prev_var is not None:
                    r += 1           # v0.3.9: one blank row between blocks
                TR_LAYOUT.append((r, 'label', it))
                r += 1
        assert it['key'] not in R_TR, it['key']
        R_TR[it['key']] = r
        TR_LAYOUT.append((r, 'row', it))
        if it['kind'] == 'calc':
            TR_LAMROWS.add(r)
            if it['base'] is not None:
                TR_OWNBASE.add(r)
        prev_var, prev_kind = it['var'], it['kind']
        r += 1
    seen = set()
    for it in items:
        if it['kind'] != 'head':
            k = (it['var'], it['b'], it['c'])
            assert k not in seen, f'section 5b: two rows {k}'
            seen.add(k)
            n = len([p for p in it['par']])
            assert it['var'] not in TR_VARINFO or n <= len(TR_VARINFO[it['var']]) - 6 or it['kind'] == 'mt', (it['var'], n)
    return r + 1                     # summary row (after a blank row)


# ---------------------------------------------------------------- 6b. Residential leakage to biomass (v0.5.1)
# Legacy Mitigation rows 5571-5593 (switch BiomassLeakage, MTInputs row 325; Settings C59, BioLeak), with the legacy bugs
# fixed (L45: one set of rows per fuel with its own price and share, fuel use = the elasticity model + the cumulative
# change, computed on last year's actual use, one switch; L90: biomass gains the same useful energy; L91: an exempt fuel
# does not leak, as the new policy is the row's own nce). As legacy (issues I-a, I-b, I51): only the most-used cooking
# fuel (WHOCooking, CookFuel) leaks; share = MIN((1 + change in the new policy / last year's after-tax price)^(sigma x
# e_bio / e_fuel / lag) - 1, 1), reversible; the flows accumulate as a level shift; the fossil change is weighted by the
# cookstove efficiency (dF = -F x e_fuel x share). Res rows are read by position (INDEX over the residential block of a
# variable, parameter fuel position), so every row of a variable has one formula. Fuel use (ener) adds the cumulative
# change of its row at Inputs position lkpos (1 = the zero row lkz).
LK_ROWS = []         # dict(key, var, b, c, kind, fmt, par, base, lam, plain); kinds: calc, plain, head
R_LK = {}            # section-6b row key -> Mitigation row
LK_LAYOUT = []       # (row, kind, item): 'head', 'label', 'row'
LK_OWNBASE = set()   # rows with their own base-year formula (0)
LK_LAMROWS = set()   # rows calling a LAMBDA in the LAMBDA test group
LK_RES = ('lkz', 'lkcb.bio')   # first and last of the rows read by ener (LkFuelKey: their column B)


class _LX:
    """Cell references of a section-6b formula in row r, column number c."""

    def __init__(self, r, c):
        self.r, self.col, self.prev = r, L(c), L(c - 1)

    def c(self, k):                  # row of the block, this column (relative row: the same offset for every fuel)
        return f'{self.col}{R_LK[k]}'

    def p(self, k):
        return f'{self.prev}{R_LK[k]}'

    def a(self, k):                  # v0.6.0: a single shared row (absolute: the same formula in every fuel row)
        return f'{self.col}${R_LK[k]}'

    def res(self, v, prev=False):    # residential block of variable v (absolute rows), this or the previous column
        h = SUB_HEAD['res'] + VOFF[v]
        c_ = self.prev if prev else self.col
        return f'{c_}${h}:{c_}${h + NF - 1}'


def _lk_inp(code):
    return lambda r: '=' + inputs_lookup(code, r)


def _layout_lk(r0):
    """Rows of section 6b from row r0 (band): the sub-heading, a label row above every run of rows of one variable with
    values in D:G (one blank row between runs), the cumulative rows read by fuel use without label rows (contiguous);
    then a blank row and the summary row."""
    def row(key, var, b, kind='calc', par=(), base=None, lam=None, plain=None, fmt='0.000'):
        LK_ROWS.append(dict(key=key, var=var, b=b, c='res', kind=kind, fmt=fmt, par=list(par), base=base, lam=lam,
                            plain=plain))
    eff = '=INDEX(CookEffVal,MATCH($B{r},CookEffKey,0))'
    zero = lambda x: '=0'
    LK_ROWS.append(dict(key='head', kind='head', text='Leakage of the most-used cooking fuel to biomass (BiomassLeakage, '
                        'Settings C59; legacy Mitigation rows 5571-5593; bugs L45, L90, L91 fixed)'))
    for m in LK_FUELS:               # new policy incl. VAT in the residential price (legacy 5574, 5580, 5586)
        row(f'lkt.{m}', 'lkt', m, par=[_lk_inp('vr'), _lk_inp('fpos')], fmt='0.000',
            lam=('LEAKTAX', lambda x: (f'INDEX({x.res("nce")},$E{x.r})', f'$D{x.r}')))
    for m in LK_FUELS:               # share moving to biomass (legacy 5575-5576, 5581-5582, 5587-5589)
        row(f'lkp.{m}', 'lkp', m, base=zero, fmt='0.0000',
            par=[lambda r: f'=IF(AND(LEFT(BioLeak,3)="Yes",CookFuel=$B{r}),1,0)',
                 lambda r: f'=ResBioSubst*CookEffBio/INDEX(CookEffVal,MATCH($B{r},CookEffKey,0))/ResSubstLag',
                 _lk_inp('fpos')],
            lam=('LEAKSHARE', lambda x: (f'$D{x.r}', x.c(f'lkt.{x.m}'), x.p(f'lkt.{x.m}'),
                                         f'INDEX({x.res("atp", True)},$F{x.r})', f'$E{x.r}')))
    for m in LK_FUELS:               # change in fossil fuel use (legacy 5577, 5583, 5588)
        row(f'lkd.{m}', 'lkd', m, base=zero, fmt='#,##0.0', par=[lambda r: eff.format(r=r), _lk_inp('fpos')],
            lam=('LEAKCHANGE', lambda x: (f'INDEX({x.res("ener", True)},$E{x.r})-{x.p(f"lkx.{x.m}")}', f'$D{x.r}',
                                          x.c(f'lkp.{x.m}'))))   # v0.9.0 (R6.7, I138): on the not-exempt use only
    for m in LK_FUELS:               # biomass with the same useful energy (legacy 5578, 5584, 5591, 5593; L90 fixed)
        row(f'lkb.{m}', 'lkb', m, fmt='#,##0.0', par=[lambda r: eff.format(r=r), lambda r: '=CookEffBio'],
            lam=('LEAKBIOMASS', lambda x: (x.c(f'lkd.{x.m}'), f'$D{x.r}', f'$E{x.r}')))
    # v0.5.6 (12b, LegacyDiff 67): initially exempt demand of the most-used cooking fuel (legacy rows 5564-5570, L48 and
    # L94 fixed): the exempt share follows the fuel use of its row with the usage elasticity phased in
    row('lkxp', 'lkxp', 'none', fmt='0.00', lam=('PHASEIN', lambda x: (f'{x.col}${R_POL["ExemptPhaseout"]}',
                                                                       f'{x.col}${R_YEAR}', f'{x.col}${R_POL["YearPha"]}',
                                                                       f'{x.col}${R_POL["ExemptPhaseoutPeriod"]}')))
    for m in LK_FUELS:
        row(f'lkxe.{m}', 'lkxe', m, base=lambda x: '=1', fmt='0.0000', par=[_lk_inp('fpos')],
            lam=('XRATIO', lambda x: (f'INDEX({x.res("enel")},$D{x.r})', f'INDEX({x.res("enel", True)},$D{x.r})')))
    for m in LK_FUELS:
        row(f'lkxr.{m}', 'lkxr', m, base=lambda x: '=1', fmt='0.0000', par=[_lk_inp('fpos')],
            lam=('XRATIO', lambda x: (f'INDEX({x.res("atp")},$D{x.r})', f'INDEX({x.res("atp", True)},$D{x.r})')))
    for m in LK_FUELS:
        row(f'lkx.{m}', 'lkx', m, fmt='#,##0.0',
            par=[_lk_inp('fpos'), lambda r: f'=INDEX($E${SUB_HEAD["res"] + VOFF["enel"]}:$E${SUB_HEAD["res"] + VOFF["enel"] + NF - 1},$D{r})',
                 lambda r: '=IF(CookFuel=$B' + str(r) + ',ExemptCookShare,0)'],
            base=lambda x: f'=$F{x.r}*INDEX({x.res("enel")},$D{x.r})',
            lam=('XPATH', lambda x: (x.p(f'lkx.{x.m}'), x.c(f'lkxe.{x.m}'), x.c(f'lkxr.{x.m}'), f'$E{x.r}', x.a('lkxp'))))
    for m in LK_FUELS:
        row(f'lkxa.{m}', 'lkxa', m, base=zero, fmt='#,##0.0',
            par=[_lk_inp('fpos'), lambda r: '=IF(CookFuel=$B' + str(r) + ',ExemptCookShare,0)'],
            lam=('XADJ', lambda x: (x.c(f'lkx.{x.m}'), f'$E{x.r}', f'INDEX({x.res("enel")},$D{x.r})')))
    row('lkz', 'lkz', 'none', kind='plain', plain=zero, fmt='#,##0.0')     # position 1: no leakage
    for m in LK_FUELS:               # cumulative change, added to fuel use (legacy totals 5554, 5557, 5558)
        row(f'lkc.{m}', 'lkc', m, base=zero, fmt='#,##0.0',
            lam=('LEAKCUM', lambda x: (x.p(f'lkc.{x.m}'), f'{x.c(f"lkd.{x.m}")}+{x.c(f"lkxa.{x.m}")}-{x.p(f"lkxa.{x.m}")}')))
    row('lkcb.bio', 'lkcb', 'bio', base=zero, fmt='#,##0.0',                # cumulative biomass (legacy total 5560)
        lam=('LEAKCUM', lambda x: (x.p('lkcb.bio'), f'SUM({x.c("lkb." + LK_FUELS[0])}:{x.c("lkb." + LK_FUELS[-1])})')))
    r = r0 + 2                       # one blank row after the band
    prev_var = None
    for it in LK_ROWS:
        if it['kind'] == 'head':
            LK_LAYOUT.append((r, 'head', it))
            r += 1
            continue
        if it['var'] != prev_var and it['par']:
            if prev_var is not None:
                r += 1               # one blank row between blocks
            LK_LAYOUT.append((r, 'label', it))
            r += 1
        elif it['var'] != prev_var and not it['par'] and prev_var in ('lkt', 'lkp', 'lkd', 'lkb'):
            r += 1                   # blank row before the cumulative rows (no parameters, no label row)
        R_LK[it['key']] = r
        LK_LAYOUT.append((r, 'row', it))
        if it['kind'] == 'calc':
            LK_LAMROWS.add(r)
            if it['base'] is not None:
                LK_OWNBASE.add(r)
        prev_var = it['var']
        r += 1
    assert R_LK[LK_RES[1]] - R_LK[LK_RES[0]] == len(LK_FUELS) + 1     # contiguous rows read by ener
    return r + 1                     # summary row (after a blank row)


