def legacy_names(tab, cap, spec):
    """v0.4.5: defined names over a legacy table built by legacy_table (header row 3, data rows 4 to 3 + cap). spec:
    name -> 'key' (the key column right of the table), a legacy header or column number (that column), or (first,
    last) / (first, last, 'head') = the columns first..last (-1 = last legacy column) of the data / the header row."""
    with open(os.path.join(DATA, f'legacy_{tab}.csv'), encoding='utf-8') as fh:
        head = next(csv.reader(fh))
    col = lambda x: len(head) if x == -1 else x if isinstance(x, int) else head.index(x) + 1
    out = {}
    for name, x in spec.items():
        if x == 'key':
            a = b = len(head) + 1
        elif isinstance(x, tuple):
            a, b = col(x[0]), col(x[1])
        else:
            a = b = col(x)
        r0, r1 = (3, 3) if isinstance(x, tuple) and x[-1] == 'head' else (4, 3 + cap)
        out[name] = f"{_qsheet(tab)}!${L(a)}${r0}:${L(b)}${r1}"
    return out


# ---------------------------------------------------------------- data sheets
def data_sheet(wb, name, title_text, header, rows, source):
    ws = wb.create_sheet(name)
    title(ws, title_text, len(header))
    put(ws, 'A1', f'Source: {source}', FONT)
    for j, h in enumerate(header, 1):
        put(ws, f'{L(j)}3', num(h) if isinstance(h, str) and h.isdigit() else h, FONT_B, F_INPUT)
    for i, r in enumerate(rows, 4):
        for j, v in enumerate(r, 1):
            ws.cell(i, j, num(v)).font = FONT
    ws.freeze_panes = 'B4'
    ws.column_dimensions['A'].width = 18

def legacy_table(wb, name, title_text, source, key=None, cap=0):
    """v0.4.5: a legacy CPAT data table unchanged (columns and order of legacy, header in row 3, data from row 4), so
    that the full legacy table (all countries) can be pasted over it at A4 (data rows without the header). Where the
    legacy table has no unique code column, key (a template with {r}) adds the workbook's key as a formula column right
    of the table, filled to row 3 + cap. Returns (sheet, number of data rows, number of legacy columns)."""
    t = read_csv(f'legacy_{name}.csv')
    ws = wb.create_sheet(name)
    n = len(t[0]) + (1 if key else 0)
    title(ws, title_text, n)
    put(ws, 'A1', f'Source: {source}. Legacy table unchanged: paste the legacy data rows (all countries) at A4'
                  + (f'; the key column {L(n)} is a formula, filled to row {3 + cap}' if key else ''), FONT)
    for j, h in enumerate(t[0], 1):
        put(ws, f'{L(j)}3', num(h) if isinstance(h, str) and h.isdigit() else h, FONT_B)
    if key:
        put(ws, f'{L(n)}3', 'Key', FONT_B)
    border_bottom(ws, 3, 1, n)
    for i, row in enumerate(t[1:], 4):
        for j, v in enumerate(row, 1):
            ws.cell(i, j, num(v)).font = FONT
    if key:
        for i in range(4, 4 + max(cap, len(t) - 1)):
            ws.cell(i, n, key.format(r=i)).font = FONT_HELP
    ws.freeze_panes = 'B4'
    ws.column_dimensions['A'].width = 24
    return ws, len(t) - 1, len(t[0])


def legacy_cells(wb, name, title_text, source, header=None):
    """v0.4.6: a legacy CPAT tab with several tables, kept at its legacy cell addresses from row 3 (rows 1-2: the
    workbook's source line and title bar), so that the legacy tab (all countries) can be pasted over it from row 3 as it
    is. Values only (legacy formulas arrive as their cached values); legacy error values are left empty. header: {cell:
    text} written over row 3 cells that legacy leaves empty (e.g. Transport3 labels). Returns (sheet, last row)."""
    t = read_csv(f'legacy_{name}_cells.csv')[1:]
    ws = wb.create_sheet(name)
    ncol = max(int(c) for _r, c, _v in t)
    title(ws, title_text, min(ncol, 30))
    put(ws, 'A1', f'Source: {source}. Legacy tab at its legacy cell addresses: paste the legacy tab from row 3', FONT)
    for r, c, v in t:
        if re.fullmatch(r'0x[0-9a-f]{2}', v):                       # legacy error value (#N/A, #DIV/0!)
            continue
        ws.cell(int(r), int(c), v if v.lower() in ('nan', 'inf', '-inf', 'infinity') else num(v)).font = FONT
    for cell, text in (header or {}).items():
        put(ws, cell, text, FONT_B)
    ws.column_dimensions['A'].width = 14
    return ws, max(int(r) for r, _c, _v in t)


RA_FIT = os.path.join(HERE, '..', '..', 'data', 'range_anxiety_fit', 'range_anxiety_fit.csv')
RA_FIT_COLS = {'passenger': 8, 'freight': 14, 'cycle': 20}     # Transport3 H, N, T (names RAPas, RAFre, RACyc)


def ra_fit_apply(ws, last):
    """v0.9.0 (R10.8-R10.9): the range-anxiety start values fitted on the prototype's own model (scenario 1, fit year
    2025, ra_goalseek.py; data/range_anxiety_fit) replace the legacy stored solutions of the country in the Transport3
    table (bright yellow: data changed by assumption); countries without a fit keep the legacy values."""
    if not os.path.exists(RA_FIT):
        return
    fits = {r['country']: r for r in csv.DictReader(open(RA_FIT, encoding='utf-8'))}
    for r in range(5, last + 1):
        f = fits.get(ws.cell(r, 1).value)
        if not f:
            continue
        for k, c in RA_FIT_COLS.items():
            if f.get(k) not in (None, ''):
                cell = ws.cell(r, c, float(f[k]))
                cell.font, cell.fill = FONT_CHANGED, F_CHANGED
                cell.number_format = '#,##0'


def mult_rows():
    """v0.4.6: legacy Multipliers rows of each (group, instrument): median block (rows 88-145) and standard-deviation block
    (rows 147+), found by group label (column B) and instrument (column B below it) in the legacy tab."""
    cells = {(int(r), int(c)): v for r, c, v in read_csv('legacy_Multipliers_cells.csv')[1:]}
    b = {r: v for (r, c), v in cells.items() if c == 2}
    sd0 = next(r for r, v in sorted(b.items()) if v.startswith('STANDARD'))
    med0 = next(r for r, v in sorted(b.items()) if v.startswith('MEDIAN'))
    out = {}
    for blk, r0, r1 in (('median', med0, sd0), ('sd', sd0, max(b) + 1)):
        grp = None
        for r in range(r0, r1):
            v = b.get(r, '')
            if v.upper() in ('GLOBAL', 'HIC', 'UMIC', 'LMIC', 'LIC'):
                grp = v.lower()
            elif grp and v and (r, 4) in cells:
                out.setdefault((grp, v.lower()), {})[blk] = r
    return out


MULT_CTY = {'exc': 'Excise tax', 'pit': 'Labor tax', 'capt': 'Public investment', 'gnfs': 'Public consumption',
            'trns': 'Transfers', 'vat': 'VAT'}   # v0.4.15 (LD56): legacy country table of each instrument (column B label)
MULT_SRC = ['est', 'man']                # v0.4.15 (LD56): estimated (country) and manual multipliers


def mult_cty_rows():
    """v0.4.15 (LD56): (first, last) country row of each instrument's estimated table in the legacy Multipliers tab
    (rows 210-1620: label in column B, lag header below, countries in column C). CIT has no table (legacy reads the
    empty rows 1624-1822, bug L76) and WAGE reads the GNFS table in legacy (bug L76): both take the income group."""
    cells = {(int(r), int(c)): v for r, c, v in read_csv('legacy_Multipliers_cells.csv')[1:]}
    out = {}
    for i, lab in MULT_CTY.items():
        h = next(r for (r, c), v in sorted(cells.items()) if c == 2 and v == lab and r > 200)
        r0 = h + 2
        r1 = r0
        while (r1 + 1, 3) in cells and len(cells[(r1 + 1, 3)]) == 3:
            r1 += 1
        out[i] = (r0, r1)
    return out


def build_inputs_mult(wb):
    """v0.4.6: fiscal multipliers (data step), one column per group|range|instrument (base = median, low = median - sd,
    high = median + sd, as legacy Multipliers rows 36-57), one row per lag (0-19; lags past the last legacy lag hold
    its value), read from the legacy Multipliers tab (kept at its legacy addresses). v0.4.15 (LD56): also the sources
    est (the country's estimated table, income group where the country or the table is missing) and man (sheet Manual
    inputs J261:U268), each with the income group's standard deviation as legacy."""
    m = read_csv('multipliers.csv')
    rows = mult_rows()
    cty = mult_cty_rows()
    keys = [(r[0], r[2]) for r in m[1:] if r[1] == 'median']
    instr = [i for g, i in keys if g == keys[0][0]]
    ws = wb.create_sheet('Inputs_mult')
    cols = ([(g, rng, i, sg) for g, i in keys for rng, sg in (('base', 0), ('low', -1), ('high', 1))]
            + [(g, rng, i, sg) for g in MULT_SRC for i in instr for rng, sg in (('base', 0), ('low', -1), ('high', 1))])
    title(ws, 'Fiscal multipliers: % change of GDP k years after an impulse of 1% of GDP (data step; key '
              'group|range|instrument)', 30)
    put(ws, 'A3', 'Read from the legacy Multipliers tab: median (rows 88-145) plus sign x standard deviation (rows 147+) of '
                  'the group and instrument, lag k in column D + k; lags past the last legacy lag (MultLastLag) hold '
                  'its value. v0.4.15: est = the country\'s estimated table (rows 210-1620; exact match of the country code, '
                  'else the income group; CIT and WAGE: the income group), man = sheet Manual inputs J261:U268; both with '
                  'the income group\'s standard deviation (as legacy).', FONT)
    labels = ['Lag (years)', 'Group', 'Range', 'Instrument', 'Legacy row: median (man: row of Manual inputs)',
              'Legacy row: standard deviation', 'Sign of the standard deviation', 'Country table: first row',
              'Country table: last row', 'Column of the income group (base) in this table',
              'Legacy row of the income group\'s median']
    for k, lab in enumerate(labels):
        put(ws, f'A{IMULT_HDR + k}', lab, FONT_B, F_INPUT)
    lc = L(len(cols) + 1)
    grow = lambda k, c: f'INDEX(${L(2)}${IMULT_HDR + k}:${lc}${IMULT_HDR + k},{c}${IMULT_HDR + 9})'   # income group's
    for j, (g, rng, i, sg) in enumerate(cols, 2):
        c = L(j)
        h = lambda k: f'{c}${IMULT_HDR + k}'
        if g == 'est':
            med = f'=IFERROR(MATCH(CtryCode,INDEX(MultC,{h(7)}):INDEX(MultC,{h(8)}),0)+{h(7)}-1,{h(10)})'
        elif g == 'man':
            med = f'=MATCH({h(3)},MultManKey,0)'
        else:
            med = rows[(g, i)]['median']
        sd = f'={grow(5, c)}' if g in MULT_SRC else rows[(g, i)]['sd']
        r0, r1 = cty.get(i, ('', '')) if g == 'est' else ('', '')
        gcol = f'=MATCH(LOWER(IncomeGrp)&"|base|"&{h(3)},MultKey,0)' if g in MULT_SRC else ''
        gmed = f'={grow(4, c)}' if g in MULT_SRC else ''
        for k, v in enumerate([f'={c}{IMULT_HDR + 1}&"|"&{c}{IMULT_HDR + 2}&"|"&{c}{IMULT_HDR + 3}', g, rng, i,
                               med, sd, sg, r0, r1, gcol, gmed]):
            formula = isinstance(v, str) and v.startswith('=')
            put(ws, f'{c}{IMULT_HDR + k}', v, FONT_B if k == 0 else FONT, F_INPUT if 0 < k and not formula else None)
        lag = lambda r: f'MIN($A{r},MultLastLag)+1'
        src = 'MultMan' if g == 'man' else 'MultD'
        for t in range(MULT_LAGS):
            r = IMULT_R0 + t
            put(ws, f'{c}{r}', f'=INDEX({src},{c}${IMULT_HDR + 4},{lag(r)})+{c}${IMULT_HDR + 6}*INDEX(MultD,'
                               f'{c}${IMULT_HDR + 5},{lag(r)})', FONT, None, '0.00')
    for t in range(MULT_LAGS):
        put(ws, f'A{IMULT_R0 + t}', t, FONT)
    assert len(cols) + 1 <= 208, 'MultKey range (B:GZ) too short'


