def _mi_ranges(spec):
    """Cells of an A1 range 'E7:E12'."""
    a, b = spec.split(':')
    (c0, r0), (c1, r1) = [(CI_(re.match(r'[A-Z]+', x).group()), int(re.search(r'\d+', x).group()))
                          for x in (a, b)]
    return [(r, c) for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)]


def mi_formulas():
    """v0.5.2: the cells of 'Manual inputs' that get a formula instead of the legacy cached value: formulas within the
    sheet kept as legacy, references to other legacy tabs replaced by the prototype equivalent. {(row, col): formula}."""
    f = {(15, 29): '=AB15+(AB15-AA15)', (254, 6): '=1-SUM(F247:F253)', (165, 6):
         '=IF(LEFT(Settings!$C$9,6)="Manual","Yes","No")', (275, 5): mt_setting('IncElAdj'),
         (344, 2): '=CtryName', (245, 3): '="Source apportionment for "&CtryName&":"'}
    for r in range(150, 164):                                   # unit labels: legacy ="$/GJ, "&$H$148
        f[(r, 5)] = None                                        # filled from the cached text below
    for c in range(10, 33):                                     # J:AF: NSCC = GSCC; GSCC path from M (2025)
        f[(237, c)] = f'={L(c)}240'
        f[(240, c)] = ('=$F$238' if c == 13 else f'={L(c + 1)}240*(1-$F$239)' if c < 13 else
                       f'={L(c - 1)}240*(1+$F$239)')
    for k, r in enumerate(range(309, 317)):                     # memo: total = price + efficiency + product
        for c in range(11, 15):                                 # legacy 315-316 swap renewables / electricity (fixed)
            a, b = f'{L(c)}{291 + k}', f'{L(c)}{300 + k}'
            f[(r, c)] = f'={a}+{b}+({a}*{b})'
    for k, r in enumerate((319, 320, 321)):
        f[(r, 12)] = f'=Elasticities!G{131 + k}'                # v0.9.0 (L220 fixed): the simple cross-price value
    for r0 in (349, 363):
        for k, nm in enumerate(MI_NEWINV):
            f[(r0 + k, 6)] = mt_setting(nm)
            f[(r0 + k, 7)] = f'=LOWER(CtryCode)&".mit.mancap.pow."&D{r0 + k}&".t."&C{r0 + k}'
    for c in range(11, 21):                                     # memo: growth of the freight path
        f[(378, c)] = f'={L(c)}376/{L(c - 1)}376'
    return f


MI_TYPED = {(5, 6): 'Per scenario (MTInputs row 93)', (218, 6): 'Per scenario (MTInputs row 220)',
            (257, 6): 'Per scenario (MTInputs row 226)', (326, 11): 0.9, (326, 12): 1, (326, 13): 1, (327, 11): 0.15,
            **{(int(c[1:]), 5): v for c, v in MI_ETS.values()}}   # v0.5.2: legacy formulas (other tabs) typed


def build_manual_inputs(wb):
    """v0.5.2: sheet Manual inputs = the whole legacy tab at its legacy addresses (rows 3-378: paste the legacy tab from
    row 3), every block with a note on its title row (column J: what reads it in the prototype, or not read). Legacy values as
    typed inputs (input fill on the input cells); legacy formulas within the sheet kept, formulas of other legacy tabs
    replaced by the prototype equivalent or typed as their legacy default (MI_TYPED, mi_formulas). v0.4.15 (LD56): fiscal
    multipliers J261:U268 (blank = 0)."""
    ws = wb.create_sheet('Manual inputs')
    t = read_csv('legacy_ManualInputs_cells.csv')[1:]
    width = max(int(c) for _r, c, _v, _f in t)
    title(ws, 'Manual inputs: user inputs outside MTInputs, at the legacy CPAT Manual inputs addresses (17 blocks, '
              'rows 5-378; the note on each block\'s title row says what reads it)', width)
    put(ws, 'A1', 'Source: legacy CPAT tab Manual inputs rows 3-378 (data/legacy_ManualInputs_cells.csv), at the legacy '
                  'addresses: paste the legacy tab from row 3. Light green = input cell.', FONT)
    fx = mi_formulas()
    codes = [int(r) for r, c, v, _f in t if c == '7' and v.startswith('mit.') and 60 <= int(r) <= 146]
    inputs = {rc for _r0, _r1, rng, _n in MI_BLOCKS for spec in rng if spec != 'codes' for rc in _mi_ranges(spec)}
    inputs |= {(r, c) for r in codes for c in range(9, 15)}
    for r, c, v, isf in t:
        r, c = int(r), int(c)
        if re.fullmatch(r'0x[0-9a-f]{2}', v):                   # legacy error value (#N/A beyond the GTAP sectors)
            continue
        val = {'True': True, 'False': False}.get(v, num(v))
        if (r, c) in fx:
            val = fx[(r, c)] or f'="{v.split(", ")[0]}, "&$H$148'
        elif (r, c) in MI_TYPED:
            val = MI_TYPED[(r, c)]
        cell = ws.cell(r, c, val)
        cell.font = FONT
        if isinstance(val, float) and r in (14, 59, 77, 95, 101, 107, 113, 119, 127, 135, 149, 220, 230, 236, 334,
                                             348, 362, 374) and c > 8 or (r == 260 and c >= 10):
            cell.number_format, cell.font = '0', FONT_B
    for (r, c), v in MI_TYPED.items():                          # cells legacy leaves empty
        if ws.cell(r, c).value is None:
            ws.cell(r, c, v).font = FONT
    for r, c in inputs:
        ws.cell(r, c).fill = F_INPUT
    for r0, _r1, _rng, note in MI_BLOCKS:                       # block title bars (NORMS 2.7 rule 2)
        for j in range(1, width + 1):
            cell = ws.cell(r0, j)
            cell.fill = F_BAND
            cell.font = FONT_BAND if j == 2 else FONT_BARNOTE
        put(ws, f'J{r0}', note, FONT_BARNOTE, F_BAND)
    for r in range(261, 269):
        for j in range(MULT_MAN_LAGS):
            ws.cell(r, 10 + j).number_format = '0.00'
    ws.column_dimensions['B'].width = 24
    ws.column_dimensions['D'].width = 40
    ws.column_dimensions['E'].width = 14
    ws.freeze_panes = 'A3'


