ECP_HDR = 7                             # v0.4.6: Inputs_ecp: header row of the selected-country table (years); rows 4-6
                                        # helpers: code prefix, regional (EU) ETS rows, row of the EU ETS price, year cols
ECP_CPI = ECP_HDR + 1                   # nominal-to-real factor by year
ECP_R0 = ECP_CPI + 1                    # first code row of the selected country
ECP_R1 = ECP_R0 + len(ECP_CODES) - 1
ECP_YL = L(4 + len(ECP_YEARS))          # last year column of the selected-country table
ECP_X0 = (ECP_R1 + 3, ECP_R1 + 3 + len(ECP_PAIRS) + 2)   # v0.4.12: first rows of the carbon tax and ETS tables


def build_ecp(wb):
    """Existing carbon pricing (v0.1.09; v0.4.6: data step Inputs_ecp reading the legacy ECP tab, kept at its legacy
    addresses; v0.4.12, I7/LD38: as legacy rows 1677-1764, several schemes): the selected country's carbon tax (single
    rate, or fuel rates unless the country has a single price), national ETS and regional EU ETS (where the country's
    EU ETS? flag is Yes or Both), each looked up in its own legacy block; prices x CPI index (real USD of ResultsYear);
    coverage of each data year (blank = 0, as legacy). Two tables by ECP sector x fuel and data year: carbon tax = rate
    x sector coverage x fuel coverage; ETS = national price x coverage + EU price x regional coverage ($/tCO2)."""
    legacy_cells(wb, 'ECP', 'ECP - existing carbon pricing: carbon taxes and ETS (prices nominal USD/tCO2, coverage '
                 'shares) by country, 2015-2025 (codes in column E)', 'legacy sheet ECP (as of Apr 1, 2025; WB Carbon '
                 'Pricing Dashboard, ICAP), extract_legacy_tables.py')
    ws = wb.create_sheet('Inputs_ecp')
    title(ws, 'Existing carbon pricing of the country: carbon tax and ETS prices and coverage (data step; legacy ECP tab)',
          8 + len(ECP_YEARS))
    put(ws, 'A3', 'Selected country (Settings C4): values used by Mitigation (0 where the country has no entry). Prices: '
                  'nominal data x CPI index (real USD/tCO2 of ResultsYear). Coverage of each data year (blank = 0, as '
                  'legacy). ecr = carbon tax rate (all, by fuel: the fuel rate where the country has one and no single '
                  'price, else the single rate); ecs/ecf = its sector / fuel coverage; eer/ees/eef = national ETS; '
                  'rer/res/ref = regional EU ETS (EU price, the country\'s regional coverage). Each code is looked up '
                  'in its legacy block of sheet ECP (columns K:L).', FONT)
    put(ws, 'A4', 'Code prefix of the country', FONT)
    put(ws, 'C4', '=LOWER(CtryCode)&".mit."', FONT)
    put(ws, 'A5', 'Single price? / EU ETS? (sheet ECP general information, columns E and K; legacy row 81 K:L)', FONT)
    put(ws, 'C5', '=IFERROR(INDEX(ECPInfoSgl,MATCH(CtryCode,ECPInfoCode,0))&"","")', FONT)
    put(ws, 'D5', '=IFERROR(INDEX(ECPInfoEU,MATCH(CtryCode,ECPInfoCode,0))&"","")', FONT)
    put(ws, 'A6', 'EU ETS applies (EU ETS? = Yes or Both; legacy row 1695) / column of the embedded year', FONT)
    put(ws, 'C6', '=IF(OR($D$5="Yes",$D$5="Both"),1,0)', FONT, None, '0')
    put(ws, 'D6', '=MATCH(MIN(LastHist,ECPLast),ECPYear,0)', FONT, None, '0')
    yl = L(5 + len(ECP_YEARS))
    cols = ['Code', 'Label', 'Unit', 'Coverage used (last data year)'] + [None] * len(ECP_YEARS) + [
        'Legacy row (ECP)', 'Block: first row', 'Block: last row', 'Legacy key']
    for j, h in enumerate(cols, 1):
        if h:
            put(ws, f'{L(j)}{ECP_HDR}', h, FONT_B, F_INPUT)
    for k, y in enumerate(ECP_YEARS):
        cl = L(5 + k)
        put(ws, f'{cl}{ECP_HDR}', y, FONT_B, F_INPUT, '0')
        put(ws, f'{cl}6', f'=MATCH({cl}${ECP_HDR},ECPAllYear,0)', FONT, None, '0')
        put(ws, f'{cl}{ECP_CPI}', f'=CPIRes/INDEX(WEOVal,MATCH("USA|pcpi",WEOKey,0),MATCH({cl}${ECP_HDR},'
                                  f'WEOYear,0))', FONT, None, '0.0000')
    put(ws, f'B{ECP_CPI}', 'Nominal-to-real factor (CPI index of ResultsYear / year)', FONT)
    put(ws, f'C{ECP_CPI}', 'factor', FONT)
    sec_lab = {'pow': 'power', 'trs': 'transport', 'res': 'buildings', 'ind': 'industry'}
    jr, k0, k1, kk = (L(5 + len(ECP_YEARS) + i) for i in range(4))
    row_of = {code: ECP_R0 + i for i, (code, _k) in enumerate(ECP_CODES)}
    for i, (code, lkey) in enumerate(ECP_CODES):
        r = ECP_R0 + i
        kind, m = code.split('.')
        price = kind in ('ecr', 'eer', 'rer')
        lab = {'ecr': 'Carbon tax rate' + ('' if m == 'all' else f' used, {FNAMES.get(m, m)}'),
               'eer': 'National ETS permit price', 'rer': 'EU ETS permit price (if the EU ETS applies)',
               'ecs': f'Carbon tax coverage, sector {sec_lab.get(m, m)}', 'ees': f'National ETS coverage, sector {sec_lab.get(m, m)}',
               'res': f'EU ETS coverage, sector {sec_lab.get(m, m)}',
               'ecf': f'Carbon tax coverage, fuel {FNAMES.get(m, m)}', 'eef': f'National ETS coverage, fuel {FNAMES.get(m, m)}',
               'ref': f'EU ETS coverage, fuel {FNAMES.get(m, m)}'}[kind]
        put(ws, f'A{r}', code, FONT)
        put(ws, f'B{r}', lab, FONT)
        put(ws, f'C{r}', 'USD/tCO2 real' if price else 'share', FONT)
        a, b = ECP_BLOCKS[kind]
        put(ws, f'{k0}{r}', a, FONT, F_INPUT, '0')
        put(ws, f'{k1}{r}', b, FONT, F_INPUT, '0')
        put(ws, f'{kk}{r}', '="eu.mit.eer.all"' if code == 'rer.all' else f'=$C$4&"{lkey}"', FONT)
        rng = f'INDEX(ECPAllKey,${k0}{r}):INDEX(ECPAllKey,${k1}{r})'
        eu = '*$C$6' if kind in ('rer', 'res', 'ref') else ''
        put(ws, f'{jr}{r}', f'=IFERROR(MATCH(${kk}{r},{rng},0)+${k0}{r}-1,0){eu}', FONT, None, '0')
        if not price:
            put(ws, f'D{r}', f'={yl}{r}', FONT, None, '0.000')
        for k, y in enumerate(ECP_YEARS):
            cl = L(5 + k)
            v = f'N(INDEX(ECPAllVal,${jr}{r},{cl}$6))'
            if kind == 'ecr' and m != 'all':                    # legacy rows 1752-1764: fuel rate, else single rate
                f = f'=IF(OR($C$5="Yes",${jr}{r}=0),{cl}${row_of["ecr.all"]},{v}*{cl}${ECP_CPI})'
            elif price:
                f = f'=IF(${jr}{r}=0,0,{v}*{cl}${ECP_CPI})'
            else:
                f = f'=IF(${jr}{r}=0,0,{v})'
            put(ws, f'{cl}{r}', f, FONT, None, '0.00' if price else '0.000')
    # sector x fuel tables ($/tCO2 real): carbon tax and ETS (legacy rows 1711-1723, 1752-1764)
    for t, (tab, head) in enumerate((('XCT', 'Existing carbon tax by ECP sector | fuel ($/tCO2 real): rate x sector '
                                              'coverage x fuel coverage (legacy rows 1752-1764)'),
                                     ('XETS', 'Existing ETS by ECP sector | fuel ($/tCO2 real): national price x '
                                              'coverage + EU price x regional coverage (legacy rows 1711-1723)'))):
        h = ECP_X0[t] - 1
        put(ws, f'A{h}', head, FONT_B)
        for i, (s_, f_) in enumerate(ECP_PAIRS):
            r = ECP_X0[t] + i
            put(ws, f'A{r}', f'{s_}|{f_}', FONT)
            put(ws, f'B{r}', 'no ECP sector (power types without a fuel)' if s_ == 'none'
                else f'{sec_lab[s_]}, {FNAMES.get(f_, f_)}', FONT)
            put(ws, f'C{r}', 'USD/tCO2 real', FONT)
            for k, y in enumerate(ECP_YEARS):
                cl = L(5 + k)
                g = lambda c_: f'{cl}{row_of[c_]}'
                if s_ == 'none':
                    f = 0
                elif tab == 'XCT':
                    f = f'={g("ecr." + f_)}*{g("ecs." + s_)}*{g("ecf." + f_)}'
                else:
                    f = (f'={g("eer.all")}*{g("ees." + s_)}*{g("eef." + f_)}+{g("rer.all")}*{g("res." + s_)}'
                         f'*{g("ref." + f_)}')
                put(ws, f'{cl}{r}', f, FONT, None, '0.00')
    ws.column_dimensions['A'].width = 16
    ws.column_dimensions['B'].width = 36


L134_UNITS = {'Price increase units, Other oil products': '$/bbl',   # legacy: "$/bbn", default "$/liter"
              'Price increase units, Biomass': '$/GJ'}                # legacy default "$/liter"


def build_mtinputs(wb):
    """MTInputs: the template copied cell by cell (values and styles, rows 1-413, columns A:H), plus one
    'Used for calculation' column per scenario from column J."""
    from copy import copy
    import openpyxl
    src = openpyxl.load_workbook(MT_TEMPLATE)['MTInputs']
    ws = wb.create_sheet('ScenarioDefinition')
    for row in src.iter_rows(min_row=1, max_row=src.max_row, max_col=8):
        for c in row:
            d = ws.cell(c.row, c.column, c.value)
            if c.has_style:
                d.font, d.fill, d.border = copy(c.font), copy(c.fill), copy(c.border)
                d.alignment, d.number_format = copy(c.alignment), c.number_format
    for col, dim in src.column_dimensions.items():
        ws.column_dimensions[col].width = dim.width
        ws.column_dimensions[col].hidden = dim.hidden
    unit_fix = {}                                          # v0.8.3: legacy bug L134, price-increase unit labels
    for r in range(8, src.max_row + 1):
        lab = str(src.cell(r, 2).value or '')
        for k, u in L134_UNITS.items():
            if lab.startswith(k):
                unit_fix[r] = u
                for j in (6, 7):
                    ws.cell(r, j).value = u
    assert len(unit_fix) == len(L134_UNITS), unit_fix
    names = {src.cell(r, 8).value: r for r in range(8, src.max_row + 1) if src.cell(r, 8).value}
    rows_ = [(r, src.cell(r, 8).value, unit_fix.get(r, src.cell(r, 6).value)) for r in range(8, src.max_row + 1)]
    put(ws, f'B{MT_TR0}', 'Transportation: engineer road model policies (legacy Dashboard rows 61-98, all off '
                          'by default; used when TrModel = Engineer)', FONT_B)
    for i, (k, n, lab, unit) in enumerate(TR_MT):          # v0.3.5: rows after the template (section 5b)
        r, v = MT_TR0 + 1 + i, _tr_num(TR_PAR[k]['value'])
        for j, x in zip(range(2, 9), (lab, unit, None, None, v, v, n)):
            d = ws.cell(r, j, x)
            t = src.cell(MT_NAMES['TrModel'], j)
            d.font, d.fill, d.border, d.alignment = copy(t.font), copy(t.fill), copy(t.border), copy(t.alignment)
            d.number_format = '0' if unit == 'year' else 'General'
        names[n] = r
        rows_.append((r, n, v))
    put(ws, f'B{MT_PW0}', 'Inputs the prototype adds, per scenario: power (v0.5.4; legacy fixes) and the scope of carbon-tax '
                          'coverage of biomass and of the subsidy and price-control phase-outs (v0.5.6; were Constants)', FONT_B)
    for i, (n, lab, unit, v) in enumerate(PW_MT_NEW):     # v0.5.4: power rows after the transport rows
        r = MT_PW0 + 1 + i
        for j, x in zip(range(2, 9), (lab, unit, None, None, v, v, n)):
            d = ws.cell(r, j, x)
            t = src.cell(MT_NAMES['RenSubsidyAddPhaseoutYrs'], j)
            d.font, d.fill, d.border, d.alignment = copy(t.font), copy(t.fill), copy(t.border), copy(t.alignment)
            d.number_format = '0' if unit == 'year' else 'General'
        names[n] = r
        rows_.append((r, n, v))
    for k in MT_SCENARIO_INPUTS[1]:
        assert k in names, k
    flags = {1: 'Baseline (stored once)', 2: 'Live (batch target)'}
    columns = [(g, gname, MT_SCENARIO_INPUTS[g]) for g, gname, _ in SCENARIOS] + \
        [(n, nm, edits) for n, nm, _run, edits in DEFINITIONS]
    runs = {n: run for n, _nm, run, _e in DEFINITIONS}
    for g, gname, edits in columns:
        col = MT_COL0 + g - 1
        cl = L(col)
        put(ws, f'{cl}{MT_ROW_RUN}', runs.get(g, flags.get(g)), FONT_B, F_INPUT if g in runs else None)
        put(ws, f'{cl}{MT_ROW_SCEN}', g if g == 1 else f'={L(col - 1)}{MT_ROW_SCEN}+1', FONT_B,
            F_INPUT if g == 1 else None, '0')
        put(ws, f'{cl}{MT_ROW_NAME}', gname, FONT_B, F_INPUT)
        put(ws, f'{cl}{MT_ROW_SHORT}', SHORT_NAMES.get(g, f'S{g}'), FONT_B, F_INPUT)   # v0.6.7: legends
        c = put(ws, f'{cl}7', 'Used for calculation', FONT_B, F_INPUT)
        c.alignment = Alignment(wrap_text=True)
        for r, name, used in rows_:
            if r == 10:
                val = f'={cl}${MT_ROW_SCEN}'          # Scenario ID
            elif r == 12:
                val = f'={cl}${MT_ROW_NAME}'          # Scenario name
            elif name in edits or r in edits:
                val = edits[name] if name in edits else edits[r]
            else:
                val = used
            if val is None:
                continue
            fnt = Font(name='Arial', size=10, bold=True, color='C00000') if (name in edits or r in edits) else FONT
            put(ws, f'{cl}{r}', val, fnt, F_INPUT)
        ws.column_dimensions[cl].width = 16
    ws.column_dimensions['I'].width = 3
    put(ws, f'H{MT_ROW_SHORT}', 'Short name (chart legends)', FONT_B)
    put(ws, f'{L(MT_COL0)}3', 'Scenario columns: short name in row 2, number in row 5, name in row 6; red = changed '
                              'from the template value. J = baseline, K = live policy scenario (Mitigation group 2).',
        FONT_B)
    put(ws, f'{L(MT_COL0 + 2)}3', 'Scenario definitions: row 4 Run? = Yes for the batch run (button Run stored '
                                  'scenarios copies each into column K, runs it and stores the results in '
                                  'StoredOutputs). Copy the last definition one column to the right to add one.', FONT_B)
    last_def = MT_COL0 + len(columns) - 1          # v0.6.7: blank scenario columns grouped and collapsed
    for c_ in range(last_def + 1, CI_(MT_LAST) + 1):
        ws.column_dimensions[L(c_)].outline_level = 1
        ws.column_dimensions[L(c_)].hidden = True
    ws.freeze_panes = 'D8'


def fix_outline_levels(path):
    """openpyxl drops sheetFormatPr/@outlineLevelCol; Excel needs it to size the outline bar for the hidden
    D:G column group. Add it to the sheet that has a row outline (Mitigation)."""
    import shutil
    import zipfile
    tmp = path + '.tmp'
    with zipfile.ZipFile(path) as zin, zipfile.ZipFile(tmp, 'w', zipfile.ZIP_DEFLATED) as zout:
        for item in zin.infolist():
            data = zin.read(item.filename)
            if item.filename.startswith('xl/worksheets/sheet') and re.search(rb'outlineLevelRow="\d+"', data) \
                    and b'outlineLevelCol' not in data:          # present when the workbook was saved before
                data = re.sub(rb'(outlineLevelRow="\d+")', rb'\1 outlineLevelCol="1"', data, count=1)
            zout.writestr(item, data)
    shutil.move(tmp, path)


# ---------------------------------------------------------------- Mapping, Settings, Inputs, Variables
def build_mapping(wb):
    ws = wb.create_sheet('Mapping')
    title(ws, 'Mapping: subsectors, fuels and policy keys to CPAT parameter groups', 13)
    put(ws, f'A{MAP_SUB0 - 2}', 'Subsectors', FONT_B)
    for j, h in enumerate(['Code', 'Name', 'Group', 'Elasticity sector', 'EF sector', 'Coal/gas price sector',
                           'Feebate sector', 'Coverage position', 'ECP sector', 'Balances flow 1', 'Sign 1',
                           'Balances flow 2', 'Sign 2'], 1):            # v0.4.5: legacy Mitigation rows 529-601
        put(ws, f'{L(j)}{MAP_SUB0 - 1}', h, FONT_B, F_INPUT)
    for i, s in enumerate(SUBSECTORS):
        r = MAP_SUB0 + i
        b = SUB_BAL[s[0]] + ('', 0) if len(SUB_BAL[s[0]]) == 2 else SUB_BAL[s[0]]
        for j, v in enumerate(list(s) + [COV_SECTORS.index(s[0]) + 1, ECP_SECTOR[s[0]]] + list(b), 1):
            put(ws, f'{L(j)}{r}', v, FONT, F_INPUT if j > 2 else None)
    for i, (code, name) in enumerate(EXTRA_LABELS):
        put(ws, f'A{MAP_SUB1 + 1 + i}', code)
        put(ws, f'B{MAP_SUB1 + 1 + i}', name)
    units = {r[0]: float(r[1]) for r in read_csv('fuel_units.csv')[1:]}
    put(ws, f'A{MAP_FUEL0 - 2}', 'Fuels', FONT_B)
    for j, h in enumerate(['Code', 'Name', 'Elasticity fuel', 'AEEI fuel', 'Price sector rule', 'Price unit',
                           'GJ per price unit', 'Fuel position', 'Price fuel (section 2)'], 1):
        put(ws, f'{L(j)}{MAP_FUEL0 - 1}', h, FONT_B, F_INPUT)
    for i, f in enumerate(FUELS):
        for j, v in enumerate(list(f) + [units[f[0]], i + 1, PRICE_FUEL_OF.get(f[0], f[0])], 1):
            put(ws, f'{L(j)}{MAP_FUEL0 + i}', v, FONT, F_INPUT if j > 2 else None)
    for i, (code, name) in enumerate(FUEL_EXTRA):
        put(ws, f'A{MAP_FUEL1 + 1 + i}', code)
        put(ws, f'B{MAP_FUEL1 + 1 + i}', name)
