    for j, h in enumerate(['Code', 'Position', 'GHGs column', 'Legacy header (gas)'], 1):
        put(ws, f'{L(j)}{MAP_GHG0 - 1}', h, FONT_B)
    for i, code in enumerate(GHG_COLS):
        for j, v in enumerate([code, i + 1, L(GHG_FIRST + i), gh[GHG_FIRST - 1 + i]], 1):
            put(ws, f'{L(j)}{MAP_GHG0 + i}', v, FONT, F_INPUT if j == 1 else None)
    assert fg == [f for f, *_ in FEEBATE_SECTORS]
    ws.column_dimensions['B'].width = 26
    for col in 'CDEFGHI':
        ws.column_dimensions[col].width = 16


