def legacy_diff_class(k, d):
    """v0.4.2: register code(s), bug or issue, status of LegacyDiff row k (register issues_register: L = legacy bug,
    I = issue, LD = simplification or feature not yet modelled; NORMS 0)."""
    import issues_register as IR
    text = ' '.join(str(x) for x in d)
    codes = sorted(set(re.findall(r'\b([LI]\d{1,3})\b', text)), key=lambda c: (c[0], int(c[1:])))   # v0.5.4: L100+
    t = d[5]
    if t in IR.LD_TYPES:
        codes.append(f'LD{k}')
    if t == 'Bug fix':
        kind, status = 'Bug (legacy)', 'Open: kept as legacy' if set(codes) & IR.BUGS_REPLICATED else 'Fixed'
    elif t == 'Same':
        kind, status = 'Same as legacy', 'n/a'
    elif t == 'Not yet':
        kind, status = 'Not yet modelled', 'Open'
    elif t in ('Simplification', 'To check (bucket 5)'):
        kind, status = 'Issue', 'Replicated' if k in IR.LD_REPLICATED else 'Open'
    else:
        kind, status = 'Issue (departure)', 'Accepted: user decision'
    iss = [c for c in codes if c.startswith('I')]
    if iss and iss[0] in IR.ISSUE_STATUS:
        kind, status = 'Issue', IR.ISSUE_STATUS[iss[0]][1]
    return ', '.join(codes), kind, status


LD_HEAD = ['Type', 'Area', 'This model', 'Legacy CPAT', '#', 'Why', 'Effect', 'Register code', 'Bug or issue',
           'Status']


def build_legacy_diff(wb):
    ws = wb.create_sheet('LegacyDiff')
    title(ws, 'Differences with legacy CPAT', len(LD_HEAD))
    put(ws, 'A3', 'Every difference with legacy CPAT. Register code: L = legacy bug (fixed here unless stated), DB = '
                  'data bug, I = issue, DI = data issue (replicated), LD = simplification or feature not yet modelled '
                  f'(this row). Master list: Tracking_Legacy_Bugs_v{VERSION}.xlsx; bugs: Legacy_CPAT_Bugs_v{VERSION}.docx; '
                  'lists ../BUGS.md and ../ISSUES.md (NORMS 0). Type Assumption: data set by assumption (bright yellow).',
        FONT)
    for j, h in enumerate(LD_HEAD, 1):
        c = put(ws, f'{L(j)}4', h, FONT_B)
        c.alignment = Alignment(wrap_text=True, vertical='top')
    for i, row in enumerate(LEGACY_DIFFS, 5):
        k = i - 4
        area, legacy, model, why, effect, typ = row
        vals = [typ, area, model, legacy, k, why, effect, *legacy_diff_class(k, row)]
        for j, v in enumerate(vals, 1):
            hi = typ == 'Assumption' and j == 1
            c = put(ws, f'{L(j)}{i}', v, FONT_CHANGED if hi else FONT, F_CHANGED if hi else None)
            c.alignment = Alignment(wrap_text=True, vertical='top')
    ws.freeze_panes = 'C5'


