def mto_row(g, k):
    """Row of indicator k (0-based) in the block of scenario g."""
    return MTO_R0 + (g - 1) * MTO_BLOCK + 1 + k


def build_mtoutputs(wb):
    """MTOutputs: one row block per scenario; each row finds its output code on Mitigation (code column of the
    scenario = first column of row 5 holding the scenario number) and reads the year columns by offset."""
    ws = wb.create_sheet('LiveOutputs')
    ny = len([BASE_YEAR] + YEARS)
    last = MTO_C0 + ny - 1
    title(ws, f'MTOutputs - key results by scenario (read from Mitigation by output code)', last)
    put(ws, 'A3', 'One block per scenario: the number in column E of the block header drives every row. To add a '
                  'scenario, copy the last block (header to blank row) and paste it directly below: the number goes '
                  'up by one. Rows: add a code stem in column B and copy a row\'s formulas. Values follow Mitigation.',
        FONT)
    for j, h in enumerate(['Output code', 'Code stem', 'Description (from Mitigation)', 'Unit', 'Scenario'], 1):
        put(ws, f'{L(j)}4', h, FONT_B, F_INPUT)
    hc, hr = L(last + 1), L(last + 2)                       # v0.1.07: lookup positions (helper columns)
    put(ws, f'{hc}4', 'Mitigation code column', FONT_B, F_INPUT)
    put(ws, f'{hr}4', 'Mitigation row', FONT_B, F_INPUT)
    ha = L(last + 3)                                        # v0.7.2 (codes R8): the v0.7.1 stem of a renamed code
    put(ws, f'{ha}4', ALIAS_HEAD, FONT_B, F_INPUT)
    for k in range(ny):
        col = L(MTO_C0 + k)
        put(ws, f'{col}4', '=Settings!$C$7' if k == 0 else f'={L(MTO_C0 + k - 1)}4+1', FONT_B,
            F_BASE if k == 0 else (F_LIGHT if k == ny - 1 else F_INPUT), '0')
    for g, gname, _ in SCENARIOS:
        h = MTO_R0 + (g - 1) * MTO_BLOCK
        band(ws, h, '', last)
        put(ws, f'A{h}', 'Scenario block', FONT_BAND, F_BAND)
        put(ws, f'E{h}', 1 if g == 1 else f'=E{h - 1}+1', FONT_BAND, F_BAND, '0')
        put(ws, f'C{h}', (f'=INDEX(ScenarioDefinition!${L(MT_COL0)}${MT_ROW_NAME}:${MT_LAST}${MT_ROW_NAME},'
                          f'MATCH($E{h},ScenarioDefinition!${L(MT_COL0)}${MT_ROW_SCEN}:${MT_LAST}${MT_ROW_SCEN},0))'),
            FONT_BAND, F_BAND)
        for k, (stem, fmt) in enumerate(MTO_INDICATORS):
            r = h + 1 + k
            put(ws, f'A{r}', f'=LOWER(Settings!$C$4)&"."&$B{r}&"."&$E{r}', FONT, F_CODE)
            put(ws, f'B{r}', stem, FONT, F_INPUT)
            put(ws, f'C{r}', f'=IFERROR(INDEX(MitDesc,${hr}{r}),"code not found")')
            put(ws, f'D{r}', f'=IFERROR(INDEX(MitUnit,${hr}{r}),"")')
            put(ws, f'E{r}', f'=E{r - 1}', FONT, None, '0')
            put(ws, f'{hc}{r}', f'=MATCH($E{r},MitScen,0)', FONT, None, '0')
            put(ws, f'{hr}{r}', f'=MATCH($A{r},INDEX(MitAll,0,${hc}{r}),0)', FONT, None, '0')
            if stem in MTO_ALIAS:
                put(ws, f'{ha}{r}', MTO_ALIAS[stem], FONT)
            for kk in range(ny):
                col = L(MTO_C0 + kk)
                put(ws, f'{col}{r}', f'=IFERROR(INDEX(MitAll,${hr}{r},${hc}{r}+1+{col}$4-Settings!$C$7),"")', FONT,
                    F_BASE if kk == 0 else None, fmt)
        r = h + MTO_BLOCK - 1
        put(ws, f'E{r}', f'=E{r - 1}', Font(name='Arial', size=10, color='BFBFBF'), None, '0')
    ws.freeze_panes = f'{L(MTO_C0)}5'
    for col, w in {'A': 30, 'B': 22, 'C': 52, 'D': 12, 'E': 8}.items():
        ws.column_dimensions[col].width = w
    for k in range(ny):
        ws.column_dimensions[L(MTO_C0 + k)].width = 9
    ws.column_dimensions[hc].width = 11
    ws.column_dimensions[hr].width = 11
    ws.column_dimensions[ha].width = 24
    ws.sheet_view.zoomScale = 85


_RC_TOK = re.compile(r"(?<![A-Za-z_\d\.!$])(\$?)([A-Z]{1,3})(\$?)(\d+)(?![\d\(A-Za-z_])")


def rel_formula(f, r, c):
    """v0.4.2: formula in relative (R1C1-like) form: equal for rows that hold the same formula pattern."""
    from openpyxl.utils import column_index_from_string as ci

    def sub(m):
        cd, col, rd, row = m.groups()
        return (f'R{row}' if rd else f'R[{int(row) - r}]') + (f'C{ci(col)}' if cd else f'C[{ci(col) - c}]')
    return ''.join(x if x.startswith('"') else _RC_TOK.sub(sub, x) for x in re.split(r'("[^"]*")', f))


def row_list(rows):
    """[257, 258, 259, 435] -> '257-259, 435'."""
    out, rows = [], sorted(rows)
    a = b = rows[0]
    for r in rows[1:] + [None]:
        if r == b + 1:
            b = r
            continue
        out.append(f'{a}-{b}' if b > a else f'{a}')
        if r is not None:
            a = b = r
    return ', '.join(out)


def section_of(r):
    """Number of the Mitigation section that holds row r."""
    bands = sorted([(R_SEC0, '0'), (B_POL, '1'), (B_PRI, '2'), (B_POW, '3'), (B_TR, '5b'), (B_LK, '6b'), (B_RES, '11'),
                    (B_REV, '12'), (B_EMI, '13'), (B_GHG, '14'), (B_AP, '15'), (B_GDP, '16'), (B_CPR, '17'),
                    (B_WEL, '18')] + [(SEC_BAND[g], str(n)) for n, g, _t in SECTIONS])
    return [n for b, n in bands if b <= r][-1]


def lambda_groups():
    """v0.4.2: LAMBDA_ROWS grouped by variable, LAMBDA and relative formula, in the order of the sheet."""
    col = group_cols(1)[2][-1]
    groups = {}
    for r, var, fu, sec, f in sorted(LAMBDA_ROWS):
        m = re.match(r'=([A-Z0-9]+)\(', f)
        key = (var, m.group(1) if m else '', rel_formula(f, r, col))
        groups.setdefault(key, []).append((r, fu, sec, f))
    return sorted(((v[0][0], k, v) for k, v in groups.items()))


def build_lambdas_sheet(wb):
    """Sheet Lambdas (v0.2.3; v0.4.2 condensed): the LAMBDA formula of every calculated row, the formula of the LAMBDA
    year 2041 of scenario 1. Rows with the same formula pattern share a line: column D lists them, column C is the
    formula of the first; copied to any listed row (Excel adjusts the references) it is that row's formula."""
    ws = wb.create_sheet('Lambdas')
    title(ws, f'Lambdas: the LAMBDA formula of every calculated row (LAMBDA test group {LAMBDA_GROUP})', 7)
    put(ws, 'A3', f'For readers and for the check. Each line is one formula pattern: the variable, its named LAMBDA '
                  f'(Name Manager, {len(LAMBDAS)} in all), its formula in column {L(group_cols(1)[2][-1])} ({LAST_YEAR}) '
                  'for the first row listed, and the Mitigation rows that hold the same formula (relative '
                  f'references). Group {LAMBDA_GROUP} of Mitigation holds these formulas in every year; they give the '
                  'same results as the plain formulas of groups 1 and 2 (tested by the spacer column and by '
                  'check_quick.py). Sorted by '
                  'Mitigation row, i.e. in the order of the build-up.', FONT)
    for j, h in enumerate(['Variable', 'LAMBDA', 'Formula (first row listed, without =)', 'Mitigation rows',
                           'Rows', 'Members (fuel | sector)', 'Section'], 1):
        put(ws, f'{L(j)}4', h, FONT_B)
    for i, (r0, (var, name, _rel), rows) in enumerate(lambda_groups(), 5):
        mem = list(dict.fromkeys(f'{fu or "-"} | {sec or "-"}' for _r, fu, sec, _f in rows))
        memtxt = '; '.join(mem[:6]) + (f'; ... ({len(mem)})' if len(mem) > 6 else '')
        for j, v in enumerate([rn_var(var), name, rows[0][3][1:], row_list([x[0] for x in rows]), len(rows), memtxt,
                               section_of(r0)], 1):
            c = put(ws, f'{L(j)}{i}', v, FONT_LAMBDA if j == 3 else FONT)
            c.alignment = Alignment(wrap_text=j in (3, 4, 6), vertical='top')
    ws.freeze_panes = 'A5'



def build_dist_charts(wb, ws, r0):
    """v0.6.0: distribution charts of legacy Dashboard (rows 322-426), from Distribution group 2 (the live policy
    scenario; change the scenario number there to chart another)."""
    from openpyxl.chart import BarChart, LineChart, Reference, ScatterChart, Series
    d = wb['Distribution']
    _c, base, decs, _sp = dist_group_cols(2)
    put(ws, f'A{r0}', 'Distribution (legacy Dashboard charts; Distribution group 2, analysis year and statistic of its '
                      'header): deciles across, labels from MTInputs QuantilesLCU', FONT_B)
    dcat = Reference(d, min_col=decs[0], max_col=decs[-1], min_row=DROW['dlab'], max_row=DROW['dlab'])
    dser = lambda key, title_: Series(Reference(d, min_col=decs[0], max_col=decs[-1], min_row=DROW[key],
                                                max_row=DROW[key]), title=title_)
    vser = lambda k0, k1, title_: Series(Reference(d, min_col=base, max_col=base, min_row=DROW[k0], max_row=DROW[k1]),
                                         title=title_)
    charts = []

    def bars(title_, ytitle, keys, stacked=False, cats=dcat):
        ch = BarChart()
        ch.type, ch.title, ch.y_axis.title = 'col', title_, ytitle
        if stacked:
            ch.grouping, ch.overlap = 'stacked', 100
        for k, t_ in keys:
            ch.series.append(dser(k, t_))
        ch.set_categories(cats)
        charts.append(ch)
    bars('Price effects by decile', '% of consumption', [('def.tot', 'Direct'), ('ief.tot', 'Indirect'),
                                                         ('tef.ove', 'Total')])
    bars('Direct effect by fuel', '% of consumption', [(f'def.{f}', lab) for f, lab, *_x in DIST_FUELS], True)
    bars('Price effects, recycling and net effect', '% of consumption',
         [('tef.ove', 'Price effects'), ('pit.ove', 'PIT reduction'), ('pui.ove', 'Public investment'),
          ('cts.ove', 'Current spending'), ('tgt.ove', 'Targeted transfer'), ('net.ove', 'Net effect')])
    bars('Total effect: urban and rural', '% of consumption', [('tef.urb', 'Urban'), ('tef.rur', 'Rural'),
                                                               ('tef.ove', 'Overall')])
    bars('Per-capita effect and net effect', 'local currency per capita', [('atef.tot.ove', 'Price effects'),
                                                                           ('anet.tot.ove', 'Net effect')])
    bars('Horizontal distribution: total effect', '% of consumption',
         [('htef.ove.p25', '25th percentile'), ('tef.ove', 'Chosen statistic'), ('htef.ove.p75', '75th percentile')])
    bars('Budget shares of household fuels', '% of consumption',
         [(f'bsh.{f}.ove', lab) for f, lab, *_x in DIST_FUELS], True)
    ln = LineChart()
    ln.title, ln.y_axis.title = 'Cumulative share of the compensation', '%'
    for s_, t_ in DIST_SAMPLES:
        ln.series.append(dser(f'ccomp.{s_}', t_))
    ln.set_categories(dcat)
    charts.append(ln)
    sc = ScatterChart()
    sc.title, sc.x_axis.title, sc.y_axis.title = 'Lorenz curves (overall)', 'cumulative population, %', \
        'cumulative consumption, %'
    xs = Reference(d, min_col=decs[0], max_col=decs[-1], min_row=DROW['lzp.ove'], max_row=DROW['lzp.ove'])
    for k, t_ in (('lz0.ove', 'Baseline'), ('lzx.ove', 'After price effects'), ('lzi.ove', 'After recycling'),
                  ('lzp.ove', 'Equality')):
        se = Series(Reference(d, min_col=decs[0], max_col=decs[-1], min_row=DROW[k], max_row=DROW[k]), xs, title=t_)
        sc.series.append(se)
    charts.append(sc)
    tb = BarChart()
    tb.type, tb.title, tb.y_axis.title = 'bar', f'Top {DIST_TOPN} sectors: output-price change', 'fraction'
    tb.series.append(vser('rkp.1', f'rkp.{DIST_TOPN}', 'Output price'))
    tb.set_categories(Reference(d, min_col=base, max_col=base, min_row=DROW['rkn.1'], max_row=DROW[f'rkn.{DIST_TOPN}']))
    charts.append(tb)
    cb = BarChart()
    cb.type, cb.title, cb.y_axis.title = 'col', 'CPAT production sectors: price change', 'fraction'
    for k, t_ in (('ppici', 'Input costs'), ('ppic', 'Output price')):
        cb.series.append(vser(f'{k}.{DIST_CPAT[0]}', f'{k}.{DIST_CPAT[-1]}', t_))
    cb.set_categories(Reference(d, min_col=2, max_col=2, min_row=DROW[f'ppic.{DIST_CPAT[0]}'],
                                max_row=DROW[f'ppic.{DIST_CPAT[-1]}']))
    charts.append(cb)
    for i, ch in enumerate(charts):
        ch.height, ch.width = 7.5, 15
        ch.x_axis.delete = False
        ch.y_axis.delete = False
        ch.legend.position = 'b'
        ws.add_chart(ch, f'{"A" if i % 2 == 0 else "K"}{r0 + 2 + (i // 2) * 16}')


