def inputs_lookup(code, r):
    return f'INDEX(Inputs!${IC[code]}${IN_R0}:${IC[code]}${IN_R1},MATCH($B{r}&"|"&$C{r},Inputs!$A${IN_R0}:$A${IN_R1},0))'


def pol_range(col, key0, n):
    """Absolute-row range of n consecutive Section-1 rows starting at key0, in column col."""
    r0 = R_POL[key0]
    return f'{col}${r0}:{col}${r0 + n - 1}'


def call(name, *args):
    assert len(args) == len(LAMBDAS[name][0]), name
    return f'{name}(' + ','.join(args) + ')'


def year_of(c):
    return BASE_YEAR + (c - COL_G0) % GW - 1


def calc_formula(var, r, col, prev, is_base, use_lambda):
    """Sector-section cell of variable var in row r (column col; prev = previous year column)."""
    o = lambda v: f'{col}{r - VOFF[var] + VOFF[v]}'          # same fuel, other variable, this column
    op = lambda v: f'{prev}{r - VOFF[var] + VOFF[v]}'        # same fuel, other variable, previous column
    exf = lambda pc: f'INDEX({pol_range(col, "exf.all", 2)},${pc}{r})'   # v0.5.1 (D16, I50): exemption factor
    if var == 'ctxnew':     # carbon tax rate of the sector x EF x fuel coverage (x exemption factor, v0.5.1)
        a = (f'INDEX({pol_range(col, "ctr.pow", len(COV_SECTORS))},$F{r})', f'$D{r}',
             f'INDEX({pol_range(col, "fc.coa", NF)},$E{r})', exf('G'))
        return '=' + (call('CARBONTAX', *a) if use_lambda else '*'.join(a))
    if var == 'ets':        # ETS cost rate of the sector x EF (x exemption factor, v0.5.1)
        a = (f'INDEX({pol_range(col, "etr.pow", len(COV_SECTORS))},$E{r})', f'$D{r}', exf('F'))
        return '=' + (call('ETSCOST', *a) if use_lambda else '*'.join(a))
    if var == 'ntx':        # v0.9.0 (R3.10): the block's new excise ntxb (fuel price reform + Pigouvian tax, netted)
        a = (f'INDEX({pol_range(col, "ntxb." + PRICE_FUELS[0][0], len(PRICE_FUELS))},$D{r})', f'$E{r}', exf('F'))
        return '=' + (call('NEWEXCISE', *a) if use_lambda else f'{a[0]}/{a[1]}*{a[2]}')
    if var == 'nce':
        a = (o('ctxnew'), o('ets'), o('ntx'))
        return '=' + (call('NEWPOLICY', *a) if use_lambda else '+'.join(a))
    if var in ('xcp', 'xcpd'):  # v0.1.09: existing carbon pricing, level or change; v0.4.12: sector | fuel tables
        a = xcarbon_args(col, f'$D{r}', f'$E{r}', f'$F{r}' if var == 'xcpd' else '0')
        return '=' + (call('XCARBON', *a) if use_lambda else xcarbon_plain(a))
    if var in ('csw', 'pcw'):  # v0.4.16 (LD18): consumer subsidy / price-control wedge (v0.9.0, R7.3: producer: none)
        a = (f'INDEX({pv_range({"csw": "pcsw", "pcw": "ppcw"}[var], col)},$D{r})',)
        return '=' + (call('BLOCKWEDGE', *a) if use_lambda else a[0])
    if var == 'atp':
        rpb = f'INDEX({pv_range("rpb", col)},$D{r})'
        pol = f'{o("nce")}+{o("xcpd")}+{o("csw")}+{o("pcw")}'   # v0.4.16: + the phase-out wedges (v0.9.0, R7: no psw)
        return (f'={call("POSTTAX", rpb, pol, f"$E{r}")}' if use_lambda
                else f'=MAX({rpb}+({pol})*(1+$E{r}),PriceFloor)')
    if var == 'aef':        # v0.4.13 (LD21): AEEI factor with the additional efficiency of the row's group (section 1)
        a = (f'$D{r}', f'INDEX({col}${R_POL[ADDEFF_PARAMS[0]]}:{col}${R_POL[ADDEFF_PARAMS[-1]]},$E{r})', f'$F{r}')
        return '=' + (call('AEEIFACTOR', *a) if use_lambda else f'(1/(1+{a[0]}+{a[1]}))^(1+{a[2]})')
    if var == 'shp':        # shadow price of the sector ($/tCO2, section 1) x EF
        a = (f'INDEX({pol_range(col, "shpx.pow", len(COV_SECTORS))},$E{r})', f'$D{r}')
        return '=' + (call('SHADOWGJ', *a) if use_lambda else f'{a[0]}*{a[1]}')
    if var == 'co2':
        a = (o('ener'), 'Settings!$C$13', f'$D{r}')
        return '=' + (call('EMISSIONS', *a) if use_lambda else '*'.join(a))
    if var == 'ch4':                         # v0.2.8: combustion CH4 (kt), EF path from the base year to EFEndYear
        return '=' + nonco2_formula(o('ener'), r, col, use_lambda)
    if var in ('rex', 'rvt'):  # v0.4.15 (LD37): excise revenue (ntx) and VAT revenue (existing + on the price changes)
        k = 'Settings!$C$13'
        rate = (o('ntx') if var == 'rex' else
                f'INDEX({pv_range("vat", col)},$D{r})+({o("xcpd")}+{o("nce")}+{o("csw")}+{o("pcw")})*$E{r}')
        return '=' + (call('REVENUE', o('ener'), k, rate) if use_lambda else f'{o("ener")}*{k}*({rate})')
    if var in REV_VARS:
        pr = lambda v: f'INDEX({pv_range(v, col)},$D{r})'
        k = 'Settings!$C$13'
        if var == 'rtx':                     # v0.1.09: + change in existing carbon pricing (incl. VAT)
            rate = f'{pr("etx")}+{pr("vat")}+{o("xcpd")}*(1+$E{r})'
        elif var == 'rxcp':                  # v0.1.09: existing carbon pricing revenue (memo, level)
            rate = o('xcp')
        elif var == 'rsub':
            rate = pr('esub')
        elif var == 'rsr':                   # v0.4.16 (LD18): subsidy reform revenue: wedges incl. VAT
            rate = f'({o("csw")}+{o("pcw")})*(1+$D{r})'   # v0.9.0 (R7.3): no producer wedge (in the supply cost)
        else:
            a = (o('ctxnew'), o('ntx'), o('ets'), f'{col}${R_POL["ets.rf"]}', o('nce'), f'$D{r}')
            rate = call('NEWREVRATE', *a) if use_lambda else f'{a[0]}+{a[1]}+{a[2]}*{a[3]}+{a[4]}*{a[5]}'
        if use_lambda:
            return '=' + call('REVENUE', o('ener'), k, rate)
        return f'={o("ener")}*{k}*({rate})'
    if var == 'ener':       # v0.3.5: the engineer road model (section 5b) where TrModel = Engineer, else enel
        el_ = o('enel')
        if r == SUB_HEAD['rod'] + VOFF['ener'] + [x[0] for x in FUELS].index('bio'):
            el_ = f'{col}${R_TR["trbe.bio"]}'   # v0.9.0 (R10.4): road biomass = the three biofuels (section 5b)
        a = (f'$D{r}', f'{col}${R_TR["tr.sw"]}', f'{col}${R_TR[TR_RES[0]]}:{col}${R_TR[TR_RES[-1]]}', el_,
             f'{col}${R_LK[LK_RES[0]]}:{col}${R_LK[LK_RES[-1]]}', f'$E{r}')   # v0.5.1 (D9): + leakage (section 6b)
        return '=' + (call('ROADSWITCH', *a) if use_lambda else lambda_plain('ROADSWITCH', a))
    if var == 'enel':
        if is_base:
            return '=' + inputs_lookup('f0', r)
        if use_lambda:
            return (f'=FUELUSE({prev}{r},{o("atp")},{op("atp")},{o("shp")},{op("shp")},{col}${R_GDPI},'
                    f'$D{r},$E{r},$F{r},{o("aef")},{col}${R_SHOCK})')
        ratio = f'({o("atp")}/{op("atp")})'
        eff = f'(({o("atp")}+{o("shp")})/({op("atp")}+{op("shp")}))'
        return f'={prev}{r}*{o("aef")}*(1+{col}${R_GDPI})^$D{r}*{ratio}^$E{r}*{eff}^$F{r}*{col}${R_SHOCK}'
    raise ValueError(var)


def xcarbon_args(col, ef, row, emb):
    """v0.4.12 (I7/LD38): arguments of XCARBON: EF (or CO2), the carbon tax and ETS of the row's ECP sector | fuel in the
    data column of the year (Inputs_ecp tables), their scenario factors (section 1) and the embedded level."""
    p = lambda k: f'{col}${R_POL[k]}'
    return (ef, f'INDEX(XCTVal,{row},{p("xct.c")})', p('xct.p'), f'INDEX(XETSVal,{row},{p("xct.c")})', p('xets.p'), emb)


def xcarbon_plain(a):
    return f'{a[0]}*({a[1]}*{a[2]}+{a[3]}*{a[4]}' + (')' if a[5] == '0' else f'-{a[5]})')


def nonco2_formula(use, r, col, use_lambda):
    """v0.2.8: fuel use x CH4 EF (t/ktoe; D base year, E EFEndYear, linear, flat after) / tPerKt."""
    y = f'{col}${R_YEAR}'
    if use_lambda:
        return call('NONCO2', use, f'$D{r}', f'$E{r}', y)
    return f'{use}*($D{r}+($E{r}-$D{r})*EFFinShare*({y}-BaseYr)/(EFEndYear-BaseYr))/tPerKt'   # v0.8.4 (I98)


LH = 'Settings!$C$10'                   # last historical price year


def gp_range(col):
    return f'{col}${R_GP0}:{col}${R_GP0 + len(GP_ROWS) - 1}'


def gp_formula(r, col, var='gp'):
    """International prices (v0.1.07 in steps): gp.src = source key (MTInputs selector without the *); gp.adj = 1 (no
    adjustment), 2 (High) or 3 (Low); gpn = Prices_int value of the source (nominal; 1 without commodity key);
    gp = gpn x deflator index x High/Low factor after the last historical year (1 without commodity key)."""
    src, adj = f'{col}${R_PRI[PRI_PARAMS[0]]}', f'{col}${R_PRI[PRI_PARAMS[1]]}'
    if var == 'gp.src':
        return f'=SUBSTITUTE({src},"*","")'
    if var == 'gp.adj':
        return f'=IF(LEFT({adj},4)="High",2,IF(LEFT({adj},3)="Low",3,1))'
    if var == 'gpn':
        return (f'=IF($D{r}="",1,INDEX(PIntVal,MATCH({col}${R_PRI["gp.src"]}&"|"&$D{r},PIntKey,0),'
                f'MATCH({col}${R_YEAR},PIntYear,0)))')
    gpn = f'{col}{r - R_GP0 + R_GPN0}'
    return (f'=IF($D{r}="",1,{gpn}*{col}${R_DEFL}*IF({col}${R_YEAR}>{LH},CHOOSE({col}${R_PRI["gp.adj"]},1,$E{r},'
            f'$F{r}),1))')


def price_formula(var, r, col, prev, block):
    """Section-2 cell of price variable var in row r (v0.2.6: rows of one fuel | sector block; its parameter row pset
    holds D pass-through, E VAT rate, F GJ per price unit, G international price position). block: 'base', 'plain',
    'hist' (years up to the last historical price year: data from Inputs_prices by price code), 'proj' (projected
    years) or 'lam' (the LAMBDA year, which holds the IF between history and projection)."""
    o = lambda v, c=col: f'{c}{r - PVIDX[var] + PVIDX[v]}'          # same block, other variable
    prm = lambda c: f'${c}{r - PVIDX[var] + PVIDX["pset"]}'          # parameter of the block
    key = f'$B{r}&"."&$C{r}'
    hist = lambda v: f'INDEX(IP{v},MATCH({key},IPKey,0),MATCH({col}${R_YEAR},IP{v}Y,0))'
    lam = block == 'lam'
    if var == 'gpi':                         # international reference price of the fuel (gp row, real)
        return f'=INDEX({gp_range(col)},{prm("G")})'
    if var == 'spf':                         # fixed part of the supply cost: data in the base year, then constant
        return ip_lookup('fixsp', key) if block == 'base' else f'={prev}{r}'
    if var == 'sp':
        gp_now, gp_prev = o('gpi'), o('gpi', prev)
        if block == 'hist':
            return '=' + hist('sp')
        if lam:
            return '=' + call('SUPPLYCOST', f'{col}${R_YEAR}', key, o('spf'), f'{prev}{r}', gp_now, gp_prev,
                              o('psp'), o('psp', prev))
        return f'={o("spf")}+({prev}{r}-{o("spf")}-{o("psp", prev)})*{gp_now}/{gp_prev}+{o("psp")}'
    if var == 'txf':                         # before the floor: txo_L + (sp_L - sp) x (1 - pcc) (v0.4.10: L14 fixed)
        d = prm('D')
        if block == 'hist':
            return f'={o("txo")}'
        if lam:
            return '=' + call('FLOATTAX', f'{col}${R_YEAR}', key, d, f'{prev}{r}', o('sp'), o('sp', prev))
        return f'={prev}{r}-({o("sp")}-{o("sp", prev)})*(1-{d})'
    if var == 'txo':                         # last historical value: own row at the column in row 4 (helper)
        last = f'INDEX($A{r}:{prev}{r},{col}${R_LHCOL})'
        if block == 'hist':
            return '=' + hist('txo')
        if lam:
            return '=' + call('OTHERTAX', f'{col}${R_YEAR}', key, last, o('txf'))
        return f'=IF({last}>=0,MAX({last},{o("txf")}),{o("txf")})'
    if var == 'txfx':                        # v0.4.16: fixed part of txo = pass-through x txo of the last historical year
        rt = r - PVIDX[var] + PVIDX['txo']
        last = f'INDEX($A{rt}:{prev}{rt},{col}${R_LHCOL})'
        if block == 'hist':
            return f'={prm("D")}*{o("txo")}'
        if lam:                              # group 3 runs from the base year: data year by year to LastHist
            return '=' + call('FIXEDPART', f'{col}${R_YEAR}', prm('D'), o('txo'), last)
        return f'={prm("D")}*{last}'
    if var == 'txfl':                        # v0.4.16: floating part (moves with the supply cost)
        return '=' + (call('DIFF', o('txo'), o('txfx')) if lam else f'{o("txo")}-{o("txfx")}')
    if var in ('pcsw', 'ppcw'):              # v0.4.16 (LD18): phase-out wedges, by the block's line of section 1
        pos = f'MATCH($B{r}&"."&$C{r},IPKey,0)'          # order of the block in PRICES (= its line of section 1)
        line = 'csf.' if var == 'pcsw' else 'pcf.'
        a = (f'INDEX({pol_range(col, line + PRICES[0][0], len(PRICES))},{pos})', o('txfx' if var == 'pcsw' else 'txfl'))
        fn_ = 'SUBREFORM' if var == 'pcsw' else 'PCREFORM'
        return '=' + (call(fn_, *a) if lam else (f'-(1-{a[0]})*MIN({a[1]},0)' if var == 'pcsw'
                                                  else f'-(1-{a[0]})*{a[1]}'))
    if var == 'rpb':
        return '=' + (call('RETAILPRICE', o('sp'), o('txo'), prm('E')) if lam
                      else f'({o("sp")}+{o("txo")})*(1+{prm("E")})')
    if var == 'vat':
        return '=' + (call('VATPAY', o('sp'), o('txo'), prm('E')) if lam else f'({o("sp")}+{o("txo")})*{prm("E")}')
    if var == 'etx':
        return '=' + (call('TAXPART', o('txo')) if lam else f'MAX({o("txo")},0)')
    if var == 'esub':
        return '=' + (call('SUBSIDYPART', o('txo')) if lam else f'MIN({o("txo")},0)')    # v0.2.4: negative
    if var == 'psp':                         # v0.6.1 (I49): psu of the fuel (G position); per barrel for oop (L125);
        k_ = 'psu.'                          # v0.6.2: / GJ per price unit ($/GJ); v0.9.0 (R7.1): psu after the phase-out
        a = (f'INDEX({col}${R_POL[k_ + PSU_FUELS[0]]}:{col}${R_POL[k_ + PSU_FUELS[-1]]},{prm("G")})',
             f'$B{r}="oop"', prm('F'))
        if lam:
            return '=' + call('PSPRICEUNIT', *a)
        return f'={a[0]}*IF({a[1]},LitersPerBbl,1)/{a[2]}'
    if var == 'esubpu':
        return '=' + (call('PERUNIT', o('esub'), prm('F')) if lam else f'{o("esub")}*{prm("F")}')
    if var == 'pnq' or var in PV_NEWSRC:     # v0.4.1: averages over the subsectors priced by this block (atp D = pos)
        rng = lambda v: f'{col}${P_FIRST + VOFF[v] - VOFF["atp"]}:{col}${P_LAST + VOFF[v] - VOFF["atp"]}'   # v0.6.2
        pos = f'$D{r - PVIDX[var] + PVIDX["pnq"]}'
        if var == 'pnq':
            return '=' + (call('BLOCKQTY', pos, rng('ener')) if lam else
                          f'SUMIFS({rng("ener")},PVar,"atp",PPar,{pos})')
        a = (pos, rng(PV_NEWSRC[var]), rng('ener'), o('pnq'), o('rpb') if var == 'rpn' else '0')
        return '=' + (call('BLOCKAVG', *a) if lam else
                      f'IF({a[3]}=0,{a[4]},SUMPRODUCT(--(PVar&PPar="atp"&{a[0]}),{a[1]},{a[2]})/{a[3]})')
    if var == 'pnce':                        # total new policy = full retail price - price before new policies
        return '=' + (call('DIFF', o('rpn'), o('rpb')) if lam else f'{o("rpn")}-{o("rpb")}')
    if var == 'pvatn':                       # VAT on the new policies (and the price floor): the residual
        parts = f'SUM({o("pctx")}:{o("ppcw")})'           # v0.4.16: incl. the phase-out wedges (v0.9.0, R7.3: no ppsw)
        return '=' + (call('DIFF', o('pnce'), parts) if lam else f'{o("pnce")}-{parts}')
    raise ValueError(var)


PP_COLS = (L(7), L(6 + NY))             # PowerPaths: year columns (G = base year; A key, B country, C item)


def pw_block(var, col, cols_abs=False):
    """Absolute-row range of a power variable over its members (types, groups, subsectors) in column col."""
    mem = PW_MEMBERS[PW_KIND[var]]
    r0 = R_PW[(var, mem[0])]
    return f'{col}${r0}:{col}${r0 + len(mem) - 1}'


def pw_pcol(var, pc):
    """Absolute range of a power variable's parameter column pc (e.g. $D$100:$D$108)."""
    mem = PW_MEMBERS[PW_KIND[var]]
    r0 = R_PW[(var, mem[0])]
    return f'${pc}${r0}:${pc}${r0 + len(mem) - 1}'


def ipw_param(key):
    return f'Inputs_power!$B${IPWQ_ROW[key]}'


def pw_param_formula(spec, var, r):
    """Mitigation D:G cell of a power row: data key, Inputs_power lookup, PowerParams value or constant."""
    if spec[0] == 'key':
        kind = PW_KIND[var]
        return f'=$A{r}&"|"&$B{r}' if kind == 'tech' else (f'=$A{r}&"|"&$C{r}' if kind == 'user' else f'=$A{r}')
    if spec[0] == 't':
        c = IPWC[spec[1]]
        return f'=INDEX(Inputs_power!${c}${IPW_R0}:${c}${IPW_R1},MATCH($B{r},Inputs_power!$A${IPW_R0}:$A${IPW_R1},0))'
    if spec[0] in ('g', 'h', 's'):
        tab = {'g': (IPWG, IPW_G0, IPW_G1), 'h': (IPWH, IPWH0, IPWH1), 's': (IPWS, IPWS0, IPWS1)}[spec[0]]
        c = tab[0][spec[1]]
        return (f'=INDEX(Inputs_power!${c}${tab[1]}:${c}${tab[2]},MATCH($C{r},Inputs_power!$A${tab[1]}:$A${tab[2]},'
                f'0))')
    if spec[0] == 'p':
        return '=' + pw_param(spec[1])
    if spec[0] == 'q':
        return '=' + ipw_param(spec[1])
    if spec[0] == 'mik':                         # v0.5.4: code of the new excise row on 'Manual inputs' (G150:G163)
        return f'="mit.ntx.ecy."&$C{r}'
    return f'=INDEX(ConstVal,MATCH("pw.c|"&$A{r},ConstKey,0))'    # v0.2.4: ('c',) scale factor from sheet Constants


def pw_formula(var, r, col, prev, block):
    """Section-3 cell of power variable var in row r. block: 'all' (data rows, every column), 'base', 'plain',
    'hist' / 'proj' (rppre) or 'lam' (right column: the named LAMBDA)."""
    lam = block == 'lam'
    nxt = L(CI_(col) + 1)
    kind = PW_KIND[var]
    first = PW_MEMBERS[kind][0] if kind != 'single' else None
    o = lambda v, c=col: f'{c}{r - R_PW[(var, first)] + R_PW[(v, first)]}'      # same member, other variable
    one = lambda v, c=col: f'{c}${R_PW[(v, "")]}'                                 # single row
    mem = lambda v, m, c=col: f'{c}${R_PW[(v, m)]}'                              # a given member (absolute row)
    blk = lambda v, c=col: pw_block(v, c)
    y = f'{col}${R_YEAR}'
    cg = 'PwCG'                         # coal / gas flags (gen rows, column D); v0.3.10: defined name (100 characters)

    def fn(name, *a, plain=None):
        return '=' + (call(name, *a) if lam else (plain if plain is not None else lambda_plain(name, a)))
    pc = lambda k: f'{col}${R_POL[k]}'          # v0.5.4: section-1 power setting of the scenario (MTInputs column)
    if var == 'tcf':                            # v0.5.4: capex time factor of the scenario's decline scenario (A0)
        return (f'=INDEX(PPathVal,MATCH(CtryCode&"|"&$D{r}&"|"&{one("ctf")},PPathKey,0),'
                f'MATCH({col}${R_YEAR},PPathYear,0))')
    if var == 'entxd':                          # v0.5.4: new electricity excise, 'Manual inputs' rows 161-162
        return f'=IFERROR(INDEX(ManExcVal,MATCH($D{r},ManExcKey,0),MATCH({col}${R_YEAR},ManExcYr,0))+0,0)'
    if var in PW_DATA:
        return f'=INDEX(PPathVal,MATCH(CtryCode&"|"&$D{r},PPathKey,0),MATCH({col}${R_YEAR},PPathYear,0))'
    # ---------------- A0 (v0.5.4): the data of the scenario (power settings of section 1 applied to the data)
    if var == 'cfu':        # capacity factor: actual within the CFOverride bounds, else the studies value (L53)
        a = (f'$D{r}', f'$E{r}', f'IF($F{r}=1,{pc("CFOverrideIfBelowWndSol")},{pc("CFOverrideIfBelowFosOth")})',
             pc('CFOverrideIfAbove'))
        return fn('CFUSED', *a)
    if var == 'nuu':        # efficiency: actual unless below the minimum (or no input: -1), else the studies value
        return fn('EFFUSED', f'$D{r}', f'$E{r}', pc('MinimumThermalEfficiency'))
    if var == 'wsel':       # WACC option: C Country*, T Tech, else the studies or a fixed value (wfx)
        return fn('WACCCODE', pc('WACCSource'))
    if var == 'wfx':        # fixed WACC of the options User and Income* ("" otherwise: the studies value)
        return fn('WACCFIXED', pc('WACCSource'), pc('WACCUserGlobal'))
    if var == 'wac':        # WACC used (legacy rows 2988-2996 X; min WACC on the studies, user and income options)
        return fn('WACCUSED', one('wsel'), f'$D{r}', f'$E{r}', f'$F{r}', one('wfx'), pc('MinimumWACC'))
    if var == 'dlf':        # discounted lifetime (annuity factor) at the WACC of the scenario
        return fn('LIFEFACTOR', o('wac'), f'$D{r}')
    if var == 'dlfr':       # discounted lifetime of renewables: average of wind and solar (legacy row 3883)
        return fn('PAIRMEAN', mem('dlf', 'wnd'), mem('dlf', 'sol'))
    if var == 'kwh':        # fuel per kWh (GJ/kWh; 0 without a price fuel)
        return fn('FUELPERKWH', f'$D{r}', o('nuu'))
    if var == 'cap0':       # base-year capacity = base-year generation / capacity factor
        return fn('SAFEDIV', f'$D{r}', o('cfu'))
    if var == 'invs':       # new investment setting of the type (MTInputs rows 395-403 of the scenario)
        return fn('PICKTYPE', pol_range(col, 'NewInvCoa', NT), f'$D{r}')
    if var == 'perm':       # "If Present*": Yes if the type has more than InvPresentShare of base-year capacity
        return fn('INVPRESENT', o('invs'), o('cap0'), blk('cap0'))
    if var == 'start':      # start year (MTInputs rows 405-413); hydro from the base year if its share is large (L54)
        return fn('INVSTART', f'$E{r}', f'$F{r}', f'INDEX({pol_range(col, "NewInvCoaYear", NT)},$D{r})')
    if var == 'scat':       # scale-up rate of the category (Power I20:J23)
        return fn('SCALECAT', pc('MaxScaleUpRateCategory'))
    if var == 'scv':        # scale-up rate of wind and solar (legacy S85:S91)
        return fn('SCALEVRE', pc('MaxScaleUpRateCategory'), pc('MaxWindSolarScaleup'), one('scat'))
    if var == 'rate':       # scale-up rate by type
        return fn('SCALETYPE', f'$D{r}', f'$E{r}', pc('MaxNonVREAsPCOfTotalGen'), one('scv'),
                  pc('MaxNonNucOreBioAsPCOfTotalGen'))
    if var == 'rr':         # retirement rate (hydro 0 if HydroDoesntRetire = Yes)
        return fn('RETIRERATE', f'$D{r}', f'$E{r}', pc('HydroDoesntRetire'))
    if var == 'erf':        # factor on cost-based early coal retirement (legacy F3993: scenario 1 by its switch)
        return fn('EARLYFACTOR', f'{col}${R_SCEN}', pc('EarlyRetirementInBaseline'), pc('MaxCostBasedEarlyRetirement'))
    if var == 'spot':       # spot fuel prices for power: Settings SpotPow or the scenario's MTInputs switch (1 / 0)
        return fn('SPOTSWITCH', pc('UseSpotFuelPricesInEngineerModel'))
    if var == 'ctf':        # capex time-factor scenario code (legacy rows 3038-3046)
        return fn('DECLINECODE', pc('RenewableCostDeclineRate'))
    if var == 'stm':        # short-term storage: marginal hours x allocation to VRE (legacy rows 3871-3873)
        return fn('SCALEBY', pc('AllocateSTStorageToVRE'), f'StMargFactor*{pc("TotalHoursStorageFor100pcVRE")}')
    if var == 'ltu':        # long-term storage: allocation to VRE x units for 100% VRE (legacy rows 3876, 3878, 3909)
        return fn('SCALEBY', pc('AllocateLTStorageToVRE'), pc('LongTermStorageFor100pcVRE'))
    if var == 'ppa':        # PPA share of coal and gas generation (legacy rows 2188-2193, 2218, 3801)
        a = (pc('PPAProportionCoalGas'), f'{col}${R_SCEN}', pc('PhaseOutCoalAndGasPPAsBaseline'),
             pc('PhaseOutCoalAndGasPPAsPolicy'), y, pc('YearPPACoalGas'), pc('YearsToPhaseOutPPAs'))
        return fn('PPASHARE', *a)
    if var == 'rnsp':       # renewable subsidy per kWh, negative (legacy rows 2733-2745; own start year: L107)
        a = (pc('RenewableSubsidyBL'), pc('RenSubsidyAddUSDkwh'), f'{col}${R_SCEN}', y, pc('RenSubsidyAddStartYear'),
             pc('RenSubsidyAddPhaseoutYrs'), f'{col}${R_CPI}')   # v0.5.6: nominal inputs to real (legacy bug L114)
        return fn('RENSUBSIDY', *a)
    if var == 'rns':        # renewable subsidy by type (hydro if RenewableSubsidyHydro = Yes; legacy rows 3144-3152)
        return fn('RENBYTYPE', one('rnsp'), f'$D{r}', f'$E{r}', pc('RenewableSubsidyHydro'))
    if var == 'rbs':        # power revenues rebated (1 / 0): policy scenarios, PowerRebates or a feebate scenario
        return fn('REBATESWITCH', f'{col}${R_SCEN}', pc('PowerRebates'), f'{col}${R_POL["scn"]}')
    if var == 'exs':        # electricity excise ($/kWh; scenario Electricity excise): grid intensity x carbon price
        return fn('EXCISECARBON', f'{col}${R_SCEN}', f'{col}${R_POL["scn"]}', f'{col}${R_CP}')
    if var == 'cel':        # long-term storage cost per marginal unit (legacy rows 3893-3906)
        return fn('LTSTORAGE', one('elcx'), one('eltk'), pc('StorageHoursForLTStorage'), one('dlfr'), one('elof'),
                  one('elov'))
    if var == 'incf':       # income factor on the GDP elasticities: IncElAdj of the scenario
        return fn('INCOMESWITCH', pc('IncElAdj'), one('incp'))
    if var == 'demg':       # memo: demand of the subsectors of this demand group (dem rows: D = group position)
        return f'=SUMIF({pw_pcol("dem", "D")},$D{r},{blk("dem")})'
    if var == 'psegs':                         # v0.9.0 (R7.5): sum of the pre-tax gaps x consumption
        return f'=SUM({blk("psegap")})'
    if var in PW_SUMS:
        src = {'demtot': 'dem', 'gtot': 'gen', 'usdtot': 'usd', 'captot': 'cap', 'nimtot': 'nim'}[var]
        return f'=SUM({blk(src)})'
    if var == 'cax':
        return fn('CAPEX', f'$D{r}', o('tcf'), plain=f'$D{r}*{o("tcf")}')
    if var in ('caxav', 'stoav'):
        if block == 'base':
            return '=' + (o('cax') if var == 'caxav' else f'$D{r}*{one("msc")}')
        new_v = o('cax', prev) if var == 'caxav' else f'$D{r}*{one("msc")}'      # capex of last year; storage now
        a = (f'{prev}{r}', new_v, o('phi', prev))
        return fn('VINTAGE', *a, plain=f'{a[0]}*(1-{a[2]})+{a[1]}*{a[2]}')
    if var == 'fix':        # v0.5.4: WACC and capacity factor of the scenario (A0)
        a = (o('caxav'), f'$D{r}', o('wac'), o('cfu'), f'$E{r}', o('stoav'))
        return fn('AMORTISED', *a)
    if var == 'lfx':        # v0.5.4: capacity factor, discounted lifetime and renewable subsidy of the scenario (A0)
        a = (o('cax'), f'$D{r}', o('cfu'), o('dlf'), f'$E{r}', o('rns'), f'$F{r}', one('msc'))
        return fn('LEVELISED', *a)
    if var == 'fpn':        # v0.6.2: this year's rpb of the price fuel (the moving average below reads this one row)
        r0, r1 = prow('rpb', PRICES[0][0]), prow('rpb', PRICES[-1][0])
        a = (f'INDEX({col}${r0}:{col}${r1},$D{r})',)
        return fn('BLOCKPRICE', *a, plain=a[0])
    if var == 'fpp':        # v0.2.3: fuel price for power: moving average (legacy A18) or spot; v0.6.2 (legacy bug L126):
        rn = r - R_PW[(var, first)] + R_PW[('fpn', first)]   # trailing t-4 .. t (legacy t-2 .. t+2 read later years)
        st = f'INDEX($A{rn}:{col}{rn},COLUMN()-MIN({y}-BaseYr,PwAvgLag))'   # from this group's base year at
        a = (one('spot'), f'{col}{rn}', f'{st}:{col}{rn}')   # most: only the group's own year cells of row fpn are read
        return fn('POWFUELPRICE', *a, plain=f'IF({a[0]}=1,{a[1]},AVERAGE({a[2]}))')
    if var in ('cics', 'cicl'):   # v0.5.6 (P5): coal implicit cost chosen, short / long term (legacy J90, K90)
        st = var == 'cics'
        return fn('COALICPICK', pc('AdditionalCoalIntangibleCost'), pc('ManualCoalIntangibleCost' + ('ST' if st else 'LT')),
                  'CoalICSTc' if st else 'CoalICLTc')
    if var == 'cic':        # v0.5.6 (P5): coal implicit cost, $/kWh (legacy D3 rows 3360-3363)
        return fn('COALIC', one('cics'), one('cicl'), y)
    if var == 'vbc':        # v0.1.09: + change in existing carbon pricing (xck); v0.2.3: fuel price for power (fpp)
        a = (f'$D{r}', o('fpp'), o('kwh'), f'{o("xck")}+($B{r}="coa")*{one("cic")}')   # v0.5.6: + coal implicit cost
        return fn('VARCOST', *a, plain=f'{a[0]}+{a[1]}*{a[2]}+{a[3]}')
    if var == 'tvcx':       # v0.2.3: tvc for the levelised window; where the host cannot evaluate the LAMBDA year: tvc(t-1)
        return f'=IFERROR({o("tvc")},{o("tvc", prev)})'
    if var in ('xck', 'prxl'):   # v0.1.09: existing carbon pricing: change per kWh (xck), revenue level (prxl)
        a = (xcarbon_args(col, f'$D{r}*{o("kwh")}', f'$E{r}', f'$F{r}') if var == 'xck'
             else xcarbon_args(col, o('co2'), f'$D{r}', '0'))
        return fn('XCARBON', *a, plain=xcarbon_plain(a))
    if var in ('prtx', 'prsub'):   # v0.1.09: existing taxes / subsidies on generation fuels (price fuel of section 2)
        pr = lambda v: f'INDEX({pv_range(v, col)},$D{r})'
        rate = f'{pr("etx")}+{pr("vat")}' if var == 'prtx' else pr('esub')
        a = (f'$E{r}*{o("pe")}', 'Settings!$C$13', rate)
        return fn('REVENUE', *a, plain=f'{a[0]}*{a[1]}*({a[2]})')
    if var == 'prxc':       # change in existing carbon pricing revenue: generation (GWh) x xck
        return fn('POWERREV', o('xck'), 'MWyMkWh', o('gen'), plain=f'{o("xck")}*MWyMkWh*{o("gen")}')
    if var == 'prnew':      # new policies: cost per kWh x GWh, ETS part at the permit price (x revenue factor)
        a = (o('gen'), o('ccp'), o('co2'), f'{col}${R_POL["etr.pow"]}', f'{col}${R_POL["ets.rf"]}')
        return fn('PNEWREV', *a, plain=f'{a[0]}*MWyMkWh*{a[1]}-{a[2]}*{a[3]}*(1-{a[4]})')
    if var == 'ccp':        # tCO2/kWh x (carbon tax x fuel coverage + ETS cost) + fuel price reform per kWh
        # v0.9.0 (R3.11): the reform term reads the block's new excise ntxb (reform + Pigouvian tax, netted)
        a = (f'$D{r}*{o("kwh")}', f'{col}${R_POL["ctr.pow"]}', f'INDEX({pol_range(col, "fc.coa", NF)},$E{r})',
             f'{col}${R_POL["etr.pow"]}',
             f'INDEX({pol_range(col, "ntxb." + PRICE_FUELS[0][0], len(PRICE_FUELS))},$F{r})', f'{o("kwh")}/$G{r}')
        return fn('KWHPOLICY', *a, plain=f'{a[0]}*({a[1]}*{a[2]}+{a[3]})+{a[4]}*{a[5]}')
    if var == 'shk':        # shadow price per kWh: shadow price of power ($/tCO2, section 1) x tCO2/kWh
        a = (f'{col}${R_POL["shpx.pow"]}', f'$D{r}*{o("kwh")}')
        return fn('SHADOWGJ', *a, plain=f'{a[0]}*{a[1]}')
    if var == 'reb':        # feebate rebate per kWh generated (base-year shares), from the second year
        if block == 'base':
            return '=0'
        a = (blk('shk'), pw_pcol('shk', 'E'))
        return fn('REBATE', *a, plain=f'-SUMPRODUCT({a[0]},{a[1]})')
    if var == 'tvc':
        a = (o('vbc'), o('ccp'), o('shk'), one('reb'))
        return fn('VARTOTAL', *a, plain='+'.join(a))
    if var == 'dsum':       # sum of discount factors to the end of the horizon (next column: blank after the last)
        a = (o('wac'), 'Settings!$C$7', y, f'{nxt}{r}')
        return fn('DISCSUM', *a, plain=f'(1+{a[0]})^({a[1]}-{a[2]})+{a[3]}')
    if var == 'lvc':        # levelised variable cost: discounted average of tvc to the end of the horizon (D9)
        a = (o('wac'), 'Settings!$C$7', y, o('tvcx'), o('dsum'), f'{nxt}{r}')
        df = f'(1+{a[0]})^({a[1]}-{a[2]})'
        return fn('LEVVAR', *a, plain=f'({df}*{a[3]}+({a[4]}-{df})*{a[5]})/{a[4]}')
    if var == 'fce':        # v0.5.6 (P5 memo, legacy F3): post-tax fuel cost per kWh
        return fn('SCALEBY', o('fpp'), o('kwh'))
    if var == 'cik':        # v0.5.6 (P5 memo, legacy F4): tCO2 per kWh (EF of the ccp row x GJ per kWh)
        dr = R_PW[('ccp', first)] + r - R_PW[(var, first)]
        return fn('SCALEBY', f'$D{dr}', o('kwh'))
    if var in ('swi', 'swd'):   # v0.5.6 (P5 memo, legacy F7): switching carbon prices gas over coal
        v = 'tic' if var == 'swi' else 'tvc'
        return fn('SWITCHPRICE', mem(v, 'nga'), mem(v, 'coa'), mem('cik', 'coa'), mem('cik', 'nga'))
    if var == 'gnc':        # v0.5.6: less the coal implicit cost if PwCoalICTariff = No
        return fn('GENCOSTIC', o('fix'), o('vbc'), f'($B{r}="coa")*{one("cic")}')
    if var in ('gncav', 'ccpav', 'vre'):
        vals = {'gncav': blk('gnc'), 'ccpav': blk('ccp'), 'vre': pw_pcol('shr', 'D')}[var]
        a = (blk('shr'), vals, f'$D{r}')
        return fn('WEIGHTED', *a, plain=f'SUMPRODUCT({a[0]},{a[1]})*{a[2]}')
    if var == 'tic':
        a = (o('lfx'), o('lvc'), pc('MinPostSubsidyPowerPrice'))
        return fn('INVCOST', *a, plain=f'MAX({a[0]}+{a[1]},{a[2]})')
    if var == 'cph':
        a = (one('cbat'), one('cint'), one('obat'), pc('StorageToInterfaceRatioSTStorage'), one('dlfr'))
        return fn('STORAGEHOUR', *a, plain=f'({a[0]}+{a[1]}/{a[3]})/({a[4]}*HoursYr)+{a[2]}/HoursYr')
    if var == 'msc':
        a = (one('stm'), one('vre'), one('cph'), pc('StartingPointWhenLTStorageIsNeeded'), one('cel'), one('ltu'))
        return fn('STORAGECOST', *a)              # v0.5.4: settings of the scenario, LT units for 100% VRE (row 3909)
    if var == 'cons':
        a = (one('demtot'), mem('dem', 'res'), f'$D{r}', f'$E{r}', f'$F{r}')
        return fn('CONSUMPTION', *a, plain=f'({a[2]}*{a[0]}+{a[3]}*{a[1]})*{a[4]}')
    if var == 'sc':
        gen = one('gncav') if block == 'base' else one('gncav', prev)
        return fn('POWERSUPPLY', gen, f'$D{r}', plain=f'{gen}+$D{r}')
    # ---------------- E2 (v0.9.0, R9.4-R9.13): cost memos by type
    if var == 'cur':        # current total cost (legacy E4 rows 3498-3506)
        return fn('INVCOST', o('lfx'), o('tvc'), pc('MinPostSubsidyPowerPrice'))
    if var == 'sys':        # system cost (legacy F1 rows 3522-3530)
        return fn('SYSCOST', f'$D{r}', o('cfu'), o('dlf'), f'$E{r}', one('msc'), f'($B{r}="coa")*{one("cic")}')
    if var == 'pcbcap':     # capital (legacy E5 L, C1)
        return fn('LEVCAPEX', o('cax'), o('cfu'), o('dlf'))
    if var == 'pcbom':      # O&M (legacy E5 M, A16 + D1)
        return fn('OMCOST', f'$D{r}', o('cfu'), f'$E{r}')
    if var == 'pcbfu':      # fuel incl. the change in existing carbon pricing (legacy E5 N, D2)
        return fn('VARCOST', f'$D{r}', o('fpp'), o('kwh'), o('xck'))
    if var in ('pcbcp', 'pcbrns'):   # new carbon price (legacy E5 P, D5); renewable subsidy (E5 Q, A17)
        return fn('MEMOOF', o('ccp' if var == 'pcbcp' else 'rns'))
    if var == 'pcbchk':     # check: parts - current total cost (legacy E5 S; shadow price and floor, I142)
        parts = '+'.join(o(v) for v in ('pcbcap', 'pcbom', 'pcbfu', 'sys', 'pcbcp', 'pcbrns'))
        return fn('DIFF', parts, o('cur'))
    if var == 'pcbct':      # carbon tax of policy scenarios (legacy E5 T; L222 fixed: own scenario)
        return fn('SCALEBY', f'{col}${R_CP}', f'({col}${R_SCEN}>1)*1')
    # ---------------- G2 (v0.9.0, R7.5-R7.9, R9.1-R9.3): electricity subsidies and the price-chain residual
    lastv = lambda rr: f'INDEX($A{rr}:{prev}{rr},{col}${R_LHCOL})'      # value of the last historical price year
    if var == 'rpnv':       # data price before VAT up to the last price year, then held (legacy rows 3575, 3604)
        a = (y, f'INDEX(PwRp,$D{r},MATCH({y},PwRpYr,0))/(1+$E{r})', f'{prev}{r}')
        return fn('HISTHOLD', *a)
    if var == 'txg':        # price before VAT - supply cost - manual excise (legacy N3605 without the tax)
        return fn('PRICEGAP', o('rpnv'), o('sc'), o('entx'))
    if var == 'txe':        # tax / subsidy of the dataset; else txg if SupplyCostDeltaSubsidy = Yes (rows 3604-3606)
        a = (y, f'INDEX(PwTx,$D{r},MATCH({y},PwTxYr,0))', o('txg'), pc('SupplyCostDeltaSubsidy'), f'{prev}{r}')
        return fn('ELTAXBASE', *a)
    if var == 'scl':        # supply cost, after the last price year capped at its value (legacy $J3600 in O3607)
        return fn('CAPLAST', y, o('sc'), lastv(r))
    if var == 'psegap':     # pre-tax gap x consumption (legacy row 3588 terms)
        return fn('PREGAP', o('sc'), o('rpnv'), o('txe'), o('cons'))
    if var == 'psesh':      # share of the electricity producer subsidy (legacy rows 3588-3589)
        a = (y, o('psegap'), one('psegs'), o('cons'), f'SUM({blk("cons")})', f'1-$D{r}', f'{prev}{r}')
        return fn('PSALLOC', *a)
    if var == 'pseu':       # per kWh, floored (legacy 3590-3591), then x the phase-out factor (3601, 3630)
        a = (y, f'{col}${R_POL["pros.ecy"]}', o('psesh'), o('cons'), lastv(r), f'{col}${R_POL["psf.ecy"]}')
        return fn('PSELEC', *a)
    if var == 'pser':       # residual above the floor (USD m; legacy row 3592)
        used = '+'.join(f'{mem("cons", m)}*{mem("pseu", m)}' for m, _n in PW_GROUPS)
        a = (y, f'{col}${R_POL["pros.ecy"]}', used, lastv(r), f'{col}${R_POL["psf.ecy"]}')
        return fn('PSERESID', *a)
    if var == 'csd':        # consumer subsidy phase-out (legacy O3606, O3635; L84 not reproduced in 465)
        a = (y, o('txe'), pc('PowerSubsidyExemptInclude'), f'{col}${R_POL["pof.cs"]}')
        return fn('CSELEC', *a)
    if var == 'ores':       # price-chain residual (legacy rows 3607, 3636): held, scaled down with the supply cost
        a = (y, f'{o("txg")}-{o("txe")}-{o("pseu")}', f'{prev}{r}', o('scl'), o('scl', prev))
        return fn('ORESID', *a)
    if var == 'spe':        # legacy supply cost "removing estimation" (rows 3620, 3649): sc + residual + carbon + excise
        a = (o('sc'), o('ores'), one('ccpav'), pc('PowerSectorPriceChangePassOn'), one('rbs'), o('pex'))
        return fn('ELSUPPLY', *a)
    if var == 'rppre':
        hist = (f'INDEX(Inputs_power!${IPWG["rp" + str(HIST_YEARS[0])]}${IPW_G0}:${IPWG["rp" + str(HIST_YEARS[-1])]}'
                f'${IPW_G1},$D{r},MATCH({col}${R_YEAR},Inputs_power!${IPWG["rp" + str(HIST_YEARS[0])]}${IPW_G0 - 1}:'
                f'${IPWG["rp" + str(HIST_YEARS[-1])]}${IPW_G0 - 1},0))')
        if block == 'hist':
            return '=' + hist
        ps = pc('PowerSectorPriceChangePassOn')   # v0.5.4: pass-through of the scenario
        sc_n = '+'.join(o(v) for v in ('sc', 'pseu', 'csd', 'ores'))   # v0.9.0 (R7.9, R9.3): + subsidies, residual
        sc_p = '+'.join(o(v, prev) for v in ('sc', 'pseu', 'csd', 'ores'))
        if lam:
            return '=' + call('POWERPRICE', f'{col}${R_YEAR}', f'$D{r}', f'{prev}{r}', ps, sc_n, sc_p, f'$E{r}')
        return f'={prev}{r}+{ps}*({sc_n}-({sc_p}))*(1+$E{r})'
    if var == 'entx':       # v0.5.4: manual electricity excise of policy scenarios (AdditionalExcise; legacy 3602, 216)
        m = PW_MEMBERS[kind][r - R_PW[(var, first)]]            # v0.5.6: + electricity fuel price reform (I59,
        a = (f'{col}${R_SCEN}', pc('AdditionalExcise'), o('entxd'), pc('NomorReal'), f'{col}${R_DEFL}',
             f'{col}{R_POL["fpr.ecy." + m]}')                   # v0.6.0: relative (one formula per row); legacy row 216: + fuel price reform path 178/179)
        return fn('MANEXCISE', *a)
    if var == 'pex':        # v0.5.4: excise in the price before VAT: electricity excise (exs) + change of the manual
        if block == 'base':  # excise since the last historical year x pass-through (legacy 3602-3616, 3631-3645)
            return f'={one("exs")}'
        a = (one('exs'), f'{y}>LastHist', pc('PowerSectorPriceChangePassOn'), o('entx'),
             f'INDEX($A{r - R_PW[(var, first)] + R_PW[("entx", first)]}:{prev}{r - R_PW[(var, first)] + R_PW[("entx", first)]},'
             f'{col}${R_LHCOL})')
        return fn('EXCISEPRICE', *a)
    if var == 'rp':         # policy term x pass-through (less the rebate) + excise, x (1 + VAT), as legacy row 3617
        a = (o('rppre'), one('ccpav'), pc('PowerSectorPriceChangePassOn'), f'$D{r}', one('rbs'), o('pex'),
             pc('MinPostSubsidyPowerPrice'))                    # v0.5.6: floor as legacy rows 3617, 3646 (I60)
        return fn('ENDUSERPOWER', *a)
    if var == 'sgap':
        return fn('SUBSIDYGAP', o('sc'), o('rppre'), f'$D{r}', plain=f'{o("rppre")}/(1+$D{r})-{o("sc")}')
    if var in ('rvat', 'rcarb', 'rgap'):
        rate = {'rvat': o('rppre'), 'rcarb': one('ccpav'), 'rgap': o('sgap')}[var]
        return fn('POWERREV', rate, f'$D{r}', o('cons'), plain=f'{rate}*$D{r}*{o("cons")}')
    if var == 'rnvat':      # v0.1.09: VAT on the new-policy cost passed through (pass-through x VAT rate); v0.5.4: less
        # the rebate, plus the excise
        rate = (f'({one("ccpav")}*{pc("PowerSectorPriceChangePassOn")}*(1-{one("rbs")})'
                f'+{o("pex")})')
        return fn('POWERREV', rate, f'$D{r}', o('cons'), plain=f'{rate}*$D{r}*{o("cons")}')
    if var == 'rreb':       # v0.5.4: rebate of the carbon cost to consumers (negative; legacy row 3663)
        return fn('POWERREV', f'-{one("rbs")}*{one("ccpav")}', pc('PowerSectorPriceChangePassOn'), o('cons'))
    if var == 'rpex':       # v0.5.4: excise revenue (legacy rows 3660, 3664)
        return fn('SCALEBY', o('pex'), o('cons'))
    if var == 'rexs':       # v0.5.4: of which the electricity excise of policy type 11 (legacy rows 3664, 7889)
        return fn('SCALEBY', one('exs'), f'SUM({blk("cons")})')
    if var == 'rexm':       # v0.5.4: of which the manual excise (legacy rows 3660, 7762)
        return fn('DIFF', f'SUM({blk("rpex")})', one('rexs'))
    # ---------------- H demand
    if var == 'pdem':       # price of the previous year, weighted by demand group (base year: 2021 data)
        if block == 'base':
            return f'=$E{r}'
        a = (f'$D{r}', mem('rp', 'res', prev), mem('rp', 'ind', prev))
        return fn('PRICEMIX', *a, plain=f'{a[0]}*{a[1]}+(1-{a[0]})*{a[2]}')
    if var == 'aeef':       # v0.5.4: efficiency multiple with the scenario's AdditionalEfficiencyPower (was Inputs_power)
        return fn('AEEIFACTOR', f'$D{r}', pc('AdditionalEfficiencyPower'), f'$E{r}')
    if var == 'mult':       # v0.5.4: shock x EngineerModelProportionOfCovidFactor of the scenario (legacy row 3685)
        if block == 'base':
            return '=1'
        a = (o('aeef'), f'{col}${R_GDP}', f'$D{r}', one('incf'), o('pdem'), o('pdem', prev), f'$E{r}', one('shock'),
             f'Settings!$C$19*{pc("EngineerModelProportionOfCovidFactor")}')
        return fn('DEMANDMULT', *a, plain=f'{a[0]}*(1+{a[1]})^({a[2]}*{a[3]})*({a[4]}/{a[5]})^{a[6]}*(1+{a[7]}*{a[8]})')
    if var == 'dem':
        if block == 'base':
            return f'=$E{r}'
        a = (f'$F{r}', f'{col}${R_TR["tr.sw"]}', f'{col}${R_TR[5331]}', f'{prev}{r}', f'INDEX({blk("mult")},$D{r})')
        return fn('DEMROAD', *a, plain=lambda_plain('DEMROAD', a))   # v0.3.5: road from section 5b if switched on
    if var == 'req':
        if block == 'base':
            return f'=SUM({blk("gen")})'
        return fn('SCALEBY', one('demtot'), f'$D{r}', plain=f'{one("demtot")}*$D{r}')
    # ---------------- I dispatch
    if var == 'reqcg':      # generation required from coal and gas
        a = (one('req'), f'SUMPRODUCT({blk("effcap")},1-{cg})')
        return fn('RESIDUAL', *a, plain=f'MAX({a[0]}-{a[1]},0)')
    if var == 'vcmin':
        a = (blk('tvc'), cg, pc('MinPostSubsidyPowerPrice'))
        return fn('FLOORMIN', *a, plain=f'MAX(_xlfn.MINIFS({a[0]},{a[1]},1),{a[2]})')
    if var == 'rem':
        a = (one('reqcg'), f'SUM({blk("gmin")})')
        return fn('RESIDUAL', *a, plain=f'MAX({a[0]}-{a[1]},0)')
    if var == 'gmx':        # v0.5.4: maximum generation of coal and gas (MaximumCoalCF, MaximumGasCF; legacy 3783-3786)
        a = (o('cap'), f'$D{r}', pc('MaximumCoalCF'), f'$E{r}', pc('MaximumGasCF'))
        return fn('MAXOUTPUT', *a)
    if var == 'gmin':       # minimum of coal (gas) if the other runs at its maximum
        a = (f'$D{r}', one('reqcg'), f'SUM({blk("gmx")})', o('gmx'))
        return fn('MINDISPATCH', *a, plain=f'{a[0]}*MIN(MAX({a[1]}-({a[2]}-{a[3]}),0),{a[3]})')
    if var == 'lgd':
        a = (f'$D{r}', pc('kDispatch'), f'MAX({o("tvc")},{pc("MinPostSubsidyPowerPrice")})', one('vcmin'))
        return fn('LOGITW', *a, plain=f'{a[0]}*EXP(-{a[1]}*{a[2]}/{a[3]})')
    if var == 'glg':        # v0.5.4: logit dispatch (the generation before PPAs; legacy rows 3799-3800)
        a = (f'$D{r}', o('effcap'), o('gmx'), o('gmin'), one('rem'), o('lgd'), f'SUM({blk("lgd")})')
        return fn('DISPATCH', *a, plain=f'IF({a[0]}=1,MIN({a[2]},{a[3]}+{a[4]}*{a[5]}/{a[6]}),{a[1]})')
    if var == 'ppr':        # v0.5.4: coal and gas need / their effective capacity (legacy row 3794)
        return fn('PPARATIO', one('reqcg'), f'SUMPRODUCT({blk("effcap")},{cg})')
    if var == 'gen':        # v0.5.4: the PPA share runs at its capacity factor x ppr (legacy rows 3804-3805)
        if block == 'base':
            return f'=$E{r}'
        return fn('PPAMIX', o('glg'), f'$D{r}', one('ppa'), o('effcap'), one('ppr'))
    if var == 'dgen':
        if block == 'base':
            return '=0'
        return fn('INCREASE', one('gtot'), one('gtot', prev), plain=f'MAX(0,{one("gtot")}-{one("gtot", prev)})')
    if var == 'shr':
        return fn('SHAREOF', o('gen'), one('gtot'), plain=f'IF({one("gtot")}=0,0,{o("gen")}/{one("gtot")})')
    if var == 'pe':         # v0.5.4: efficiency of the scenario (A0)
        return fn('SAFEDIV', f'{o("gen")}*$D{r}', o('nuu'))
    if var in ('effcap', 'reteff'):   # v0.5.4: capacity factor of the scenario (A0)
        return fn('SCALEBY', o({'effcap': 'cap', 'reteff': 'ret'}[var]), o('cfu'))
    if var == 'nim':        # v0.5.4: nameplate = effective / capacity factor of the scenario
        return fn('SAFEDIV', o('nei'), o('cfu'))
    if var == 'co2':
        return fn('SCALEBY', o('pe'), f'$D{r}', plain=f'{o("pe")}*$D{r}')
    # ---------------- K capacity and retirements
    if var == 'cap':
        if block == 'base':
            return f'={o("cap0")}'
        a = (o('cap', prev), o('ret', prev), o('nim', prev))
        return fn('CARRY', *a, plain=f'{a[0]}-{a[1]}+{a[2]}')
    if var == 'ret':        # planned retirement (data, where switched on) or rate-based; + early coal retirement
        a = (o('cap'), o('rr'), f'$D{r}', one('early'), f'$E{r}', o('pret'))     # v0.5.4: rate of the scenario
        return fn('RETIRE', *a, plain=f'MIN(IF({a[4]}=1,{a[5]},{a[0]}*{a[1]})+{a[2]}*{a[3]},{a[0]})')
    if var == 'egrow':      # room for early coal retirement: max wind and solar additions less demand growth and
        add = (mem('maxinv', 'wnd'), mem('maxinv', 'sol'))     # (effective) non-coal retirements of last year
        if block == 'base':
            return '=' + (call('EARLYROOM', *add, '0', '0') if lam else f'MAX(0,{add[0]}+{add[1]})')
        a = add + (one('dgen', prev), f'SUM({blk("reteff", prev)})-{mem("reteff", "coa", prev)}')
        return fn('EARLYROOM', *a, plain=f'MAX(0,{a[0]}+{a[1]}-{a[2]}-({a[3]}))')
    cc, cw, cs = mem('tvc', 'coa'), mem('tic', 'wnd'), mem('tic', 'sol')     # early retirement: coal vs wind, solar
    if var == 'ecmin':      # lowest of coal variable cost and wind and solar investment cost
        return fn('LOWEST3', cc, cw, cs, plain=f'MIN({cc},{cw},{cs})')
    if var == 'ecshr':      # coal share of the logit (= e_coal / (e_coal + e_wind + e_solar), divided through)
        a = (pc('kInvestment'), cc, cw, cs, one('ecmin'))
        return fn('COALSHARE', *a, plain=(f'1/(1+EXP(-{a[0]}*({cw}-{cc})/{a[4]})'
                                          f'+EXP(-{a[0]}*({cs}-{cc})/{a[4]}))'))
    if var == 'early':      # cost-based early coal retirement (nameplate MW)
        a = (mem('effcap', 'coa'), f'$D{r}', one('egrow'), one('ecshr'), f'{one("erf")}*(1-{one("ppa")})',
             mem('cfu', 'coa'))      # v0.5.4: factor of the scenario, not the PPA share (legacy rows 3987, 3993)
        return fn('EARLYRET', *a, plain=f'MAX(0,MIN({a[0]}*{a[1]},{a[2]})*(1-{a[3]}))/{a[5]}*{a[4]}')
    if var == 'kafter':     # effective capacity after this year's retirements
        a = (f'SUM({blk("effcap")})', f'SUM({blk("reteff")})')
        return fn('DIFF', *a, plain=f'{a[0]}-{a[1]}')
    if var == 'need':       # effective capacity needed for next year's required generation (online next year);
        # v0.4.14: legacy bug L67 fixed (legacy: this year's); v0.6.2: next year's estimated as this year's x (1 + growth
        # from last year), so nothing reads a later column (no circular reference through the GDP feedback)
        a = (one('req'), one('req', L(CI_(col) - 1)), one('kafter'))
        return fn('NEEDNEXT', *a, plain=f'MAX({a[0]}*IFERROR({a[0]}/{a[1]},1)-{a[2]},0)')
    if var == 'mancap':     # v0.5.6 (P3): manual capacity path of the scenario group ('Manual inputs' 349-357 / 363-371)
        return fn('MANCAP', f'$D{r}', f'{col}${R_SCEN}', y)
    if var == 'mani':       # v0.5.6 (P3): manual investment = path increase + retirement (effective MW)
        nx = f'{nxt}{r - R_PW[(var, first)] + R_PW[("mancap", first)]}'
        return fn('MANINV', o('invs'), nx, o('mancap'), o('ret'), o('cfu'))
    if var == 'needm':      # v0.5.6 (P3): need net of manual investment (legacy row 4108, unused there: bug L118)
        return fn('RESIDUAL', one('need'), f'SUM({blk("mani")})')
    # ---------------- L investment
    if var == 'cmin':
        a = (blk('tic'), blk('permit'), pc('MinPostSubsidyPowerPrice'))
        return fn('FLOORMIN', *a, plain=f'MAX(_xlfn.MINIFS({a[0]},{a[1]},1),{a[2]})')
    if var == 'deficit':
        a = (one('needm'), f'SUM({blk("first")})')
        return fn('RESIDUAL', *a, plain=f'MAX({a[0]}-{a[1]},0)')
    if var == 'permit':     # v0.5.4: permitted and start year of the scenario (A0)
        return fn('PERMITTED', o('perm'), o('start'), y)
    if var == 'maxinv':
        a = (o('rate'), f'SUM({blk("effcap")})', o('permit'))
        return fn('SCALEUP', *a, plain=f'{a[0]}*{a[1]}*{a[2]}')
    if var == 'lgi':
        a = (o('permit'), pc('kInvestment'), o('tic'), one('cmin'))
        return fn('LOGITW', *a, plain=f'{a[0]}*EXP(-{a[1]}*{a[2]}/{a[3]})')
    if var == 'pni':
        a = (o('lgi'), f'SUM({blk("lgi")})')
        return fn('SHAREOF', *a, plain=f'IF({a[1]}=0,0,{a[0]}/{a[1]})')
    if var == 'first':
        a = (o('maxinv'), one('needm'), o('pni'))
        return fn('FIRSTROUND', *a, plain=f'MIN({a[0]},{a[1]}*{a[2]})')
    if var == 'space':
        a = (o('maxinv'), o('first'), o('permit'))
        return fn('SPACE', *a, plain=f'({a[0]}-{a[1]})*{a[2]}')
    if var == 'second':     # cheapest first: the deficit less the space of cheaper types (legacy L11-L17)
        cheaper = (f'SUMPRODUCT(({blk("tic")}+PwTie<{o("tic")}+$D{r})*{blk("space")})')   # v0.3.9: name (100 chars)
        a = (o('permit'), o('space'), one('deficit'), cheaper)
        return fn('CHEAPFILL', *a, plain=f'{a[0]}*MAX(0,MIN({a[1]},{a[2]}-{a[3]}))')
    if var == 'dgas':       # v0.5.4: deficit left after the second round, to gas if PwDeficitGas = Yes (legacy 4247-4252)
        return fn('GASDEFICIT', 'PwDeficitGas', one('deficit'), blk('second'))
    if var == 'nei':        # v0.5.4: + the final deficit for gas (D: gas flag)
        return fn('ADDED', o('first'), f'{o("second")}+$D{r}*{one("dgas")}+{o("mani")}')
    if var == 'prrns':      # v0.5.4: renewable subsidy by type x generation (negative; legacy rows 3665-3669)
        return fn('POWERREV', o('rns'), 'MWyMkWh', o('gen'))
    if var == 'usd':
        return fn('INVSPEND', o('nim'), o('cax'), plain=f'{o("nim")}*{o("cax")}*kWperMW/USDperM')
    if var == 'phi':
        a = (o('nim'), o('cap'), o('ret'))
        return fn('VINTSHARE', *a, plain=f'IF({a[1]}+{a[0]}-{a[2]}=0,0,{a[0]}/({a[1]}+{a[0]}-{a[2]}))')
    raise ValueError(var)


def ref_formula(col, rr):
    """Scenario-1 value of row rr in this column's year. v0.3.1: the range ends at this column (scenario 1 is the
    first group, so it is always inside), so no cell depends on a later column of its own or a later scenario
    (the GDP feedback of section 16 would otherwise make the lookups circular)."""
    g0 = L(COL_G0)
    return f'=INDEX(${g0}{rr}:{col}{rr},MATCH({col}${R_YEAR},${g0}${R_YEAR}:{col}${R_YEAR},0))'


def mt_lookup(r, col):
    """Section-1 input: MTInputs row (column D) for this column's scenario (row 5)."""
    return (f'=INDEX(ScenarioDefinition!${L(MT_COL0)}$1:${MT_LAST}${MT_END},$D{r},'
            f'MATCH({col}${R_SCEN},ScenarioDefinition!${L(MT_COL0)}${MT_ROW_SCEN}:${MT_LAST}${MT_ROW_SCEN},0))')


def path_formula(col, y0, y1, start, target, linear_ext=None):
    """0 before y0; linear from start (at y0) to target (at y1). After y1: linear continuation (default; the fuel
    price reform and feebates have their own paths since v0.9.0, as legacy); the carbon price keeps its MTInputs switch (linear_ext cell, "Linear*" = continue,
    otherwise flat at the target, as legacy)."""
    y = f'{col}${R_YEAR}'
    slope = f'({target}-{start})/MAX({y1}-{y0},1)'
    if linear_ext is None:
        return f'=IF({y}<{y0},0,{start}+{slope}*({y}-{y0}))'
    return (f'=IF({y}<{y0},0,{start}+{slope}'
            f'*IF(OR({y}<={y1},{linear_ext}="Linear*"),{y}-{y0},{y1}-{y0}))')


def lam_or_plain(name, args, use_lambda):
    """v0.9.0: a LAMBDA call, or its plain formula (the body with the arguments substituted)."""
    return call(name, *args) if use_lambda else lambda_plain(name, args)


PIG_ECPS = {'gso': 'trs', 'die': 'trs', 'lpg': 'res', 'ker': 'res', 'oop': 'ind', 'bio': 'res'}   # ECP sector of
# an all-sector price block (the sector of the block otherwise; v0.9.0, R3.8)
POL_KIND = {p_[0]: p_[4] for p_ in POL}
TR1_BASE = {'pig.fe0.gso.pas':['fuel economy gasoline passenger', 'fuel economy light', 'ownership passenger',
                                  'ownership light'],
            'pig.fe0.die.pas': ['fuel economy diesel passenger', 'fuel economy light', 'ownership passenger',
                                'ownership light'],
            'pig.wsh.gso': ['share of gasoline for cycle'], 'pig.wsh.die': ['share of diesel for bus',
                                                                            'share of diesel for freight'],
            'pig.fe0.gso': ['fuel economy gasoline cycle'], 'pig.fe0.die': ['fuel economy diesel freight']}   # v0.9.0
# (PIGAP): Transport1 variables of the base year in D:G of the Pigouvian transport rows (legacy rows 2017-2121)


def _ap_line(f, S):
    """v0.9.0 (PIGAP): section-1 rows (first, last) of the marginal air-pollution costs of a unit-cost line."""
    ss = next(x for f_, S_, x in AP_LINES if (f_, S_) == (f, S))
    return R_POL[f'apmc.{f}.{S}.{ss[0]}'], R_POL[f'apmc.{f}.{S}.{ss[-1]}']


def _in_row(s_, f):
    """Inputs row of subsector s_ and fuel f (key fuel|subsector, subsector blocks of NF fuels)."""
    return IN_R0 + [x[0] for x in SUBSECTORS].index(s_) * NF + [x[0] for x in FUELS].index(f)


def pig_dg(key, r):
    """v0.9.0 (R3): D:G of the section-1 rows of the Pigouvian tax (None = empty)."""
    if key.startswith('apmc.'):              # PIGAP: base-year and EFEndYear coefficient x EF sums, base-year use
        _a, f, S, s_ = key.split('.')
        m = AP_POW_MOD[f] if s_ == 'pow' else AP_MOD_OF.get(s_, 'oth')
        if s_ == 'pow':
            i = IPW_R0 + [t for t, _n in PW_TECH].index(f)
            ef = f'Inputs_power!${IPWC[AP_EFCOLS[0]]}${i}:${IPWC[AP_EFCOLS[-1]]}${i}'
            w = 1
        else:
            i = _in_row(s_, f)
            ef = f'Inputs!${IC[AP_EFCOLS[0]]}${i}:${IC[AP_EFCOLS[-1]]}${i}'
            w = f'=Inputs!${IC["f0"]}${i}'
        k_ = lambda k: f'=IFERROR(SUMPRODUCT(INDEX(ApEf,MATCH(CtryCode&"|{m}|{k}",ApEfKey,0),0),{ef}),0)'
        return [k_(0), k_(1), w]
    if key == 'pig.trk':                     # Transport1 row of the country's base year
        return ['=IFERROR(MATCH(CtryCode&"|"&BaseYr,TrKey,0),0)']
    if key in TR1_BASE:
        t = R_POL['pig.trk']
        return [f'=IF($D${t}=0,0,INDEX(TrVal,$D${t},MATCH("{v_}",TrVar,0))+0)' for v_ in TR1_BASE[key]]
    if key.startswith('pig.mu0.'):           # road usage and efficiency elasticities (Inputs, road rows)
        u = lambda f: f'Inputs!${IC["eU"]}${_in_row("rod", f)}'
        e = lambda f: f'Inputs!${IC["eF"]}${_in_row("rod", f)}'
        if key.endswith('gso'):
            return [f'={u("gso")}', f'={e("gso")}']
        return [f'={u("die")}', f'={u("gso")}-{u("die")}', f'={u("die")}+{e("die")}',
                f'={u("gso")}+{e("gso")}-{u("die")}-{e("die")}']
    if key.startswith('pig.rsh0.'):          # base-year road use and use of all subsectors (Inputs f0)
        f = key.split('.')[2]
        c = IC['f0']
        return [f'=Inputs!${c}${_in_row("rod", f)}',
                f'=SUMIF(Inputs!${IC["fuel"]}${IN_R0}:${IC["fuel"]}${IN_R1},"{f}",Inputs!${c}${IN_R0}:${c}${IN_R1})']
    if key.startswith('pig.trg.'):           # per-km cost: data key, row on FromTransportCB, base-year value
        return [f'|tran.{key.split(".")[2]}.km', f'=IFERROR(MATCH(CtryCode&$D{r},TcbKey,0),0)',
                f'=IF($E{r}=0,0,INDEX(TcbVal,$E{r},MATCH(BaseYr,TcbYear,0)))']
    if key in PIGM_KEYS:
        return None
    v, pc = key.rsplit('.', 2)[0], '.'.join(key.rsplit('.', 2)[1:])
    fu, sec = pc.split('.')
    gj = f'=$F{prow("pset", pc)}' if pc in PV_BLOCK else None          # GJ per price unit of the block
    ef = f'=IFERROR(INDEX(EFGen,MATCH($B{r},EFGenKey,0)),0)'
    if v == 'pig.ap':                        # PIGAP: D GJ per price unit (coal, gas 1); E residential coal switch
        if fu not in ('coa', 'nga', 'gso', 'die', 'lpg', 'ker', 'oop'):
            return None
        d = gj if fu in ('gso', 'die', 'lpg', 'ker', 'oop') else 1
        if pc != 'coa.res':
            return [d]
        a, b = _ap_line('coa', 'res')
        c = IC['f0']
        bld = [x[0] for x in SUBSECTORS if x[2] == 'bld']
        tot = f'Inputs!${c}${_in_row(bld[0], FUELS[0][0])}:${c}${_in_row(bld[-1], FUELS[-1][0])}'
        assert _in_row(bld[-1], FUELS[-1][0]) - _in_row(bld[0], FUELS[0][0]) == len(bld) * NF - 1
        return [d, f'=--(SUM($F${a}:$F${b})>ApCoalResMin*SUM({tot}))']
    if v == 'cc.code':
        return [ef if gj else None, gj]
    if v == 'xcpb':
        ecps = sec if sec != 'all' else PIG_ECPS.get(fu, 'res')
        return ([ef, f'=IFERROR(MATCH("{ecps}|{fu}",XKey,0),1)', f'=INDEX(XCTVal,$E{r},ECPEmb)+INDEX(XETSVal,$E{r},ECPEmb)']
                if gj else None)
    if v == 'ntxb':
        return [gj]
    return None


def pig_calc(key, col, is_base):
    """v0.9.0 (R3.1-R3.9): formula of a section-1 row of the Pigouvian tax and the SCC (Equations_addendum C)."""
    c = lambda k: f'{col}${R_POL[k]}'
    rel = lambda k: f'{col}{R_POL[k]}'
    y = f'{col}${R_YEAR}'
    r = R_POL[key]
    if key == 'pig.phi':                     # R3.1 (L195, L196 fixed: every year from CPIntro, no #DIV/0!)
        return f'=MIN(MAX({y}-{c("CPIntro")}+1,0)/MAX({c("AddEfficientTaxesPhaseInYears")},1),1)'
    if key == 'pig.efw':                     # PIGAP: emission-factor path weight, as section 15 ap.w (inputs only)
        return f'=EFFinShare*({y}-BaseYr)/(EFEndYear-BaseYr)'
    if key == 'pig.vpm':                     # PIGAP: value of averted PM2.5; 2022 (no change in legacy) takes 2023
        return f'=IFERROR(INDEX(ApVal,MATCH(CtryCode&"|air.vpm",ApKey,0),MATCH(MAX({y},BaseYr+1),ApYear,0)),0)'
    if key.startswith('apmc.'):              # PIGAP: USD bn per ug/m3 x ug/m3 per ktoe -> USD/GJ
        w = c('pig.efw')
        return f'={c("pig.vpm")}*($D{r}*(1-{w})+$E{r}*{w})*Billion/PJperKtoe/Million'
    if key == 'pig.trk':
        return f'=$D{r}'
    if key.startswith('pig.fe0.') and key.endswith('.pas'):   # ownership mix of passenger and light (legacy trfem)
        return f'=IF($F{r}+$G{r}=0,$D{r},($D{r}*$F{r}+$E{r}*$G{r})/($F{r}+$G{r}))'
    if key == 'pig.wsh.gso':                 # passenger and light share of gasoline (2-3 wheelers the rest)
        return f'=1-$D{r}'
    if key == 'pig.wsh.die':                 # passenger and light share of diesel without buses (as legacy w_f)
        return f'=IF($D{r}>=1,0,1-$E{r}/(1-$D{r}))'
    if key.startswith('pig.fe0.'):           # base-year average fuel economy by class share (legacy AVGFE)
        f = key.split('.')[2]
        w = rel(f'pig.wsh.{f}')
        return f'={w}*{rel(f"pig.fe0.{f}.pas")}+(1-{w})*$D{r}'
    if key == 'pig.mu0.gso':                 # driving share of the response (R1.8, w = 1)
        return f'=IF($D{r}+$E{r}=0,0,$D{r}/($D{r}+$E{r}))'
    if key == 'pig.mu0.die':
        w = rel('pig.wsh.die')
        return f'=IFERROR(($D{r}+{w}*$E{r})/($F{r}+{w}*$G{r}),0)'
    if key.startswith('pig.rsh0.'):
        return f'=IF($E{r}=0,0,$D{r}/$E{r})'
    if key.startswith('pig.kpl.'):           # driving-weighted km per litre of the base year
        f = key.split('.')[2]
        return '=' + '*'.join(rel(f'pig.{k}.{f}') for k in ('fe0', 'mu0', 'rsh0'))
    if key.startswith('pig.trg.'):           # growth of the per-km cost relative to the base year
        return f'=IF($F{r}=0,0,INDEX(TcbVal,$E{r},MATCH({y},TcbYear,0))/$F{r})'
    if key.startswith('pig.trb.'):           # base-year value per litre: base-year per-km cost x km per litre
        _p, _t, k, f = key.split('.')
        base = f'=$F${R_POL["pig.trg." + k]}*{rel("pig.kpl." + f)}'
        return base + (f'*(1-{rel("pig.wsh." + f)})' if k == 'rdm' else '')   # road damage: freight share
    if key == 'scc.man':
        return f'=INDEX(SCCManVal,MATCH({y},SCCManYear,0))'   # v0.5.2 (L103 fixed): Manual inputs row 237
    if key in ('scc.nat', 'scc.glo'):
        fu = key[4:]
        src = 'NSCCSrc' if fu == 'nat' else 'GSCCSrc'
        opts = ','.join(rel(f'scc.{k}') for k in ('tgt', 'rkn' if fu == 'nat' else 'rkg', 'man', 'epa'))
        return f'=CHOOSE(MATCH(LEFT({src},1),{{"T","R","M","U","E"}},0),{opts},{opts.split(",")[-1]})'
    v, pc = key.rsplit('.', 2)[0], '.'.join(key.rsplit('.', 2)[1:])
    if v == 'pig.ap':                        # R3.4 with marginal damages (PIGAP, I104 fixed): base-year weights
        fu, sec = pc.split('.')
        if fu not in ('coa', 'nga', 'gso', 'die', 'lpg', 'ker', 'oop'):
            return '=0'                      # electricity (issue I119), biomass
        a, b = _ap_line(fu, 'pow' if fu == 'oop' else sec)   # other oil products: power cost x GJ per barrel (L194)
        sw = f'*$E{r}' if pc == 'coa.res' else ''
        if a == b:
            return f'={col}{a}*$D{r}'
        return (f'=IFERROR(SUMPRODUCT({col}{a}:{col}{b},$F${a}:$F${b})/SUM($F${a}:$F${b}),'
                f'AVERAGE({col}{a}:{col}{b}))*$D{r}{sw}')
    if v == 'pig.tr':                        # R3.5: only gasoline and diesel (issue I118); PIGAP: base x growth
        fu = pc.split('.')[0]
        if fu not in ('gso', 'die'):
            return '=0'
        ks = ['acc', 'con'] + (['rdm'] if fu == 'die' else [])
        return '=' + '+'.join(f'{rel(f"pig.trb.{k}.{fu}")}*{rel("pig.trg." + k)}' for k in ks)
    if v == 'cc.code':                       # R3.2-R3.3: national SCC x generic EF x GJ per price unit
        return f'={c("scc.nat")}*$D{r}*$E{r}'
    if v == 'pigx':                          # R3.6
        a = (rel(f'pig.ap.{pc}'), rel(f'cc.code.{pc}'), rel(f'pig.tr.{pc}'))
        return f'={c("pig.phi")}*({a[0]}+{a[1]}*(LEFT({c("ClimateEffTax")},3)="Yes")+{a[2]})'
    if v == 'ntxg':                          # R3.7 (the manual fossil excise is not built, R8)
        return f'={rel("fpr." + pc)}+{rel("pigx." + pc)}*(LEFT({c("AddEfficientTaxes")},3)="Yes")'
    if v == 'xcpb':                          # R3.8: change in existing carbon pricing of the block ($/GJ)
        if pc not in PV_BLOCK:
            return '=0'
        return '=' + xcarbon_plain(xcarbon_args(col, f'$D{r}', f'$E{r}', f'$F{r}'))
    if v == 'xpre':                          # R3.8: existing taxes before new policy ($/GJ); electricity: 0
        if pc not in PV_BLOCK:
            return '=0'
        return '=' + '+'.join(f'{col}${prow(x, pc)}' for x in ('txo', 'pcsw', 'ppcw')) + f'+{rel("xcpb." + pc)}'
    if v == 'ntxb':                          # R3.9 (issue I113): policy scenarios only; netted if AddEfficientTaxes
        g, x = rel(f'ntxg.{pc}'), rel(f'xpre.{pc}')
        return (f'=({col}${R_SCEN}>1)*IF(LEFT({c("AddEfficientTaxes")},3)="Yes",MIN({g},MAX(0,{g}-{x}*$D{r})),{g})')
    raise ValueError(key)


def pol_calc(key, col, use_lambda=False, is_base=False):
    c = lambda k: f'{col}${R_POL[k]}'          # fixed rows (years, carbon-tax inputs): absolute
    rel = lambda k: f'{col}{R_POL[k]}'          # start / final values: relative, so a path drags down
    y = f'{col}${R_YEAR}'
    if key in ('scc.tgt', 'scc.rkn', 'scc.rkg', 'scc.epa'):   # v0.9.0: the SCC paths (moved from section 18; v0.3.17)
        lv, yrs = {'scc.tgt': ('SCCTgt', f'{y}-SCCTgtYr'), 'scc.epa': ('SCCEpa', f'{y}-BaseYr'),
                   'scc.rkn': ('INDEX(SCCVal,MATCH(RickeN,SCCKey,0))', f'{y}-BaseYr'),
                   'scc.rkg': ('INDEX(SCCVal,MATCH(RickeG,SCCKey,0))', f'{y}-BaseYr')}[key]
        return '=' + (call('GROWPATH', lv, 'SCCGr', yrs) if use_lambda else f'{lv}*(1+SCCGr)^({yrs})')
    if POL_KIND.get(key) == 'plain':
        return pig_calc(key, col, is_base)
    if key == 'exph':                        # v0.5.6: exemption phase-out (legacy rows 2259-2265, L94)
        a = (f'{col}${R_SCEN}', c('ExemptPhaseout'), y, c('CPIntro'), c('YearPha'), c('ExemptPhaseoutPeriod'))
        return '=' + (call('EXEMPTPHASE', *a) if use_lambda else
                      f'IF(AND({a[0]}>1,{a[1]}=TRUE,{a[2]}>={a[3]}),MAX(MIN(({a[2]}+1-{a[4]})/{a[5]},1),0),0)')
    if key == 'cptraj':                      # nominal inputs (NomorReal = Nominal) x CPI index (legacy row 2249)
        if use_lambda:
            return '=' + call('PATH', y, c('CPIntro'), c('CPOutro'), c('CPLevelStart'), c('CPLevelTarget'),
                              f'{c("ExtendCarbonPriceBeyondOutro")}="Linear*"') + '*' + c('cp.nom')
        y0, s0, s1 = c('CPIntro'), c('CPLevelStart'), c('CPLevelTarget')
        return f'=IF({y}<{y0},0,{s0}+({s1}-{s0})/MAX({c("CPOutro")}-{y0},1)*{c("cp.t")})*{c("cp.nom")}'
    if key == 'mfee.p':                      # v0.2.8: methane fee path, linear after the target year (legacy)
        a = (c('MPIntro'), c('MPOutro'), c('MPLevelStart'), c('MPLevelTarget'))
        if use_lambda:
            return '=' + call('PATH', y, *a, 'TRUE')
        return path_formula(col, *a)
    if key == 'mfee':                        # v0.2.8: + carbon price if the carbon tax applies to methane
        a = (c('mfee.p'), f'({col}${R_SCEN}>1)', c('CTforMethane'), c('cptraj'))   # v0.4.12 (LD46): the fee only in
        return '=' + (call('METHANEFEE', *a) if use_lambda          # policy scenarios (number > 1), as legacy 2238
                      else f'{a[0]}*{a[1]}+IF(LEFT({a[2]},3)="Yes",{a[3]},0)')
    if key == 'cp.t':                        # years along the path (linear after the target year if Linear*)
        a = (y, c('CPIntro'), c('CPOutro'), c('ExtendCarbonPriceBeyondOutro'))
        if use_lambda:
            return '=' + call('PATHYEARS', a[0], a[1], a[2], f'{a[3]}="Linear*"')
        return f'=IF({a[3]}="Linear*",{y},MIN({y},{a[2]}))-{a[1]}'
    if key == 'cp.nom':                      # nominal inputs: x CPI index; real: 1
        a = (c('NomorReal'), f'{col}${R_CPI}')
        return '=' + (call('NOMFACTOR', *a) if use_lambda else f'IF(LEFT({a[0]},7)="Nominal",{a[1]},1)')
    if key.startswith('fpr.') or (key.startswith('fb.') and key not in ('fb.yr0', 'fb.yr1')):
        pre, k = ('fpr', key[4:]) if key.startswith('fpr.') else ('fb', key[3:])
        y0, y1 = c(f'{pre}.yr0'), c(f'{pre}.yr1')
        s0, s1 = (rel('fprs.' + k), rel('fprf.' + k)) if pre == 'fpr' else (rel('fbs.' + k), rel('fbt.' + k))
        if pre == 'fb':                      # v0.9.0 (LD10 reverted): feebates flat at the target after the target
            if use_lambda:                   # year, as legacy rows 2001-2004 (L174: no #DIV/0! when start = target)
                return '=' + call('PATH', y, y0, y1, s0, s1, 'FALSE')
            return f'=IF({y}<{y0},0,{s0}+({s1}-{s0})/MAX({y1}-{y0},1)*(MIN({y},{y1})-{y0}))'
        a = (y, y0, y1, c('ExtendCarbonPriceBeyondOutro'), s0, rel('fprj.' + k), rel('fpra.' + k))   # v0.9.0 (LD10
        return '=' + lam_or_plain('FPRPATH', a, use_lambda)      # reverted): follows the switch (legacy 167-180)
    if key.split('.')[0] in ('fprj', 'fprk', 'fprp', 'fpra'):   # v0.9.0: helper rows of the fuel price reform path
        v, k = key.split('.', 1)
        y0, y1, s0, s1 = c('fpr.yr0'), c('fpr.yr1'), rel('fprs.' + k), rel('fprf.' + k)
        ext = c('ExtendCarbonPriceBeyondOutro')
        a = {'fprj': ('FPRSLOPE', (y0, y1, s0, s1)),
             'fprk': ('FPRRATE', (y0, y1, s0, s1, rel('fprj.' + k))),
             'fprp': ('FPRBASE', (y0, y1, s0, rel('fprj.' + k))),
             'fpra': ('FPRAFTER', (y, y0, y1, ext, s0, s1, rel('fprp.' + k), rel('fprk.' + k)))}[v]
        return '=' + lam_or_plain(*a, use_lambda)
    on = f'{c("ets.on")}=1'
    bco2 = pol_range(col, 'bco2.pow', len(COV_SECTORS))
    etsc = pol_range(col, 'etsc.pow', len(COV_SECTORS))
    if key == 'ets.on':                      # the new ETS applies and has started
        a = (c('NewETS'), y, c('ETSIntro'))
        return '=' + (call('ETSON', *a) if use_lambda else f'IF(AND(LEFT({a[0]},3)="Yes",{y}>={a[2]}),1,0)')
    if key == 'ets.p':
        a = (c('ets.on'), c('ETSPriceOverride'), c('ets.ovr'), c('ets.est'), c('cptraj'))
        return '=' + (call('ETSPRICE', *a) if use_lambda else
                      f'IF({on},IF(LEFT({a[1]},3)="Yes",IF({a[2]}="",{a[4]},{a[2]}),{a[3]}),0)')
    if key.startswith('etsb.'):              # benchmark: linear from start to target year, flat after
        y0, y1, s0, s1 = c('ETSIntro'), c('ETSOutro'), rel('etsbs.' + key[5:]), rel('etsbt.' + key[5:])
        if use_lambda:
            return '=' + call('PATH', y, y0, y1, s0, s1, 'FALSE')
        return f'=IF({y}<{y0},0,{s0}+({s1}-{s0})/MAX({y1}-{y0},1)*(MIN({y},{y1})-{y0}))'
    if key.startswith('obr.'):
        b = f'INDEX({pol_range(col, "etsb.pow", len(ETS_GROUPS))},$D{R_POL[key]})'
        return '=' + (call('OBRSHARE', b) if use_lambda else f'MIN(1,MAX(0,{b}))')
    if key in ('ets.vol', 'ets.imp'):         # Settings volatility table: value for the MTInputs label
        lab, vals = ((c('ETSVolatility'), 'Settings!$C$17:$F$17') if key == 'ets.vol'
                     else (c('ETSVolImpact'), 'Settings!$C$18:$F$18'))
        if use_lambda:
            return '=' + call('VOLPICK', lab, vals)
        return f'=INDEX({vals},MATCH(SUBSTITUTE({lab},"*",""),Settings!$C$16:$F$16,0))'
    if key == 'ets.vadj':
        a = (c('ets.vol'), c('ets.imp'), c('ETSCTRisk'))
        return '=' + (call('VOLADJ', *a) if use_lambda else f'(1+{a[2]}*{a[1]})/(1+{a[0]}*{a[1]})')
    if key == 'ets.bce':
        return '=' + (call('COVERED', bco2, etsc) if use_lambda else f'SUMPRODUCT({bco2},{etsc})')
    if key == 'ets.chg':                     # relative cap change: linear from start to target year, flat after
        a = (y, c('ETSIntro'), c('ETSOutro'), c('ETSChangeRelStart'), c('ETSChangeRelTarget'))
        if use_lambda:
            return '=' + call('CAPCHANGE', *a)
        return f'={a[3]}+({a[4]}-{a[3]})/MAX({a[2]}-{a[1]},1)*(MIN({y},{a[2]})-{a[1]})'
    if key == 'ets.cap':
        a = (c('ets.on'), y, c('ETSOutro'), c('ETSCapCont'), c('ets.bce'), c('ets.chg'),
             f'{L(CI_(col) - 1)}${R_POL["ets.cap"]}')
        if use_lambda:
            return '=' + call('ETSCAP', *a)
        return f'=IF({on},IF(AND({y}>{a[2]},LEFT({a[3]},8)="Constant"),{a[6]},{a[4]}*(1+{a[5]})),0)'
    if key == 'ets.se':                      # baseline-weighted semi-elasticity x allocation effectiveness
        obr = pol_range(col, 'obr.pow', len(COV_SECTORS))
        if use_lambda:
            return '=' + call('ETSSEMI', bco2, etsc, 'SemiEl', obr, 'OBREff', c('ets.bce'))
        return f'=IF({c("ets.bce")}>0,SUMPRODUCT({bco2},{etsc},SemiEl,1-(1-OBREff)*{obr})/{c("ets.bce")},0)'
    if key == 'ets.est':
        a = (c('ets.on'), c('ets.cap'), c('ets.bce'), c('ets.se'), c('ets.vadj'))
        if use_lambda:
            return '=' + call('ETSESTIMATE', *a)
        return f'=IF(AND({on},{a[1]}>0,{a[1]}<{a[2]},{a[3]}<0,{a[4]}>0),LN({a[1]}/{a[2]})/({a[3]}*{a[4]}),0)'
    if key == 'ets.pe':
        return '=' + (call('TAXEQUIV', c('ets.p'), c('ets.vadj')) if use_lambda else f'{c("ets.p")}*{c("ets.vadj")}')
    if key == 'exf.res':                     # v0.5.1 (D16, I50): residential LPG and kerosene always exempted
        a = c(RES_PARAMS[0])                 # (LEFT(x, 3): a starred Yes* counts too; legacy tests the exact "Yes")
        return '=' + (call('EXEMPTFACTOR', a) if use_lambda else f'IF(LEFT({a},3)="Yes",0,1)')
    if key == 'scn':                         # v0.4.16 (LD9): column of the legacy scenario table (0: not found)
        a = (c('ScenarioSelected'),)
        return '=' + (call('SCNROW', *a) if use_lambda else f'IFERROR(MATCH({a[0]},ScnName,0),0)')
    if key == 'cp.exp':                      # explicit pricing (1) or shadow pricing (0), legacy row 259
        a = (c('scn'),)
        return '=' + (call('EXPLICIT', *a) if use_lambda else f'IF({a[0]}=0,1,--(INDEX(ScnExpl,{a[0]})="Yes"))')
    if key == 'cpx':                         # explicit carbon price (carbon tax rates ctr)
        a = (f'{col}${R_CP}', c('cp.exp'))
        return '=' + (call('SCALEBY', *a) if use_lambda else f'{a[0]}*{a[1]}')
    if key == 'cp.shd':                      # shadow carbon price (legacy row 2375 "General carbon price")
        a = (f'{col}${R_CP}', c('cpx'))
        return '=' + (call('DIFF', *a) if use_lambda else f'{a[0]}-{a[1]}')
    if key == 'regadj':                      # efficiency adjustment of the scenario (MTInputs rows 247-251)
        a = (c('scn'), f'{col}${R_POL[REG_PARAMS[1]]}:{col}${R_POL[REG_PARAMS[-1]]}')
        return '=' + (call('REGADJ', *a) if use_lambda else
                      f'IF({a[0]}=0,0,IF(INDEX(ScnAdj,{a[0]})=0,0,INDEX({a[1]},INDEX(ScnAdj,{a[0]}))))')
    if key.startswith('regc.'):              # sector covered by the scenario's regulation (legacy rows 240-257)
        a = (c('scn'), f'$D{R_POL[key]}')
        return '=' + (call('REGCOVER', *a) if use_lambda else
                      f'IF({a[0]}=0,0,--(INDEX(ScnCov,{a[0]},{a[1]})="Yes"))')
    if key.startswith('reg.'):               # regulation shadow price = shadow carbon price x adjustment x coverage
        a = (c('cp.shd'), c('regadj'), rel('regc.' + key[4:]))
        return '=' + (call('REGSHADOW', *a) if use_lambda else f'{a[0]}*{a[1]}*{a[2]}')
    if key.startswith('po.'):                # v0.4.16 (LD18, LD19): phase-out switch, period and share of the scenario
        v_, k_ = key.rsplit('.', 1)
        po = next(x for x in PHASEOUTS if x[0] == k_)
        sc = f'{col}${R_SCEN}'
        if v_ == 'po.on':                    # scenario 1: the baseline switch; else the policy switch (legacy 264-274)
            a = (sc, c(po[3]), c(po[2]))
            fn_ = 'PCON' if k_ == 'pc' else 'PHASEON'
            if use_lambda:
                return '=' + call(fn_, *a)
            yes = lambda x: f'OR({x}=TRUE,LEFT({x},3)="Yes")'
            return (f'=AND({yes(a[2])},OR({a[0]}>1,{yes(a[1])}))*1' if k_ == 'pc'
                    else f'=IF({a[0]}=1,{yes(a[1])},{yes(a[2])})*1')
        if v_ == 'po.n':
            a = (sc, c(po[6]), c(po[5]))
            return '=' + (call('PICKSCEN', *a) if use_lambda else f'IF({a[0]}=1,{a[1]},{a[2]})')
        a = (sc, c(po[8]), c(po[7]))          # share: policy = MAX(baseline, policy), legacy G267/G271
        return '=' + (call('PHASESHARE', *a) if use_lambda else f'IF({a[0]}=1,{a[1]},MAX({a[1]},{a[2]}))')
    if key.startswith('pof.'):               # factor: MAX(1 - share, 1 - share x (t - T0) / N after T0), legacy 2213-2216
        k_ = key[4:]
        po = next(x for x in PHASEOUTS if x[0] == k_)
        a = (y, c(f'po.on.{k_}'), c(po[4]), c(f'po.n.{k_}'), c(f'po.sh.{k_}'))
        return '=' + (call('PHASEOUT', *a) if use_lambda else
                      f'MAX(1-{a[4]},IF({a[1]}*({a[0]}>{a[2]}),1-{a[4]}*({a[0]}-{a[2]})/MAX({a[3]},1),1))')
    if key.startswith(('csf.', 'pcf.', 'psf.')):   # line by price fuel | sector (producer: by fuel): 1 - incl x (1 - phi)
        pre, code = key.split('.', 1)
        a = (rel(f'{pre[:2]}i.{code}'), c('pof.' + {'csf': 'cs', 'pcf': 'pc', 'psf': 'ps'}[pre]))
        return '=' + (call('INCLFACTOR', *a) if use_lambda else f'1-{a[0]}*(1-{a[1]})')
    if key.startswith('pros.'):              # producer subsidy (USD m real): data up to the last price year, then held
        prev = L(CI_(col) - 1)
        a = (y, 'LastHist', f'IFERROR(INDEX(MPU,MATCH({y},MPUYr,0),$D{R_POL[key]})+0,0)', f'{col}${R_CPI}',
             f'{prev}{R_POL[key]}')
        return '=' + (call('PRODSUB', *a) if use_lambda else f'IF({a[0]}<={a[1]},{a[2]}*{a[3]}*MperBn,{a[4]})')
    if key.startswith('psd.'):               # v0.6.1 (I49): demand spreading the subsidy, legacy rows 825-829
        f_ = key[4:]
        wd = f'{col}${R_GHG.get("ch4.wd." + f_, 0)}*Thousand'
        a = {'oil': (wd, wd, 'LitersPerKtoeOil'), 'coa': (wd, 'ConsCoa', 'MethGJperKtoe'),
             'nga': (wd, 'ConsGas', 'MethGJperKtoe'), 'bio': ('ConsBio', 'ConsBio', 'MethGJperKtoe')}[f_]
        if use_lambda:                       # v0.6.2: one LAMBDA (oil: world only; biomass: domestic only)
            return '=' + call('PSDEMAND', *a)
        return '=' + {'oil': f'{wd}*LitersPerKtoeOil', 'coa': f'AVERAGE({wd},ConsCoa)*MethGJperKtoe',
                      'nga': f'AVERAGE({wd},ConsGas)*MethGJperKtoe', 'bio': 'ConsBio*MethGJperKtoe'}[f_]
    if key.startswith('psu.'):               # v0.6.1 (I49): per unit up to the last price year, then the last value x
        f_ = key[4:]                         # the phase-out factor (v0.9.0, R7.1: as legacy O2455 = $J2456 x O2213)
        prev = L(CI_(col) - 1)
        a = (y, c('pros.' + f_), c('psd.' + f_), f'INDEX($A{R_POL[key]}:{prev}{R_POL[key]},{col}${R_LHCOL})',
             c('psf.' + f_))
        return '=' + (call('PRODSUBUNIT', *a) if use_lambda else
                       f'IF({a[0]}<=LastHist,IFERROR(-{a[1]}*USDperM/{a[2]},0),{a[3]}*{a[4]})')
    if key.startswith(('etsbs.', 'etsbt.')):  # v0.4.15 (I21): benchmark = 1 - auctioned share (MTInputs rows 90-91)
        a = c('ETSAuctStart' if key.startswith('etsbs.') else 'ETSAuctTarget')
        return '=' + (call('FREESHARE', a) if use_lambda else f'1-{a}')
    if key == 'ets.rf':
        v = c('ets.vadj')
        return '=' + (call('REVFACTOR', v) if use_lambda else f'IF({v}>0,1/{v},0)')
    if key.startswith('etsc.'):
        a = (c('ets.on'), rel('etscv.' + key[5:]))
        return '=' + (call('ETSCOVER', *a) if use_lambda else f'IF({on},IF({a[1]},1,0),0)')
    if key.startswith('ctr.'):               # carbon tax rate of this sector ($/tCO2), not where the ETS covers it
        # v0.1.09: CTaxComplimentaryToETS = Yes -> coverage 1 - existing ETS sector coverage; v0.4.12: the national ETS
        # coverage of the year (D = its row in the Inputs_ecp table; legacy rows 2270-2288, bug L65 fixed)
        a = (c('cpx'), rel('sc.' + key[4:]), rel('etsc.' + key[4:]), c('CTaxComplimentaryToETS'),   # v0.4.16: explicit
             f'INDEX(ECPVal,$D{R_POL[key]},{c("xct.c")})')
        return '=' + (call('SECTORTAX', *a) if use_lambda else
                      f'{a[0]}*IF(LEFT({a[3]},3)="Yes",1-{a[4]},{a[1]})*(1-{a[2]})')
    if key == 'xct.c':                       # v0.4.12: data column of the year (last data year after)
        return f'=MATCH(MIN({y},ECPLast),ECPYear,0)'
    if key in ('xct.p', 'xets.p'):           # v0.1.09; v0.4.12: factor = switch x (1 + growth) after the last data year
        sch = key.split('.')[0]
        sw, g = (('ExistingCTApply', 'ExistingCTGrowth') if sch == 'xct'
                 else ('ExistingETSApply', 'ExistingETSGrowth'))
        a = (c(sw), c(g), y)
        return '=' + (call('ECPFACTOR', *a) if use_lambda else
                      f'IF(LEFT({a[0]},3)="Yes",(1+{a[1]})^MAX(0,{y}-ECPLast),0)')
    if key.startswith('etr.'):               # ETS cost in the fuel price of this sector ($/tCO2), auctioned part
        a = (c('ets.pe'), rel('etsc.' + key[4:]), rel('obr.' + key[4:]))
        return '=' + (call('SECTORETS', *a) if use_lambda else f'{a[0]}*{a[1]}*(1-{a[2]})')
    if key.startswith('shpx.'):              # shadow price on the efficiency margin ($/tCO2) of this sector
        s = key[5:]
        a = (f'INDEX({pol_range(col, "fb." + FEEBATE_SECTORS[0][0], len(FEEBATE_SECTORS))},$D{R_POL[key]})',
             rel('ssc.' + s), rel('reg.' + s), c('ets.pe'), rel('etsc.' + s), rel('obr.' + s))   # v0.4.16: + reg
        return '=' + (call('SHADOWTOTAL', *a) if use_lambda else f'{a[0]}*{a[1]}+{a[2]}+{a[3]}*{a[4]}*{a[5]}')
    if key.startswith('ssc.'):              # v0.4.16: x MTInputs row 251 SPPEffAdjFeebates (was the constant 1.0)
        a = (rel('fbc.' + key[4:]), c('SPPEffAdjFeebates'))
        return '=' + (call('SHADOWSHARE', *a) if use_lambda else f'IF({a[0]},1,0)*{a[1]}')
    raise ValueError(key)


# ---------------------------------------------------------------- Mitigation
def lam_row(c, r, var, fuel, sector, formula):
    """Record the LAMBDA alternative of a calculated row (right column of scenario 1) for sheet Lambdas."""
    if c == group_cols(1)[2][-1] and formula is not None:
        LAMBDA_ROWS.append((r, var, fuel, sector, formula))


def build_mitigation(wb):
    ws = wb.create_sheet('Mitigation', 1)
    groups = [s[0] for s in SCENARIOS]
    last = COL_G0 + len(groups) * GW - 1
    outline = {}                                            # row -> (level, hidden)
    for j, h in enumerate(['Variable', 'Fuel', 'Sector'], 1):
        put(ws, f'{L(j)}1', h, FONT_B)
    for col in PARAM_COLS:                   # v0.2.4: each block's parameters are named in the label row above it
        put(ws, f'{col}1', f'Param {PARAM_COLS.index(col) + 1}: see label row', FONT_B)
    for col, h in DESC.items():
        put(ws, f'{col}1', h, FONT_B)
    title(ws, 'Mitigation Module', last)       # v0.2.7: short title (version and description: ReadMe, Settings)
    band(ws, R_SEC0, '0. Scenario assumptions', last)   # v0.4.1: numbered 0
    put(ws, f'H{R_LHCOL}', 'Column number of the last historical price year (helper: section 2 reads the last '
                           'historical excise and other taxes there)', FONT)
    put(ws, f'H{R_SCEN}', 'Scenario number (MTInputs column)', FONT_B)
    put(ws, f'H{R_NAME}', 'Scenario name (from MTInputs)', FONT_B)

    lab_font = Font(name='Arial', size=10, bold=True)          # v0.3.9: table header row: bold, thin bottom border

    def label_row(r, src, head=None):
        """v0.2.4: label row r above a block: D:G name the parameters of the block's variable (row src, Variables
        G:J); H the variable (or the sub-heading text head)."""
        for j, pc in enumerate(PARAM_COLS, 1):
            put(ws, f'{pc}{r}', f'=INDEX(VarP{j},MATCH($A{src},VarKey,0))&""', lab_font)
        if head is None:
            put(ws, f'H{r}', f'=INDEX(VarLab,MATCH($A{src},VarKey,0))', lab_font)
        else:
            put(ws, f'H{r}', head, lab_font)
        border_bottom(ws, r, 1, last)                     # v0.3.9: legacy header row
        LABEL_ROWS.add(r)

    def describe(r, font=FONT):
        put(ws, f'H{r}', label_formula(r), font)
        put(ws, f'I{r}', '=' + var_lookup('C', r), font)
        put(ws, f'J{r}', '=' + var_lookup('E', r), font)

    def ids(r, var, fuel, sector, font=FONT):
        put(ws, f'A{r}', var, FONT)            # v0.2.6: variable, fuel and sector names are never bold
        put(ws, f'B{r}', fuel, FONT)
        put(ws, f'C{r}', sector, FONT)
        describe(r, font)

    def codes(r, font=FONT):
        it_font = Font(name=font.name, size=font.sz, bold=font.b, italic=True, color=font.color)   # v0.3.9: italic
        for g in groups:
            cc = L(group_cols(g)[0])
            put(ws, f'{cc}{r}', code_formula(r, cc), it_font, F_CODE)

    def each_col(fn):
        for g in groups:
            _, base, years = group_cols(g)
            for c in [base] + years:
                fn(c, c == base, c == years[-1])

    def sub_blocks(blocks, R, RL, RH, cellf):
        """v0.3.14: write results sub-blocks; cellf(col, r, key, var, fu, sec, is_base, lam) -> (formula, format).
        lam: LAMBDA column of the row (the cell calls a named LAMBDA there)."""
        for head, rows_ in blocks:
            if head is None:                  # v0.4.1: summary rows of the section (no heading, no label row)
                continue
            subhead(ws, RH[head], head)
            outline[RH[head]] = (1, True)
            label_row(RL[head], R[rows_[0][0]])
        for key, var, fu, sec in [x for _h, rows_ in blocks for x in rows_]:
            r = R[key]
            fnt = FONT_SUM if r in SUMMARY2 or any(r == t for _b, t, _z in SECTION_GROUPS) else FONT
            ids(r, var, fu, sec, fnt)
            codes(r, fnt)
            outline[r] = (1, True)

            def fc(c, is_base, is_last, r=r, key=key, var=var, fu=fu, sec=sec, fnt=fnt):
                f, fmt = cellf(L(c), r, key, var, fu, sec, is_base, is_last)
                lam = is_last and 'LAMBDA' not in f and f.startswith('=') and f[1:].split('(')[0] in LAMBDAS
                put(ws, f'{L(c)}{r}', f, fnt, F_LAMBDA if lam else (F_BASE if is_base else None), fmt)
                if lam:
                    lam_row(c, r, var, fu, sec, f)
            each_col(fc)

    def chg_of(col, lvl):
        """Change of row lvl against scenario 1 in this column's year (helper row R_REFCOL)."""
        return f'={col}{lvl}-INDEX(${L(COL_G0)}{lvl}:{col}{lvl},{col}${R_REFCOL})'

    # Scenario assumption rows
    ids(R_GDP, 'gdp.pos.pct', '', '', FONT_B)
    codes(R_GDP)
    for r_, v_ in ((R_CPI, 'infl'), (R_DEFL, 'defl')):
        ids(r_, v_, '', '')
        codes(r_)
    for r_, v_ in ((R_GDPUSD, 'gdp.usd'), (R_GDPLCU, 'gdp.lcu'), (R_XR, 'xr')):   # v0.3.13: GDP level, exchange rate
        ids(r_, v_, 'all', 'all')
        codes(r_)
    for g, gname, _ in SCENARIOS:
        code, base, years = group_cols(g)
        cc = L(code)
        put(ws, f'{cc}1', 'Scenario: output code', FONT_B)    # v0.4.1: same text in every group (copy-pasteable)
        put(ws, f'{cc}{R_SCEN}', f'=COUNTIF(${L(COL_G0)}$1:{cc}$1,"Scenario*")', FONT_B, None, '0')   # v0.4.1: n-th group
        put(ws, f'{L(base)}{R_NAME}', (f'=INDEX(ScenarioDefinition!${L(MT_COL0)}${MT_ROW_NAME}:${MT_LAST}${MT_ROW_NAME},'
                                       f'MATCH({L(base)}${R_SCEN},ScenarioDefinition!${L(MT_COL0)}${MT_ROW_SCEN}:'
                                       f'${MT_LAST}${MT_ROW_SCEN},0))'), FONT_B)

    def top(c, is_base, is_last):
        col, prev = L(c), L(c - 1)
        bf = F_BASE if is_base else None
        put(ws, f'{col}{R_YEAR}', '=Settings!$C$7' if is_base else f'={prev}{R_YEAR}+1', FONT_B, bf, '0')
        put(ws, f'{col}{R_LHCOL}', f'=COLUMN()+LastHist-{col}${R_YEAR}', FONT, bf, '0')   # v0.2.5: helper (section 2)
        put(ws, f'{col}{R_REFCOL}', f'=MATCH({col}${R_YEAR},${L(COL_G0)}${R_YEAR}:{col}${R_YEAR},0)', FONT, bf, '0')
        put(ws, f'{col}{R_SHOCK}', f'=1+{col}${R_PW[("shock", "")]}*Settings!$C$19', FONT, bf, '0.0000')   # v0.3.11
        put(ws, f'{col}{R_GDPI}', f'=(1+{col}${R_GDP})^{col}${R_PW[("incf", "")]}-1', FONT, bf, '0.0%')   # v0.4.12
        put(ws, f'{col}{R_SCEN}', f'={prev}{R_SCEN}', FONT, bf, '0')
        gb, lv = f'{col}{R_GDPS["gdp.base"]}', f'{col}{R_GDPS["gdp.lvl"]}'   # v0.3.1: after the GDP feedback
        if is_base:
            fg = f'={gb}'
        elif is_last:
            fg = '=' + call('GDPGROWTH', gb, lv, f'{prev}{R_GDPS["gdp.lvl"]}')
            lam_row(c, R_GDP, 'gdp.pos.pct', '', '', fg)
        else:
            fg = f'=(1+{gb})*{lv}/{prev}{R_GDPS["gdp.lvl"]}-1'
        put(ws, f'{col}{R_GDP}', fg, fill_=F_LAMBDA if is_last else bf, fmt='0.0%')
        for r_, key, base_ in ((R_CPI, 'USA|pcpi', 'CPIRes'), (R_DEFL, 'USA|ngdp_d', 'DeflRes')):
            put(ws, f'{col}{r_}', f'={base_}/INDEX(WEOVal,MATCH("{key}",WEOKey,0),MATCH({col}${R_YEAR},WEOYear,0))',
                fill_=bf, fmt='0.0000')
        for r_, _v, item, fm in HEAD_DATA:                  # v0.3.13: data rows (sheet WEO)
            put(ws, f'{col}{r_}', f'=INDEX(WEOVal,MATCH(CtryCode&"|{item}",WEOKey,0),MATCH({col}${R_YEAR},WEOYear,0))',
                fill_=bf, fmt=fm)
        a = (f'{col}{R_GDPLCU}', f'{col}{R_GDPUSD}')
        fx = '=' + (call('RATIO', *a) if is_last else f'{a[0]}/{a[1]}')
        put(ws, f'{col}{R_XR}', fx, fill_=F_LAMBDA if is_last else bf, fmt='0.00')
        if is_last:
            lam_row(c, R_XR, 'xr', 'all', 'all', fx)
    each_col(top)

    sub_font = Font(name='Arial', size=10, bold=True, italic=True)

    # 1. Policies
    band(ws, B_POL, '1. Policies', last)
    keys = [k[0] for k in POL]
    with_dg = ({k for k, *_r, mt in POL if mt} | set(POL_PARAMS) | {k for k in keys if k.startswith('ctr.')}
               | {k for k in keys if (k.rsplit('.', 2)[0] in PIG_VARS or k in PIGM_KEYS) and pig_dg(k, 0)})
    for key, var, fuel, sector, kind, mt in POL:
        r = R_POL[key]
        if SUBHEADS.get(key):                # sub-heading = label row of the group: D:G of its first row with D:G
            grp = keys[keys.index(key):]
            grp = grp[:next((i for i, k in enumerate(grp[1:], 1) if SUBHEADS.get(k)), len(grp))]
            src = next((k for k in grp if k in with_dg), None)
            subhead(ws, r - 2, SUBHEADS[key])          # v0.3.9: sub-heading on its own row (column B)
            outline[r - 2] = (1, True)
            label_row(r - 1, R_POL[src] if src else r)
            if src is None:
                for pc in PARAM_COLS:
                    ws[f'{pc}{r - 1}'].value = None
            outline[r - 1] = (1, True)
        elif key in POL_LABEL_BREAKS:         # v1.0.1: label row of a new variable inside the block
            label_row(r - 1, r)
            outline[r - 1] = (1, True)
        summary = key == 'cptraj'
        fnt = FONT_SUM if summary or kind == 'calc' else FONT
        ids(r, var, fuel, sector, fnt)
        if mt:                                # v0.2.4: MTInputs row looked up on Mapping (by name or label)
            put(ws, f'D{r}', f'=INDEX(MTRowNum,MATCH($A{r}&"|"&$B{r}&"|"&$C{r},MTRowKey,0))', FONT, None, '0')
        for pc_, k_ in zip(PARAM_COLS, POL_PARAMS.get(key, ())):     # v0.4.2: Mapping table of coverage sectors
            put(ws, f'{pc_}{r}', COV_LOOKUP[k_].format(r=r), FONT, None, '0.0000000' if pc_ == 'E' else '0')
        if kind == 'plain' and (key.rsplit('.', 2)[0] in PIG_VARS or key in PIGM_KEYS):   # v0.9.0 (R3): parameters
            for pc_, v_ in zip(PARAM_COLS, pig_dg(key, r) or ()):
                if v_ is not None:
                    put(ws, f'{pc_}{r}', v_, FONT, None, '@' if str(v_).startswith('|') else '0.0000')
        if key.startswith('ctr.'):            # v0.1.09: existing ETS sector coverage (complementary carbon tax)
            put(ws, f'D{r}', f'=MATCH("ees.{ECP_SECTOR[sector]}",ECPKey,0)', FONT, None, '0')   # v0.4.12: row
        codes(r, fnt)
        outline[r] = (0, False) if summary else (1, True)

        def pcell(c, is_base, is_last, r=r, key=key, kind=kind, fnt=fnt, var=var, fuel=fuel, sector=sector):
            col = L(c)
            bf = F_BASE if is_base else None
            if kind == 'mt' and var == 'ctcov':        # v0.5.6: a fuel or sector not covered is phased in (exph)
                val = f'=IF({mt_lookup(r, col)[1:]},1,{col}${R_POL["exph"]})'
            elif kind == 'mt':
                val = mt_lookup(r, col)
            elif kind == 'calc':                # v0.2.3: the last year (2041) calls the named LAMBDA
                val = pol_calc(key, col, is_last)
                lam_row(c, r, var, fuel, sector, pol_calc(key, col, True))
            elif kind == 'ecp':
                val = pol_calc(key, col, False)
            elif kind == 'plain':               # v0.9.0: plain formula in every column (SCC selection, Pigouvian rows)
                val = pol_calc(key, col, False, is_base)
            elif kind == 'data' and var in ('bco2', 'ch4bs'):   # v0.2.4: sheet BaselineCO2 (values of scenario 1)
                val = f'=INDEX(BaseCO2Val,MATCH(CtryCode&"|"&$C{r},BaseCO2Key,0),MATCH({col}${R_YEAR},BaseCO2Year,0))'
            elif kind == 'data':                       # ets.ovr: pasted override prices (input row)
                val = DATA_VALUES.get((key, year_of(c)))
            else:                                      # v0.2.4: sheet Constants by key variable|fuel|sector
                val = f'=INDEX(ConstVal,MATCH($A{r}&"|"&$B{r}&"|"&$C{r},ConstKey,0))'
            fmt = '0' if var in ('CPIntro', 'CPOutro', 'fpr.yr0', 'fpr.yr1', 'fb.yr0', 'fb.yr1') else '0.00'
            if var in ('ctcov', 'fbcov') and kind == 'const':
                fmt = 'General'
            lam = is_last and kind == 'calc'
            if var in ECP_PARAMS[:4] and var.endswith('Growth'):
                fmt = '0.0%'
            elif var in ECP_PARAMS:
                fmt = 'General'
            if var in ('bco2', 'ets.bce', 'ets.cap', 'ch4bs'):
                fmt = '#,##0.000'
            elif key in PIGM_KEYS or var in ('pig.ap', 'pig.tr'):   # v0.9.0 (PIGAP): small unit costs and shares
                fmt = '0.0000'
            elif var == 'ets.se':
                fmt = '0.0000000'
            put(ws, f'{col}{r}', val, FONT_LAMBDA if lam else fnt,
                F_LAMBDA if lam else (F_INPUT if key == 'ets.ovr' else bf), fmt)
        each_col(pcell)

    # 2. Retail energy prices (before new policies)
    band(ws, B_PRI, '2. Retail energy prices', last)
    subhead(ws, R_PRI['head.int.h'], 'International energy prices (MTInputs rows 220, 258; real via the deflator '
                                     'index; only ratios are used)')   # v0.3.9
    outline[R_PRI['head.int.h']] = (1, True)
    subhead(ws, R_PRI['head.dom'], 'Domestic price build-up by fuel and sector (D pass-through, E VAT rate, F GJ '
                                     'per price unit, G international price position)')   # v0.3.9
    label_row(R_PRI['head.int'], R_PRI[PRI_PARAMS[0]])
    outline[R_PRI['head.int']] = (1, True)
    outline[R_PRI['head.dom']] = (0, False)
    for k, p in enumerate(PRI_PARAMS):
        r = R_PRI[p]
        ids(r, p, '', '')
        put(ws, f'D{r}', f'=INDEX(MTRowNum,MATCH($A{r}&"|"&$B{r}&"|"&$C{r},MTRowKey,0))', FONT, None, '0')
        codes(r)
        outline[r] = (1, True)

        def scell(c, is_base, is_last, r=r):
            put(ws, f'{L(c)}{r}', mt_lookup(r, L(c)), fill_=F_BASE if is_base else None)
        each_col(scell)
    for key_ in ('gp.src', 'gp.adj'):
        r = R_PRI[key_]
        ids(r, key_, '', '')
        codes(r)
        outline[r] = (1, True)

        def gscell(c, is_base, is_last, r=r, key_=key_):
            put(ws, f'{L(c)}{r}', gp_formula(r, L(c), key_), fill_=F_BASE if is_base else None,
                fmt='@' if key_ == 'gp.src' else '0')
        each_col(gscell)
    for r0, var_ in ((R_GPN0, 'gpn'), (R_GP0, 'gp')):
        label_row(r0 - 1, r0)
        outline[r0 - 1] = (1, True)
        for k, (fu, lab, key, hi, lo) in enumerate(GP_ROWS):
            r = r0 + k
            ids(r, var_, fu, 'int')
            codes(r)
            outline[r] = (1, True)
            hl = [f'=INDEX(ConstVal,MATCH("gp.{x}|"&$B{r},ConstKey,0))' for x in ('hi', 'lo')]   # v0.2.4: Constants
            pv = [key] + hl + [None] if var_ == 'gp' else [key, None, None, None]
            for pc, v in zip(PARAM_COLS, pv):
                put(ws, f'{pc}{r}', v, FONT, F_UNUSED if v is None else (F_INPUT if pc == 'D' and key else None))

            def gcell(c, is_base, is_last, r=r, var_=var_):
                put(ws, f'{L(c)}{r}', gp_formula(r, L(c), var_), fill_=F_BASE if is_base else None, fmt='0.00')
            each_col(gcell)
    fuel_lab = {f: n for f, n, *_x in FUELS}
    sec_lab = {'pow': 'Power', 'res': 'Residential', 'ind': 'Industry', 'all': 'All sectors'}
    for f in PFUELS:                          # v0.2.6: fuel heading, then one block per sector
        subhead(ws, PV_HEAD[f], f'{fuel_lab[f]}: price build-up by sector')   # v0.3.9
    for pc, lab in PRICES:
        fuel, sec = pc.split('.')
        h0, rp = PV_BLOCK[pc], prow('pset', pc)
        label_row(h0, rp, f'{fuel_lab[fuel]} | {sec_lab[sec]}: parameters (D:G), international reference price, '
                          f'fixed part of the supply cost, price build-up')
        border_top(ws, h0, 1, last)            # v0.3.9: legacy top border on the first row of each build-up block
        ids(rp, 'pset', fuel, sec, FONT_IN)   # parameter row of the block: the little table of settings
        codes(rp)
        for pcol in PARAM_COLS:
            put(ws, f'{pcol}{rp}', ip_lookup(PV_COLS[pcol], f'$B{rp}&"."&$C{rp}'), FONT_IN,
                fmt='0' if pcol == 'G' else ('0.0%' if pcol == 'E' else '0.000'))
        rn = prow('pnew', pc)                  # v0.4.1: label row of the new taxes and subsidies (D: price position)
        label_row(rn, prow('pnq', pc), f'{fuel_lab[fuel]} | {sec_lab[sec]}: new taxes and subsidies, averaged over '
                                       f'the subsectors priced by this block (weights: their fuel use)')
        put(ws, f'D{prow("pnq", pc)}', ip_lookup('pos', f'$B{rn + 1}&"."&$C{rn + 1}'), fmt='0')
        for var in PVARS:
            r = prow(var, pc)
            fnt = FONT_IN if var in PV_ITALIC else (FONT_SUM if var == 'rpn' else FONT)   # v0.6.3: memo rows italic
            if var == 'rpn':
                BOLD_ROWS.add(r)
                PRICE_TOTAL_ROWS.add(r)
            ids(r, var, fuel, sec, fnt)
            codes(r)

            def pcell2(c, is_base, is_last, r=r, var=var, fuel=fuel, sec=sec, fnt=fnt):
                hist = year_of(c) <= LAST_HIST
                fmt = '0.00' if var == 'gpi' else ('#,##0.0' if var == 'pnq' else '0.000')
                if var in ('spf', 'gpi'):        # data-like rows: no LAMBDA
                    put(ws, f'{L(c)}{r}', price_formula(var, r, L(c), L(c - 1), 'base' if is_base else 'plain'),
                        fnt, F_BASE if is_base else None, fmt)
                    return
                lam = is_last
                block = 'lam' if lam else ('hist' if hist else 'proj')
                lam_row(c, r, var, fuel, sec, price_formula(var, r, L(c), L(c - 1), 'lam'))
                fl = F_LAMBDA if lam else (F_BASE if is_base else (F_LIGHT if hist and var in ('sp', 'txo', 'txf', 'txfx')
                                                                    else None))
                put(ws, f'{L(c)}{r}', price_formula(var, r, L(c), L(c - 1), block),
                    FONT_LAMBDA if lam else fnt, fl, fmt)
            each_col(pcell2)

    # v0.3.10: memo at the end of section 2: average prices and price indices (I31; NORMS 3c)
    put(ws, f'H{R_REFCOL}', 'Position of scenario 1\'s column of the same year (helper: price indices, section 2)',
        FONT)
    put(ws, f'H{R_SHOCK}', 'Fuel-use shock factor: 1 + shock (section 3, legacy row 2439) x Settings C19; multiplies '
                           'every fuel row of sections 5-8, as legacy (v0.3.11)', FONT)
    put(ws, f'H{R_GDPI}', 'GDP growth with the income factor for fuel use: (1 + GDP growth)^income factor - 1 (section '
                          '3; legacy row 2433: fuel rows raise GDP growth to eps_Y x income factor; v0.4.12, I23)', FONT)
    put(ws, f'H{R_GDPUSD}', 'Real GDP, baseline (USD bn, sheet WEO; legacy row 465): the basis of every % of GDP row '
                            '(12d, 16); moved up from section 16 (v0.3.13)', FONT)
    put(ws, f'H{R_GDPLCU}', 'Real GDP, baseline (local currency bn, sheet WEO; legacy row 464; v0.3.13)', FONT)
    put(ws, f'H{R_XR}', 'Exchange rate implied by real GDP: local currency per USD, constant in real terms (v0.3.13)', FONT)
    subhead(ws, R_PIX_HEAD, 'Average prices and price indices (memo): after-tax prices incl. new policies')
    outline[R_PIX_HEAD] = (1, True)
    d_ = VOFF['ener'] - VOFF['atp']               # rows from a subsector's atp row to its ener row
    s0, s1 = S_FIRST, S_LAST
    cons0, cons1 = R_PW[('cons', PW_GROUPS[0][0])], R_PW[('cons', PW_GROUPS[-1][0])]
    rp0, rp1 = R_PW[('rp', PW_GROUPS[0][0])], R_PW[('rp', PW_GROUPS[-1][0])]
    base_c = L(COL_G0 + 1)                        # base-year column of scenario 1 (base-year data equal in all)
    m0, m1 = R_PIX_LAB[PIX_FUELS[0]], R_PIX[('pav.time', 'ecy')]   # memo rows above the all-energy block
    for lab_k in PIX_FUELS + [f'l.{x}' for x in PAVL_FUELS]:   # v0.4.15 (I31): + the legacy weights of coal and gas
        f_ = lab_k[2:] if lab_k.startswith('l.') else lab_k
        vars_ = PAVL_VARS if lab_k.startswith('l.') else PIX_VARS
        label_row(R_PIX_LAB[lab_k], R_PIX[(vars_[0], f_)])
        outline[R_PIX_LAB[lab_k]] = (1, True)
        for v_ in vars_:
            r = R_PIX[(v_, f_)]
            ids(r, v_, f_, 'all')
            codes(r)
            outline[r] = (1, True)

            def pxcell(c, is_base, is_last, r=r, v_=v_, f_=f_):
                col = L(c)
                g0 = L(COL_G0)
                rc = f'{col}${R_REFCOL}'
                own = lambda v: f'{col}{R_PIX[(v, f_)]}'
                ref = lambda v: f'INDEX(${g0}{R_PIX[(v, f_)]}:{col}{R_PIX[(v, f_)]},{rc})'
                atp_r = f'{col}${s0}:{col}${s1}'
                q_own = f'{col}${s0 + d_}:{col}${s1 + d_}'
                q_ref = f'INDEX(${g0}${s0 + d_}:{col}${s1 + d_},0,{rc})'
                q_b = f'${base_c}${s0 + d_}:${base_c}${s1 + d_}'
                lam = is_last
                fmt = '#,##0.0'
                lv = lambda v: f'{col}{R_PIX[(v, f_)]}'
                if v_ in ('pavl.qr', 'pavl.qi'):         # v0.4.15 (I31): scenario-1 fuel use, residential / 8 industry
                    a_, b_ = ((SUB_HEAD['res'], SUB_HEAD['res'] + SB - 1) if v_ == 'pavl.qr'
                              else (SUB_HEAD['mch'], SUB_HEAD['ftr'] + SB - 1))
                    a = (f'INDEX(${g0}${a_}:{col}${b_},0,{rc})', f'$A${a_}:$A${b_}', f'$B${a_}:$B${b_}', f'$B{r}')
                    f = '=' + (call('SUBQTY', *a) if lam else f'SUMIFS({a[0]},{a[1]},"ener",{a[2]},{a[3]})')
                elif v_ == 'pavl.qp':                    # scenario-1 fuel use of the power type burning the fuel
                    r0_, r1_ = R_PW[('pe', PW_TECH[0][0])], R_PW[('pe', PW_TECH[-1][0])]
                    a = (f'INDEX(${g0}${r0_}:{col}${r1_},0,{rc})', f'$B${r0_}:$B${r1_}', f'$B{r}')
                    f = '=' + (call('SUMOF', *a) if lam else f'SUMIFS({a[0]},{a[1]},{a[2]})')
                elif v_ == 'pavl.pp':                    # power fuel price incl. new policies ($/GJ)
                    a = (f'{col}{prow("rpb", f_ + ".pow")}', f'{col}{R_PW[("gen", f_)]}', f'{col}{R_PW[("ccp", f_)]}',
                         f'{col}{R_PW[("pe", f_)]}', 'Settings!$C$13', 'MWyMkWh')
                    f = '=' + (call('PWFUELPRICE', *a) if lam else
                               f'{a[0]}+IF({a[3]}=0,0,{a[1]}*{a[5]}*{a[2]}/({a[3]}*{a[4]}))')
                    fmt = '0.00'
                elif v_ == 'pav.leg' and f_ in PAVL_FUELS:
                    q = lambda k: f'{col}{R_PIX[("pavl." + k, f_)]}'
                    a = (f'{col}{prow("rpn", f_ + ".res")}', q('qr'), f'{col}{prow("rpn", f_ + ".ind")}', q('qi'),
                         q('pp'), q('qp'), lv('pav.uv'))
                    rq = [R_PIX[(f'pavl.{k}', f_)] for k in ('qr', 'qi', 'qp')]   # v0.9.0 (PIGAP): SUM of the
                    qs = (f'SUM({q("qr")}:{q("qp")})' if rq == list(range(rq[0], rq[0] + 3))   # consecutive quantity
                          else f'({a[1]}+{a[3]}+{a[5]})')                    # rows (4-digit rows: 100 characters)
                    f = '=' + (call('LEGAVG', *a) if lam else
                               f'IF({qs}=0,{a[6]},({a[0]}*{a[1]}+{a[2]}*{a[3]}+{a[4]}*{a[5]})/{qs})')
                    fmt = '0.00'
                elif v_ == 'pav.leg' and f_ in PAVL_OIL:  # legacy: the single retail price of the fuel
                    a = (f'{col}{prow("rpn", f_ + ".all")}',)
                    f = '=' + (call('TOTAL', *a) if lam else a[0])
                    fmt = '0.00'
                elif v_ == 'pav.leg':                    # electricity (own quantities, as legacy) and the others
                    a = (lv('pav.sp'), lv('pav.q'))
                    f = '=' + (call('SHAREOF', *a) if lam else f'IF({a[1]}=0,0,{a[0]}/{a[1]})')
                    fmt = '0.0000'
                elif v_ == 'pav.lidx' and f_ in PAVL_FUELS + PAVL_OIL + ['ecy']:
                    a = (lv('pav.leg'), ref('pav.leg'))
                    f = '=' + (call('SHAREOF', *a) if lam else f'IF({a[1]}=0,0,{a[0]}/{a[1]})')
                    fmt = '0.0000'
                elif v_ == 'pav.lidx':                   # no legacy average: the Laspeyres index
                    a = (lv('pav.las'),)
                    f = '=' + (call('TOTAL', *a) if lam else a[0])
                    fmt = '0.0000'
                elif v_ == 'pav.idx':                    # the index reported (Settings C54: Legacy* or Laspeyres)
                    a = ('PavMethod', lv('pav.lidx'), lv('pav.las'))
                    f = '=' + (call('PICKINDEX', *a) if lam else f'IF(LEFT({a[0]},3)="Leg",{a[1]},{a[2]})')
                    fmt = '0.0000'
                elif v_ in ('pav.sp', 'pav.spr', 'pav.sp0'):
                    qq = {'pav.sp': q_own, 'pav.spr': q_ref, 'pav.sp0': q_b}[v_]
                    if f_ == 'ecy':
                        qq = {'pav.sp': f'{col}${cons0}:{col}${cons1}',
                              'pav.spr': f'INDEX(${g0}${cons0}:{col}${cons1},0,{rc})',
                              'pav.sp0': f'${base_c}${cons0}:${base_c}${cons1}'}[v_]
                        a = (f'{col}${rp0}:{col}${rp1}', qq)
                        f = '=' + (call('SPENDSUM', *a) if lam else f'SUMPRODUCT({a[0]},{a[1]})')
                    elif f_ == 'all':
                        a = (f'SUMIFS({col}${m0}:{col}${m1},$A${m0}:$A${m1},$A{r},$B${m0}:$B${m1},"<>ecy")',
                             'Settings!$C$13', f'{col}{R_PIX[(v_, "ecy")]}')
                        f = '=' + (call('ALLSPEND', *a) if lam else f'{a[0]}*{a[1]}+{a[2]}')
                    else:
                        a = (f'$B{r}', atp_r, qq)
                        f = '=' + (call('FUELSPEND', *a) if lam else
                                   f'SUMPRODUCT(--(SecVar="atp"),--(SecFuel={a[0]}),{a[1]},{a[2]})')
                elif v_ == 'pav.q':
                    if f_ == 'ecy':
                        a = (f'{col}${cons0}:{col}${cons1}',)
                        f = '=' + (call('TOTAL', *a) if lam else f'SUM({a[0]})')
                    elif f_ == 'all':
                        a = (f'SUMIFS({col}${m0}:{col}${m1},$A${m0}:$A${m1},$A{r},$B${m0}:$B${m1},"<>ecy")',
                             f'{col}{R_PIX[("pav.q", "ecy")]}*GJperkWh/PJperKtoe')
                        f = '=' + (call('ADDED', *a) if lam else f'{a[0]}+{a[1]}')
                    else:
                        a = (f'$B{r}', f'{col}${s0}:{col}${s1}')
                        f = '=' + (call('FUELQTY', *a) if lam else f'SUMIFS({a[1]},SecVar,"ener",SecFuel,{a[0]})')
                elif v_ == 'pav.uv':
                    a = (own('pav.sp'), own('pav.q'))
                    f = '=' + (call('SHAREOF', *a) if lam else f'IF({a[1]}=0,0,{a[0]}/{a[1]})')
                    fmt = '0.0000'
                elif v_ == 'pav.las':
                    a = (own('pav.spr'), ref('pav.sp'))
                    f = '=' + (call('SHAREOF', *a) if lam else f'IF({a[1]}=0,0,{a[0]}/{a[1]})')
                    fmt = '0.0000'
                elif v_ == 'pav.time':
                    a = (own('pav.sp0'), f'${base_c}{R_PIX[("pav.sp", f_)]}')
                    f = '=' + (call('SHAREOF', *a) if lam else f'IF({a[1]}=0,0,{a[0]}/{a[1]})')
                    fmt = '0.0000'
                else:                                   # pav.mix
                    a = (own('pav.uv'), ref('pav.uv'), own('pav.las'))
                    f = '=' + (call('MIXEFFECT', *a) if lam else
                               f'IF({a[1]}*{a[2]}=0,0,{a[0]}/{a[1]}/{a[2]})')
                    fmt = '0.0000'
                if lam:
                    lam_row(c, r, v_, f_, 'all', f)
                put(ws, f'{col}{r}', f, FONT_LAMBDA if lam else FONT,
                    F_LAMBDA if lam else (F_BASE if is_base else None), fmt)
            each_col(pxcell)
    ids(R_PRI_SUM, 'rpe', 'all', 'all', FONT_SUM)      # v0.4.1: summary row of section 2
    codes(R_PRI_SUM, FONT_SUM)

    def rpecell(c, is_base, is_last):
        col = L(c)
        put(ws, f'{col}{R_PRI_SUM}', f'={col}{R_PIX[("pav.uv", "all")]}', FONT_SUM, F_BASE if is_base else None,
            '0.00')
    each_col(rpecell)

    # 3. Power sector: engineer model with generation costs and electricity prices (v0.1.05-v0.1.06)
    band(ws, B_POW, '3. Power sector', last)
    for let, head, _items in PW_LAYOUT:
        subhead(ws, PW_HEAD[let], head)   # v0.3.9 (head is the loop text here)
        outline[PW_HEAD[let]] = (1, True)
    for var, r_lab in PW_LAB.items():          # v0.2.4: label row above each block (and single row with D:G)
        label_row(r_lab, r_lab + 1)
        outline[r_lab] = (0, False) if var in PW_SUMMARY else (1, True)
    for r, var, fu, sec, kind in PW_ROWS:
        summary = var in PW_SUMMARY
        fnt = FONT_SUM if summary else FONT
        ids(r, var, fu, sec, fnt)
        codes(r, fnt)
        outline[r] = (0, False) if summary else (1, True)
        specs = PW_PARAMS[var]
        for j, pcol in enumerate(PARAM_COLS):
            if j < len(specs):
                put(ws, f'{pcol}{r}', pw_param_formula(specs[j], var, r), FONT,
                    None, 'General' if specs[j][0] == 'key' else '0.000000')
            else:
                put(ws, f'{pcol}{r}', None, fill_=F_UNUSED)
        fmt = PW_FMT.get(var, '0.0000')

        def pwcell(c, is_base, is_last, r=r, var=var, fnt=fnt, fmt=fmt, fu=fu, sec=sec):
            plain_all = var in PW_DATA or var in PW_SUMS or var in PW_NOLAM
            lam = is_last and not plain_all
            if not plain_all:
                lam_row(c, r, var, fu, sec, pw_formula(var, r, L(c), L(c - 1), 'lam'))
            if var in PW_DATA:
                block = 'all'
            elif lam:
                block = 'lam'
            elif var == 'rppre':
                block = 'hist' if year_of(c) <= LAST_HIST else 'proj'
            else:
                block = 'base' if is_base and var in PW_BASE else 'plain'
            fl = F_LAMBDA if lam else (F_BASE if is_base else (F_LIGHT if block == 'hist' else None))
            put(ws, f'{L(c)}{r}', pw_formula(var, r, L(c), L(c - 1), block), FONT_LAMBDA if lam else fnt, fl, fmt)
        each_col(pwcell)
    for r in range(B_POW + 1, R_POW_NOTE + 2):
        outline.setdefault(r, (1, True))                    # blank rows between blocks and the notes roll up too
    notes = [
        'Year by year as legacy: demand (H) uses last year\'s electricity price (G); dispatch (I) fills demand from this '
        'year\'s capacity (K); the generation shares set the VRE share and storage cost (J), the average generation '
        'cost (E) and next year\'s supply cost and price (G); investment (L) adds the capacity needed for this year\'s '
        'demand to next year\'s capacity, using levelised costs (C + D9 = E1). dsum and lvc look one column ahead '
        '(levelised variable cost to the end of the horizon 2041), so they and tvcx (tvc, or last year\'s where 2041 cannot be evaluated) have plain formulas in every column.',
        'Bug fixes against legacy (CPAT-AI-Mitigation-Prototype_BugsIssuesUpgrades_v0.6.4.docx): services demand, efficiency exponent, '
        'income factor, long-term storage allocation, investment spending, investment logit, early-retirement units, '
        'coal effective retirement, feebate rebate, capacity check. Power enters the main thread (v0.1.09): CO2 in '
        'section 13 (total, by fuel, ETS sector power), generation fuel use in section 11 (row ener.pow, totals by '
        'fuel), revenues (sub-table M and G: rvat, rnvat, rgap) in section 12 (rows .pow).']
    for k, n in enumerate(notes):
        put(ws, f'H{R_POW_NOTE + k}', n, FONT_NOTE)   # v0.4.1: notes upright grey
    ids(R_PW_TOT, 'pet', 'all', 'pow', FONT_SUM)       # v0.2.6: summary line of section 3
    codes(R_PW_TOT, FONT_SUM)

    def pettot(c, is_base, is_last):
        col = L(c)
        put(ws, f'{col}{R_PW_TOT}', f'=SUMPRODUCT({pw_block("pe", col)},{pw_pcol("pe", "E")})', FONT_SUM,
            F_BASE if is_base else None, '#,##0.0')
    each_col(pettot)

    # 5-8. Sector sections
    for num_, grp, title_ in SECTIONS:
        b = SEC_BAND[grp]
        band(ws, b, f'{num_}. {title_}', last)
        subs = [s[0] for s in SUBSECTORS if s[2] == grp]
        r_sum = SEC_SUM[grp]
        ids(r_sum, 'ener', 'all', grp, FONT_SUM)
        codes(r_sum, FONT_SUM)
        heads = [SUB_HEAD[s] for s in subs]
        a, z = heads[0], heads[-1] + SB - 1

        def secsum(c, is_base, is_last, r=r_sum, a=a, z=z):
            col = L(c)
            ren = ''.join(f'+{col}{R_TR[k_]}' for k_ in REN_ROWS if grp == 'tra')   # v0.9.0 (R10.7)
            put(ws, f'{col}{r}', f'=SUMIFS({col}{a}:{col}{z},$A{a}:$A{z},"ener",$B{a}:$B{z},"<>all"){ren}', FONT_SUM,
                F_BASE if is_base else None, '#,##0.0')
        each_col(secsum)
        outline[r_sum] = (0, False)
        d0, d1 = R_PW[('dem', DEM_SUBS[0])], R_PW[('dem', DEM_SUBS[-1])]
        memo_font = Font(name='Arial', size=10, italic=True)
        for s in subs:
            h = SUB_HEAD[s]
            ids(h, 'ener', 'all', s, FONT_SUM)
            codes(h, FONT_SUM)
            outline[h] = (0, False)                       # v0.2.4: one outline level: subsector heading visible
            ids(h + 1, 'eldem', 'ecy', s, memo_font)          # v0.1.07: electricity demand of the subsector (memo)
            codes(h + 1, memo_font)
            outline[h + 1] = (0, False)

            def eldcell(c, is_base, is_last, r=h + 1):
                col = L(c)
                put(ws, f'{col}{r}', f'=SUMIF($C${d0}:$C${d1},$C{r},{col}${d0}:{col}${d1})', memo_font,
                    F_BASE if is_base else None, '#,##0.0')
            each_col(eldcell)
            e0 = h + VOFF['ener']

            def subsum(c, is_base, is_last, h=h, e0=e0, s=s):
                col = L(c)
                ren = f'+{col}{R_TR[f"ener.{s}.ren"]}' if f'ener.{s}.ren' in R_TR else ''   # v0.9.0 (R10.7)
                put(ws, f'{col}{h}', f'=SUM({col}{e0}:{col}{e0 + NF - 1}){ren}', FONT_SUM, F_BASE if is_base else None,
                    '#,##0.0')
            each_col(subsum)
            for k, var in enumerate(VARS):
                params = VAR_PARAMS[var]
                label_row(h + VOFF[var] - 1, h + VOFF[var])     # v0.2.4: label row above each variable
                outline[h + VOFF[var] - 1] = (1, True)
                for i, (f, *_r) in enumerate(FUELS):
                    r = h + VOFF[var] + i
                    ids(r, var, f, s)
                    codes(r)
                    outline[r] = (1, True)
                    for j, pc in enumerate(PARAM_COLS):
                        if j < len(params):
                            put(ws, f'{pc}{r}', '=' + inputs_lookup(params[j], r), fmt='0.000')
                        else:
                            put(ws, f'{pc}{r}', None, fill_=F_UNUSED)
                    fmt = '#,##0.0' if var in ['ener', 'enel', 'rex', 'rvt'] + REV_VARS else ('0.0000' if var == 'co2'
                                                                                          else '0.000')

                    def cell(c, is_base, is_last, r=r, var=var, fmt=fmt, f=f, s=s):
                        lam = is_last
                        lam_row(c, r, var, f, s, calc_formula(var, r, L(c), L(c - 1), is_base, True))
                        put(ws, f'{L(c)}{r}', calc_formula(var, r, L(c), L(c - 1), is_base, lam),
                            FONT_LAMBDA if lam else FONT, F_LAMBDA if lam else (F_BASE if is_base else None), fmt)
                    each_col(cell)

    # 5b. Road transport: engineer model (v0.3.5; Methods, chapter Transport)
    band(ws, B_TR, '5b. Road transport: engineer model and outputs to the transport co-benefits module', last)   # v0.9.0 (user 2026-10-29: no copies)
    for r, what, it in TR_LAYOUT:
        if what == 'head':
            subhead(ws, r, it['text'])   # v0.3.9
            continue
        if what == 'label':
            label_row(r, R_TR[it['key']])
            continue
        var, kind = it['var'], it['kind']
        ids(r, var, it['b'], it['c'])
        codes(r)
        if kind == 'mt':
            put(ws, f'D{r}', f'=INDEX(MTRowNum,MATCH($A{r}&"|"&$B{r}&"|"&$C{r},MTRowKey,0))', FONT, None, '0')
        for pc, v in zip(PARAM_COLS, it['par']):
            v = v(r) if callable(v) else v
            if v is not None:
                put(ws, f'{pc}{r}', v, FONT)
        if kind == 'par':
            continue

        def trcell(c, is_base, is_last, r=r, it=it, kind=kind, var=var):
            x = _TX(r, c)
            lam = False
            if kind == 'mt':
                f = mt_lookup(r, x.col)
            elif kind == 'plain':
                f = it['base'](x) if is_base and it['base'] else it['plain'](x)
            elif is_base and it['base'] is not None:
                f = it['base'](x)
            else:
                name, args = it['lam'][0], it['lam'][1](x)
                f = '=' + lambda_plain(name, args)
                if is_last:
                    f, lam = '=' + call(name, *args), True
                if not is_base:
                    lam_row(c, r, var, it['b'], it['c'], '=' + call(name, *args))
            put(ws, f'{x.col}{r}', f, FONT_LAMBDA if lam else FONT, F_LAMBDA if lam else (F_BASE if is_base else None),
                it['fmt'])
        each_col(trcell)
    ids(R_TRSUM, 'trsum', 'all', 'rod', FONT_SUM)
    codes(R_TRSUM, FONT_SUM)

    def trsum(c, is_base, is_last):
        col = L(c)
        put(ws, f'{col}{R_TRSUM}', f'=SUM({col}{R_TR[TR_RES[0]]}:{col}{R_TR[TR_RES[-1]]})+{col}{R_TR[5331]}', FONT_SUM,
            F_BASE if is_base else None, '#,##0.0')
    each_col(trsum)

    # 6b. Residential leakage to biomass (v0.5.1, D9; legacy rows 5571-5593, bugs L45, L90, L91 fixed)
    band(ws, B_LK, '6b. Residential leakage to biomass', last)
    for r, what, it in LK_LAYOUT:
        if what == 'head':
            subhead(ws, r, it['text'])
            continue
        if what == 'label':
            label_row(r, R_LK[it['key']])
            continue
        var, kind = it['var'], it['kind']
        ids(r, var, it['b'], it['c'])
        codes(r)
        for pc, v in zip(PARAM_COLS, it['par']):
            put(ws, f'{pc}{r}', v(r), FONT, None, '0.000')

        def lkcell(c, is_base, is_last, r=r, it=it, kind=kind, var=var):
            x = _LX(r, c)
            x.m = it['b']
            lam = False
            if kind == 'plain':
                f = it['plain'](x)
            elif is_base and it['base'] is not None:
                f = it['base'](x)
            else:
                name, args = it['lam'][0], it['lam'][1](x)
                f = '=' + lambda_plain(name, args)
                if is_last:
                    lam_row(c, r, var, it['b'], it['c'], '=' + call(name, *args))
            put(ws, f'{x.col}{r}', f, FONT, F_BASE if is_base else None, it['fmt'])
        each_col(lkcell)
    ids(R_LKSUM, 'lks', 'all', 'res', FONT_SUM)
    codes(R_LKSUM, FONT_SUM)

    def lksum(c, is_base, is_last):
        col = L(c)
        put(ws, f'{col}{R_LKSUM}', f'=SUM({col}{R_LK["lkc." + LK_FUELS[0]]}:{col}{R_LK[LK_RES[1]]})', FONT_SUM,
            F_BASE if is_base else None, '#,##0.0')
    each_col(lksum)

    # 11. Results - energy consumption
    spans = {g: (SUB_HEAD[[x[0] for x in SUBSECTORS if x[2] == g][0]],
                 SUB_HEAD[[x[0] for x in SUBSECTORS if x[2] == g][-1]] + SB - 1) for _n, g, _t in SECTIONS}
    band(ws, B_RES, '11. Energy consumption', last)
    a, z = S_FIRST, S_LAST
    ids(R_TOTAL, 'ener', 'all', 'all', FONT_SUM)
    codes(R_TOTAL, FONT_SUM)

    def tot(c, is_base, is_last):            # v0.1.09: + power generation fuel use (row ener.pow)
        col = L(c)
        put(ws, f'{col}{R_TOTAL}', f'=SUMIFS({col}${a}:{col}${z},SecVar,"ener",SecFuel,"<>all")+{col}{R_EPOW}',
            FONT_SUM, F_BASE if is_base else None, '#,##0.0')
    each_col(tot)
    ids(R_EPOW, 'ener', 'all', 'pow')
    codes(R_EPOW)
    q0, q1 = R_PW[('pe', PW_TECH[0][0])], R_PW[('pe', PW_TECH[-1][0])]     # power fuel use by type (section 3 I)

    def epow(c, is_base, is_last):
        col = L(c)
        put(ws, f'{col}{R_EPOW}', f'={col}{R_PW_TOT}', fill_=F_BASE if is_base else None, fmt='#,##0.0')
    each_col(epow)
    for i, (s, *_r) in enumerate(SUBSECTORS):
        r = R_SUB0 + i
        ids(r, 'ener', 'all', s)
        codes(r)

        def bysub(c, is_base, is_last, r=r):
            col = L(c)
            put(ws, f'{col}{r}', f'=SUMIFS({col}${a}:{col}${z},SecVar,"ener",SecSub,$C{r},SecFuel,"<>all")',
                fill_=F_BASE if is_base else None, fmt='#,##0.0')
        each_col(bysub)
    for i, (f, *_r) in enumerate(FUELS):
        r = R_FUEL0 + i
        ids(r, 'ener', f, 'all')
        codes(r)

        def byfuel(c, is_base, is_last, r=r):
            col = L(c)
            pw = f'SUMIF($B${q0}:$B${q1},$B{r},{col}${q0}:{col}${q1})'     # v0.1.09: + power of this fuel
            put(ws, f'{col}{r}', f'=SUMIFS({col}${a}:{col}${z},SecVar,"ener",SecFuel,$B{r})+{pw}',
                fill_=F_BASE if is_base else None, fmt='#,##0.0')
        each_col(byfuel)
    far = L(last + 10 * GW)
    extra = [(R_CHK, 'ener.chk', '', '',
              lambda col: (f'=ABS(SUM({col}{R_SUB0}:{col}{R_EPOW})-{col}{R_TOTAL})'
                           f'+ABS(SUM({col}{R_FUEL0}:{col}{R_FUEL0 + NF - 1})'
                           + ''.join(f'+{col}{R_TR[k_]}' for k_ in REN_ROWS)      # v0.9.0 (R10.7): renewables
                           + f'-{col}{R_TOTAL})'), '0.000', F_CHECK),
             (R_REF, 'ener.ref', 'all', 'all',     # v0.6.2: ref_formula (the range ends at this column, NORMS)
              lambda col: ref_formula(col, R_TOTAL), '#,##0.0', None),
             (R_PCT, 'ener.pct', 'all', 'all', lambda col: f'={col}{R_TOTAL}/{col}{R_REF}-1', '0.00%', None)]
    for r, var, fu, sub, f, fmt, fl in extra:
        ids(r, var, fu, sub, FONT_B)
        codes(r)

        def ex(c, is_base, is_last, r=r, f=f, fmt=fmt, fl=fl):
            put(ws, f'{L(c)}{r}', f(L(c)), fill_=fl or (F_BASE if is_base else None), fmt=fmt)
        each_col(ex)

    # 11b (v0.3.14): change against scenario 1 by fuel and sector group
    lvl11 = {**{f: R_FUEL0 + i for i, (f, *_x) in enumerate(FUELS)}, **{g: SEC_SUM[g] for _n, g, _t in SECTIONS},
             'pow': R_EPOW, 'all': R_TOTAL}

    def c11b(col, r, key, var, fu, sec, is_base, lam):
        lv = lvl11[fu if fu != 'all' else sec]
        if var == 'echg':
            return chg_of(col, lv), '#,##0.0'
        ch = f'{col}{R_E11B["echg." + key.split(".", 1)[1]]}'
        return f'=IF({col}{lv}-{ch}=0,0,{ch}/({col}{lv}-{ch}))', '0.0%'
    sub_blocks(E11B_BLOCKS + [(None, E11B_SUM)], R_E11B, R_E11B_LAB, R_E11B_HEAD, c11b)
    for r in range(R_SUB0, R_PCT + 1):
        outline[r] = (1, False)
    put(ws, f'H{R_ELD["all"] - 1}', 'Memo: electricity demand by sector (power model, section 3 H; final use of '
                                    'electricity, not in the fuel totals above, which count the fuels used to '
                                    'generate it)', Font(name='Arial', size=10, bold=True))   # v0.4.1: not italic
    outline[R_ELD['all'] - 1] = (1, False)
    for g in ELD_GROUPS:
        r = R_ELD[g]
        ids(r, 'eldem', 'ecy', g, FONT_SUM if g == 'all' else FONT)
        codes(r)
        outline[r] = (1, False)

        def eld(c, is_base, is_last, r=r, g=g):
            col = L(c)
            if g == 'all':
                f = f'=SUM({col}{R_ELD[ELD_GROUPS[1]]}:{col}{R_ELD[ELD_GROUPS[-1]]})'
            else:
                a_, z_ = spans[g]
                f = f'=SUMIF($A${a_}:$A${z_},"eldem",{col}${a_}:{col}${z_})'
            put(ws, f'{col}{r}', f, FONT_SUM if g == 'all' else FONT, F_BASE if is_base else None, '#,##0.0')
        each_col(eld)

    # 12. Revenues: existing taxes, existing subsidies and new policies as separate calculations
    band(ws, B_REV, '12. Revenues', last)
    far = L(last + 10 * GW)
    for key, var, fu, sec in REV_ROWS:
        r = R_REV[key]
        summary = sec == 'all'
        fnt = FONT_SUM if summary else FONT
        ids(r, var, fu, sec, fnt)
        codes(r, fnt)
        outline[r] = (0, False) if summary else (1, True)

        def rcell(c, is_base, is_last, r=r, key=key, var=var, sec=sec, fnt=fnt):
            col = L(c)
            if var in REV_VARS and sec == 'pow':     # v0.1.09: power (section 3: M by type, G by user group)
                parts = {'rtx': ['prtx', 'prxc', 'rvat'], 'rsub': ['prsub', 'rgap', 'prrns'],   # v0.5.4: rns, rebate,
                         'rnew': ['prnew', 'rnvat', 'rreb', 'rpex'],                    # excise
                         'rxcp': ['prxl'], 'rsr': []}[var]      # v0.4.16: electricity phase-outs not modelled (power)
                f = '=' + ('+'.join(f'SUM({pw_block(p_, col)})' for p_ in parts) or '0')
            elif var in REV_VARS:
                a, z = (S_FIRST, S_LAST) if sec == 'all' else spans[sec]
                crit = 'SecVar' if sec == 'all' else f'$A${a}:$A${z}'
                f = f'=SUMIFS({col}${a}:{col}${z},{crit},"{var}")'
                if sec == 'all':
                    f += f'+{col}{R_REV[var + ".pow"]}'
            elif var == 'rev.chk':
                f = '=' + '+'.join(f'ABS({col}{R_REV[v + ".all"]}-SUM({col}{R_REV[v + ".tra"]}:{col}{R_REV[v + ".pow"]}))'
                                   for v in ('rtx', 'rsub', 'rnew'))   # v0.4.16: rsr in rfu.chk (100-char limit)
            elif var == 'rnet':
                f = f'={col}{R_REV["rtx.all"]}+{col}{R_REV["rsub.all"]}'     # v0.2.4: subsidies negative
            elif var == 'rtot':                      # v0.2.8: + methane fee revenue; v0.4.16: + subsidy reform, producer
                f = (f'={col}{R_REV["rnet.all"]}+{col}{R_REV["rnew.all"]}+{col}{R_REV["rsr.all"]}'
                     f'+{col}{R_REV["rpsu.all"]}+{col}{R_REV["rmf.all"]}')
            elif var == 'rpsu':                      # v0.4.16 (LD19): producer subsidies after the phase-out (negative)
                f = (f'=-SUMPRODUCT({pol_range(col, "pros." + PROS_FUELS[0][0], len(PROS_FUELS))},'
                     f'{pol_range(col, "psf." + PROS_FUELS[0][0], len(PROS_FUELS))})')
            elif var == 'rmf':
                f = f'={col}{R_GHG["ch4.rev"]}'
            elif var == 'rtot.ref':
                rr = R_REV['rtot.all']
                f = ref_formula(col, rr)
            else:
                f = f'={col}{R_REV["rtot.all"]}-{col}{R_REV["rtot.ref"]}'
            put(ws, f'{col}{r}', f, fnt, F_CHECK if var == 'rev.chk' else (F_BASE if is_base else None),
                '0.000' if var == 'rev.chk' else '#,##0.0')
        each_col(rcell)
    notes = [
        'Per subsector and fuel (rows rtx, rsub, rnew, rxcp in each subsector block): rtx = fuel use x PJ/ktoe x '
        '(existing tax etx + VAT vat of the price fuel + change in existing carbon pricing xcpd x (1 + VAT rate)); '
        'rsub = fuel use x PJ/ktoe x existing subsidy esub (negative: subsidies are negative); rnew = fuel use x PJ/ktoe x (new '
        'carbon tax + new excise + ETS x revenue factor + VAT on new policies nce x VAT rate); rxcp = existing carbon '
        'pricing revenue (memo, level; the part embedded in the price data is inside rtx). Feebates are '
        'revenue-neutral.',
        'Power (rows .pow, v0.1.09; section 3 M and G): rtx = taxes on generation fuels + change in existing carbon '
        'pricing + electricity VAT; rsub = subsidies on generation fuels + electricity subsidy gap (price before VAT '
        'minus supply cost; negative when the price is below cost, positive when above); rnew = carbon tax, ETS at the permit price and fuel '
        'price reform on generation + VAT on the policy cost passed through. Existing taxes and subsidies use the '
        'scenario\'s own quantities, so a policy also changes them (the fiscal effect vs scenario 1 is rtot.chg); '
        'rev.chk = 0 when the totals equal their rows. Sign convention: subsidies are negative, so rnet = rtx + '
        'rsub.',
        'Per-fuel policy input (later): esubpu (existing subsidy per MTInputs price unit, section 2) can feed a '
        'subsidy-reform path in the fuel price reform rows (MTInputs 142-169 use the same units).']
    for k, n in enumerate(notes):
        put(ws, f'H{R_REV_NOTE + k}', n, FONT_NOTE)   # v0.4.1: notes upright grey

    # 12d. Fiscal reports (v0.3.13): revenue by fuel, shares of GDP, base erosion
    for head, rows_ in FIS_BLOCKS:
        subhead(ws, R_FIS_HEAD[head], head)
        outline[R_FIS_HEAD[head]] = (1, True)
        label_row(R_FIS_LAB[head], R_FIS[rows_[0][0]])
    for key, var, fu, sec in FIS_ROWS:
        r = R_FIS[key]
        fnt = FONT
        ids(r, var, fu, sec, fnt)
        codes(r, fnt)
        outline[r] = (1, True)

        def fcell(c, is_base, is_last, r=r, key=key, var=var, fu=fu, sec=sec):
            col = L(c)
            lam = is_last and key in FIS_LAM
            fmt = '#,##0.0'
            if var == 'rfu' and fu == 'ecy':
                a_, z_ = R_PW[('rvat', PW_GROUPS[0][0])], R_PW[('rgap', PW_GROUPS[-1][0])]   # v0.5.4: one range
                assert {v_ for r_, v_, *_x in PW_ROWS if a_ <= r_ <= z_} == {'rvat', 'rnvat', 'rreb', 'rpex', 'rgap'}
                f = f'=SUM({col}${a_}:{col}${z_})+SUM({pw_block("prrns", col)})'
            elif var == 'rfu':
                f = (f'=SUMPRODUCT(SUMIFS({col}${S_FIRST}:{col}${S_LAST},SecVar,{{"rtx","rsub","rnew","rsr"}},'
                     f'SecFuel,$B{r}))')
            elif var == 'rfg':
                f = '=' + '+'.join(f'{col}{R_PW[(p_, fu)]}' for p_ in ('prtx', 'prxc', 'prsub', 'prnew'))
            elif var == 'rfu.chk':
                f = (f'=ABS(SUM({col}{R_FIS["rfu." + FUELS[0][0]]}:{col}{R_FIS["rfg." + RFG_TECH[-1]]})'
                     f'-{col}{R_REV["rnet.all"]}-{col}{R_REV["rnew.all"]}-{col}{R_REV["rsr.all"]})')
                fmt = '0.000'
            elif var == 'rpol':                              # v0.4.15 (LD37): 12e, total revenue by policy
                q = lambda k: f'{col}{R_FIS["rpol." + k]}'
                pr = lambda a, b: f'{col}${a}:{col}${b}'
                cov = lambda k: pr(R_POL[f'{k}.{COV_SECTORS[0]}'], R_POL[f'{k}.{COV_SECTORS[-1]}'])
                rf = f'{col}${R_POL["ets.rf"]}'
                sumifs = lambda v: f'SUMIFS({col}${S_FIRST}:{col}${S_LAST},SecVar,"{v}")'
                f = {'ct': f'=SUMPRODUCT({pr(R_CPR["covct." + COV_SECTORS[0]], R_CPR["covct." + COV_SECTORS[-1]])},'
                           f'{cov("ctr")})+SUM({pw_block("rreb", col)})+{col}${R_PW[("rexs", "")]}',   # v0.5.4
                     'ets': f'=SUMPRODUCT({pr(R_EMI["co2.sec." + COV_SECTORS[0]], R_EMI["co2.sec." + COV_SECTORS[-1]])},'
                            f'{cov("etr")})*{rf}',
                     'ctp': f'={col}{R_CPR["covct.pow"]}*{col}${R_POL["ctr.pow"]}',
                     'etp': f'={col}{R_EMI["co2.sec.pow"]}*{col}${R_POL["etr.pow"]}*{rf}',
                     'exc': (f'={sumifs("rex")}+SUM({pw_block("prnew", col)})-{q("ctp")}-{q("etp")}'
                             f'+{col}${R_PW[("rexm", "")]}'),   # v0.5.4: manual electricity excise
                     'vat': f'={sumifs("rvt")}+SUM({pw_block("rvat", col)})+SUM({pw_block("rnvat", col)})',
                     'psu': f'=SUM({pw_block("rgap", col)})+{col}{R_REV["rpsu.all"]}',   # v0.4.16: + producer
                     'exi': (f'={col}{R_REV["rtot.all"]}-{col}{R_REV["rmf.all"]}-{q("ct")}-{q("exc")}-{q("vat")}'
                             f'-{q("ets")}-{q("psu")}-{q("ren")}'),
                     'ren': f'=SUM({pw_block("prrns", col)})', 'trs': '=0',   # v0.5.4: renewable subsidies (L108)
                     'mf': f'={col}{R_REV["rmf.all"]}',
                     'tot': f'=SUM({q(RPOL_SUM[0])}:{q(RPOL_SUM[-1])})'}[fu]
            elif var == 'rpol.chk':
                f = f'=ABS({col}{R_FIS["rpol.tot"]}-{col}{R_REV["rtot.all"]})'
                fmt = '0.000'
            elif var == 'gdpn':                          # v0.5.6: nominal GDP, WEO NGDP / NGDPD (Inputs_macro)
                f = (f'=INDEX(WEOVal,MATCH(CtryCode&"|{"ngdp" if fu == "lcu" else "ngdpd"}",WEOKey,0),'
                     f'MATCH({col}${R_YEAR},WEOYear,0))')   # v0.9.2: WEO is in bn already (bug M19 fixed)
                fmt = '#,##0.0'
            elif var == 'rbe':
                rr = R_REV['rnet.all']
                f = f'={col}{rr}-INDEX(${L(COL_G0)}{rr}:{col}{rr},{col}${R_REFCOL})'
            else:                                            # share of baseline real GDP
                src = RPCT_SRC[fu][0]
                a = (f'{col}{R_FIS[src] if src in R_FIS else R_REV[src]}', f'{col}${R_GDPUSD}')
                f = '=' + (call('GDPSHARE', *a) if lam else f'{a[0]}/({a[1]}*MperBn)')
                fmt = '0.00%'
            put(ws, f'{col}{r}', f, fnt, F_LAMBDA if lam else (F_CHECK if var in ('rfu.chk', 'rpol.chk') else
                                                               (F_BASE if is_base else None)), fmt)
            if key in FIS_LAM and not is_base:
                lam_row(c, r, var, fu, sec, f if lam else None)
        each_col(fcell)

    # 13. Emissions: CO2 from fuel combustion
    band(ws, B_EMI, '13. Emissions', last)
    for key, var, fu, sec in EMI_ROWS:
        r = R_EMI[key]
        summary = key in ('co2.all', 'co2.chg', 'co2.pct')
        fnt = FONT_SUM if summary else FONT
        ids(r, var, fu, sec, fnt)
        codes(r, fnt)
        outline[r] = (0, False) if summary else (1, True)

        def ecell(c, is_base, is_last, r=r, key=key, var=var, fu=fu, sec=sec, fnt=fnt):
            col = L(c)
            q0, q1 = R_PW[('co2', PW_TECH[0][0])], R_PW[('co2', PW_TECH[-1][0])]   # power co2 by type
            pw_sum = lambda crit: f'SUMIF(${crit[0]}${q0}:${crit[0]}${q1},{crit[1]},{col}${q0}:{col}${q1})'
            if var == 'co2' and fu == 'all' and sec == 'pow':
                f = f'=SUM({pw_block("co2", col)})'
                fmt = '#,##0.00'
            elif var == 'co2' and fu == 'all':
                a, z = (S_FIRST, S_LAST) if sec == 'all' else spans[sec]
                crit = 'SecVar' if sec == 'all' else f'$A${a}:$A${z}'
                f = f'=SUMIF({crit},"co2",{col}${a}:{col}${z})'
                if sec == 'all':
                    f += f'+{col}{R_EMI["co2.pow"]}'
                fmt = '#,##0.00'
            elif var == 'co2':
                a, z = S_FIRST, S_LAST
                f = f'=SUMIFS({col}${a}:{col}${z},SecVar,"co2",SecFuel,$B{r})+{pw_sum(("B", f"$B{r}"))}'
                fmt = '#,##0.00'
            elif var == 'co2.ref':
                rr = R_EMI['co2.all']
                f = ref_formula(col, rr)
                fmt = '#,##0.00'
            elif var == 'co2.chg':
                f = f'={col}{R_EMI["co2.all"]}-{col}{R_EMI["co2.ref"]}'
                fmt = '#,##0.00'
            elif var == 'co2.pct':
                f = f'={col}{R_EMI["co2.all"]}/{col}{R_EMI["co2.ref"]}-1'
                fmt = '0.0%'
            elif var == 'co2.sec':
                a, z = S_FIRST, S_LAST
                f = f'=SUMIFS({col}${a}:{col}${z},SecVar,"co2",SecSub,$C{r})+{pw_sum(("C", f"$C{r}"))}'
                fmt = '#,##0.000'
            elif var == 'co2.ets':
                r0 = R_EMI['co2.sec.pow']
                f = (f'=SUMPRODUCT({col}${r0}:{col}${r0 + len(COV_SECTORS) - 1},'
                     f'{pol_range(col, "etsc.pow", len(COV_SECTORS))})')
                fmt = '#,##0.000'
            elif var == 'co2.cap':
                f = f'={col}${R_POL["ets.cap"]}'
                fmt = '#,##0.000'
            elif var == 'co2.gap':
                f = f'=IF({col}{R_EMI["co2.cap"]}>0,{col}{R_EMI["co2.ets"]}/{col}{R_EMI["co2.cap"]}-1,0)'
                fmt = '0.0%'
            elif var == 'ets.lr':
                cap, bce, cov = (f'{col}${R_POL["ets.cap"]}', f'{col}${R_POL["ets.bce"]}', f'{col}{R_EMI["co2.ets"]}')
                f = f'=IF(OR({cap}<=0,{cap}>={bce},{cov}>={bce}),0,LN({cap}/{bce})/LN({cov}/{bce}))'
                fmt = '0.0000'
            elif var == 'ets.next':
                p_, lr = f'{col}${R_POL["ets.p"]}', f'{col}{R_EMI["ets.lr"]}'
                f = f'=IF(OR({p_}<=0,{lr}=0),{col}${R_POL["ets.est"]},{p_}*{lr}^Settings!$C$15)'
                fmt = '0.00'
            elif var == 'co2.chk':                                      # v0.1.09: sectors + power, fuels
                g0, g1 = R_EMI[f'co2.{SECTIONS[0][1]}'], R_EMI['co2.pow']
                f0, f1 = R_EMI[f'co2.f.{FUELS[0][0]}'], R_EMI[f'co2.f.{FUELS[-1][0]}']
                t = f'{col}{R_EMI["co2.all"]}'
                f = f'=ABS({t}-SUM({col}{g0}:{col}{g1}))+ABS({t}-SUM({col}{f0}:{col}{f1}))'
                fmt = '0.000'
            else:                                                       # bco2.chk
                f = f'=SUM({pol_range(col, "bco2.pow", len(COV_SECTORS))})-{col}{R_EMI["co2.ref"]}'
                fmt = '0.000'
            put(ws, f'{col}{r}', f, fnt, F_CHECK if var in ('bco2.chk', 'co2.chk') else (F_BASE if is_base else None),
                fmt)
        each_col(ecell)
    put(ws, f'H{R_EMI_NOTE}', 'Per subsector and fuel: co2 = fuel use (ktoe) x PJ/ktoe x EF (tCO2/GJ, IIASA, EF_GHG '
                              'sheet; biomass 0); power generation: section 3 I (fuel use x MtCO2 per ktoe), in the '
                              'total, by fuel and as ETS sector pow. No inventory adjustment, no process emissions; '
                              'CH4, N2O and local pollutants later. co2.chk = 0 when the total equals sectors + power '
                              'and the fuels. ETS rows: co2.sec by ETS sector, co2.ets covered emissions, co2.cap the '
                              'cap, co2.gap the distance to the cap, '
                              'ets.next the next price (paste its values into ets.ovr with ETSPriceOverride = Yes '
                              'and repeat, or run ets_goalseek.py); bco2.chk = 0 when the baseline data in '
                              'section 1 match scenario 1.', FONT_NOTE)

    # 13b (v0.3.14): CO2 change, grid intensity, Kaya identity
    def c13b(col, r, key, var, fu, sec, is_base, lam):
        cur = lambda k: f'{col}{R_E13B[k]}'
        g0 = L(group_cols(1)[1])                         # scenario 1, base year column
        if var == 'cchg':
            return chg_of(col, R_EMI[f'co2.f.{fu}' if fu != 'all' else f'co2.{sec}']), '#,##0.00'
        if key == 'co2.grid':
            a = (f'{col}{R_EMI["co2.pow"]}*Million', f'{col}{R_PW[("gtot", "")]}*HoursYr')
            return '=' + (call('SAFEDIV', *a) if lam else f'IF({a[1]}=0,0,{a[0]}/({a[1]}))'), '0.000'
        gdp, en, co2 = f'{col}${R_GDPUSD}', cur('kaya.tpes'), f'{col}{R_GHG["ghg.g.co2"]}'
        if fu == 'tpes':                                 # v0.3.18: legacy row 18880: fuel use + primary electricity
            p0, p1 = R_PW[('pe', PRIM_ELEC[0])], R_PW[('pe', PRIM_ELEC[-1])]
            return f'={col}{R_TOTAL}+SUM({col}{p0}:{col}{p1})', '#,##0'
        if var == 'kaya':
            a = {'pop': (f'{col}{R_GHG["pop"]}', 'Thousand'), 'gpc': (gdp, cur('kaya.pop')), 'ei': (en, gdp),
                 'ci': (f'{co2}*Thousand', en)}[fu]
            return '=' + (call('SAFEDIV', *a) if lam else f'IF({a[1]}=0,0,{a[0]}/{a[1]})'), '#,##0.000'
        if fu == 'chk':
            return '=' + '*'.join(cur(f'kidx.{k}') for k in ('pop', 'gpc', 'ei', 'ci')), '0.000'
        x = {'gdp': f'{col}{R_GDPUSD}', 'co2': co2}[fu] if fu in ('gdp', 'co2') else cur(f'kaya.{fu}')
        x0 = '$' + g0 + x[len(col):]                     # same row, scenario 1 base-year column
        return '=' + (call('SAFEDIV', x, x0) if lam else f'IF({x0}=0,0,{x}/{x0})'), '0.000'
    sub_blocks(E13B_BLOCKS, R_E13B, R_E13B_LAB, R_E13B_HEAD, c13b)

    # 14. GHG emissions (v0.2.8): non-CO2 GHGs and methane; Methods, chapter Emissions
    band(ws, B_GHG, '14. GHG emissions', last)
    g1 = group_cols(1)
    b1, e1 = L(g1[1]), L(g1[2][-1])                          # scenario 1 columns (history is the same in all)
    at_inv = lambda rr: f'INDEX(${b1}${rr}:${e1}${rr},GHGYear-BaseYr+1)'   # value of row rr in the inventory year
    G = R_GHG
    src = {j: x for j, *x in CH4_SOURCES}
    gas_par = {'co2': 'ghg.enr.co2'}
    for head, rows_ in GHG_BLOCKS:
        subhead(ws, R_GHG_HEAD[head], head)   # v0.3.9: sub-heading row (column B)
        outline[R_GHG_HEAD[head]] = (1, True)
        label_row(R_GHG_LAB[head], G[rows_[0][0]])
    ghg_par = {}                                             # key -> {param column: formula}
    for j, (lab, tier, share, gwp, cat) in src.items():
        ckey = f'CtryCode&"|{tier}"'
        lk = lambda col_: f'=IFERROR(INDEX(MethVal,MATCH({ckey},MethKey,0),MATCH("{col_}",MethCol,0)),0)'
        f0, f3 = G[f'ch4.src.{CH4_FOSSIL[0]}'], G[f'ch4.src.{CH4_FOSSIL[-1]}']
        r = G[f'ch4.src.{j}']
        fossil = gwp == 'GWPCH4F'
        ghg_par[f'ch4.src.{j}'] = {
            'D': lk(share) if share else '=1',
            'E': f'=${b1}${G[f"ch4.act.{j}"]}',      # v0.6.0 (I47, as legacy rows 894-924): base-year data activity
            'F': (f'=MIN(MethShareCap*$E{r}/SUM($E${f0}:$E${f3}),$D{r})' if fossil else f'=$D{r}'),
            'G': (f'=IF(SUM($F${f0}:$F${f3})=0,0,$F{r}/SUM($F${f0}:$F${f3}))' if fossil else f'=$F{r}')}
        ghg_par[f'ch4.abt.{j}'] = {'D': lk('avg_pow_a'), 'E': lk('avg_pow_b'), 'F': f'={gwp}',
                                   'G': f'=IF(LEFT({MFEE_SW[j]},3)="Yes",1,0)'}   # v0.4.12 (LD46): legacy J196-J200
        inv_col = {'enr': 'D', 'agr': 'E', 'wst': 'F'}[cat]
        ghg_par[f'ch4.em.{j}'] = {'D': f'=${inv_col}${G["ghg.invb"]}*$G{r}*ktPerMt/{gwp}'}
        # v0.9.0 (R8.6, I141 as legacy): oil and gas, downstream gas, biomass J185; coal J186; livestock, rice J187;
        # waste J188
        ghg_par[f'ch4.int.{j}'] = {'D': "='Manual inputs'!$J$" + str(CH4_INTROW[j])}
        if j in ('liv', 'ric', 'wst'):
            c_ = 'agr' if j != 'wst' else 'wst'
            el = lambda d_: f'=N(INDEX({MI_GHG_EL[d_]},MATCH("{MI_GHG_CAT[c_]}",GhgElCat,0)))'   # v0.5.2
            ghg_par[f'ch4.act.{j}'] = {'D': el('gdppc'), 'E': el('pop')}
    bal = lambda fu: f'=INDEX(BalVal,MATCH(CtryCode&"|production",BalKey,0),MATCH("{fu}",BalFuel,0))'
    ghg_par['ch4.act.og'] = {'D': bal('nga'), 'E': bal('oop')}
    ghg_par['ch4.act.cm'] = {'D': bal('coa')}
    for f_, pos, upk, el_, bf in (('oil', 'Oil', 'MethGJperBbl', 'J190', 'oop'), ('coa', 'Coal', 'MethGJperT', 'J191', 'coa'),
                                  ('nga', 'Natural gas', 'MethGJperMMBtu', 'J192', 'nga')):   # v0.5.6 (I66): legacy units
        ghg_par[f'ch4.wd.{f_}'] = {'D': f'=MATCH("{pos}",Prices_int!$F$323:$F$333,0)'}   # v0.6.0: no typed numbers
        ghg_par[f'ch4.pi.{f_}'] = {'E': f'=MethGJperKtoe/{upk}', 'F': "='Manual inputs'!$J$194"}
        ghg_par[f'ch4.prd.{f_}'] = {'D': bal(bf), 'E': f"='Manual inputs'!${el_[0]}${el_[1:]}"}
    pd_ = lambda f_: f'$D${G["ch4.prd." + f_]}'       # v0.5.6 (I66): base production (legacy: held in 2022-2023)
    ghg_par['ch4.fk.og'] = {'D': f'={pd_("oil")}+{pd_("nga")}'}
    ghg_par['ch4.fk.cm'] = {'D': f'={pd_("coa")}'}
    ghg_par['ch4.src.og']['E'] = f'={pd_("oil")}+{pd_("nga")}'   # inventory-year activity = base production (no loop)
    ghg_par['ch4.src.dg']['E'] = '=ConsGas'          # v0.6.0 (I47): data, as legacy H894 (modelled base-year gas use
    ghg_par['ch4.src.bm']['E'] = '=ConsBio'          # includes power, which looks ahead: a loop through the GDP feedback)
    ghg_par['ch4.src.cm']['E'] = f'={pd_("coa")}'
    inv = lambda code_: f'=INDEX(GHGVal,MATCH(CtryCode&"|"&GHGYear,GHGKey,0),MATCH("{code_}",GHGCol,0))'
    ghg_par['ghg.invb'] = {'D': inv('enr.ch4'), 'E': inv('agr.ch4'), 'F': inv('wst.ch4'), 'G': inv('lucf.co2')}
    for c_ in GHG_DRV:
        el = lambda d_, c_=c_: f'=N(INDEX({MI_GHG_EL[d_]},MATCH("{MI_GHG_CAT[c_]}",GhgElCat,0)))'   # v0.5.2
        ghg_par[f'ghg.dr.{c_}'] = {'D': el('gdppc'), 'E': el('pop')}
    for f_ in CH4_PW:
        ghg_par[f'ch4.pw.{f_}'] = {'D': nc_ef(1, '"pow"', f'"{f_}"'), 'E': nc_ef(2, '"pow"', f'"{f_}"')}
    st_ = lambda k_: f'=INDEX(BaseCO2Val,MATCH(CtryCode&"|{k_}",BaseCO2Key,0),MATCH(GHGYear,BaseCO2Year,0))'
    ghg_par['ghg.k'] = {'D': f'=$D${G["ghg.invb"]}', 'E': st_('ch4c'), 'F': st_('ch4sup')}   # v0.6.2: stored scenario 1
    ghg_par['ghg.flr'] = {'D': f'=IFERROR(INDEX(MethVal,MATCH(CtryCode&"|oil",MethKey,0),MATCH("per_flare",MethCol,0)),0)'}
    for c_ in GHG_CATS:
        for g_ in GHG_GASES:
            ghg_par[f'ghg.{c_}.{g_}'] = {'D': f'=MATCH("{c_}.{g_}",GHGCol,0)'}
    ghg_par['ghg.lucf.co2']['E'] = f'=ABS($G${G["ghg.invb"]})'      # size of the last inventory value
    cat0, cat1 = G[f'ghg.{GHG_CATS[0]}.{GHG_GASES[0]}'], G[f'ghg.{GHG_CATS[-1]}.{GHG_GASES[-1]}']
    for key, var, fu, sec in GHG_ROWS:
        r = G[key]
        summary = key in ('ghg.all', 'ghg.inc', 'ghg.chg', 'ghg.pct')
        fnt = FONT_SUM if summary else FONT
        ids(r, var, fu, sec, fnt)
        codes(r, fnt)
        outline[r] = (0, False) if key == 'ghg.all' else (1, True)
        for pc, fm in ghg_par.get(key, {}).items():
            put(ws, f'{pc}{r}', fm, FONT, None, '0.0000')
        if key in GHG_PARONLY:
            continue

        def gcell(c, is_base, is_last, r=r, key=key, var=var, fu=fu, sec=sec, fnt=fnt):
            col, prev = L(c), L(c - 1)
            lam = is_last and key in GHG_LAM
            y = f'{col}${R_YEAR}'
            h = f'{col}${G["ghg.h"]}'
            cur = lambda k: f'{col}{G[k]}'
            old = lambda k: f'{prev}{G[k]}'
            hist_inv = f'INDEX(GHGVal,MAX({h},1),$D{r})'
            fmt = '#,##0.000'
            if key == 'pop':
                f = f'=INDEX(PopVal,MATCH(CtryCode,PopKey,0),MATCH({y},PopYear,0))'
                fmt = '#,##0'
            elif key == 'pop.g':
                pp = (f'INDEX(PopVal,MATCH(CtryCode,PopKey,0),MATCH({y}-1,PopYear,0))' if is_base
                      else old('pop'))
                f = '=' + (call('GROWTHRATE', cur('pop'), pp) if lam else f'{cur("pop")}/{pp}-1')
                fmt = '0.00%'
            elif key == 'gdppc.g':
                a = (f'{col}${R_GDP}', cur('pop.g'))
                f = '=' + (call('PERCAPITA', *a) if lam else f'(1+{a[0]})/(1+{a[1]})-1')
                fmt = '0.00%'
            elif key == 'ghg.h':                             # row of the inventory year on sheet GHGs (0 = none)
                f = f'=IFERROR(MATCH(CtryCode&"|"&{y},GHGKey,0),0)'
                fmt = '0'
            elif key == 'ghg.m':
                a = (f'{col}${R_POL[GHG_PARAMS[5]]}', f'{col}{R_EMI["co2.all"]}', f'{col}{R_EMI["co2.ref"]}')
                f = '=' + (call('EFFORT', *a) if lam
                           else f'IF(AND(LEFT({a[0]},3)="Yes",{a[2]}>0),{a[1]}/{a[2]},1)')
                fmt = '0.0000'
            elif key == 'ghg.gi':
                a = (f'{col}{R_EMI["co2.ind"]}', f'{prev}{R_EMI["co2.ind"]}')
                f = '=0' if is_base else '=' + (call('GROWTHRATE', *a) if lam else f'IF({a[1]}=0,0,{a[0]}/{a[1]}-1)')
                fmt = '0.00%'
            elif var == 'ghg.dr':
                a = (cur('gdppc.g'), f'$D{r}', cur('pop.g'), f'$E{r}', cur('ghg.m'), old('ghg.m'))
                f = '=1' if is_base else '=' + (call('DRIVER', *a) if lam else
                                                f'(1+{a[0]})^{a[1]}*(1+{a[2]})^{a[3]}*{a[4]}/{a[5]}')
                fmt = '0.0000'
            elif var == 'ch4.wd':     # v0.5.6 (I66): world demand (legacy rows 717-719)
                f = f'=INDEX(WDData,$D{r}+WDIdx-1,MATCH({y},WDYear,0))'
                fmt = '#,##0'
            elif var == 'ch4.fk':     # v0.5.6 (I66): fee per ktoe after abatement (legacy rows 6112, 6129)
                ab, em = G[f'ch4.abt.{fu}'], G[f'ch4.em.{fu}']   # base-year production as divisor (no circularity)
                f = (f'=IF($D{r}=0,0,{col}${R_POL["mfee"]}*$F${ab}*$G${ab}*tPerKt*$D${em}/$D{r}*(1-{cur(f"ch4.abt.{fu}")}))'
                     if not is_base else '=0')
                fmt = '#,##0'
            elif var == 'ch4.pi':     # v0.5.6 (I66): producer price index (legacy rows 6142-6144)
                fk = 'ch4.fk.' + ('cm' if fu == 'coa' else 'og')
                gp = f'{col}${R_GP0 + [g[0] for g in GP_ROWS].index(fu)}'
                f = '=1' if is_base else f'=1+({cur(fk)}-{old(fk)})/({gp}*$E{r})*$F{r}'
                fmt = '0.0000'
            elif var == 'ch4.prd':    # v0.5.6 (I66): production (legacy rows 6146-6149)
                p2 = L(c - 2)
                wd = G[f'ch4.wd.{fu}']
                f = (f'=IF({y}<=BaseYr+1,$D{r},{old(key)}*{cur("ch4.pi." + fu)}^$E{r}*{prev}{wd}/{p2}{wd})')
                fmt = '#,##0.0'
            elif var == 'ch4.act':
                j = fu
                if j == 'og':
                    f = f'={cur("ch4.prd.oil")}+{cur("ch4.prd.nga")}'     # v0.5.6 (I66): grown as legacy
                elif j == 'cm':
                    f = f'={cur("ch4.prd.coa")}'
                elif j in ('dg', 'bm'):
                    f = f'={col}{R_FUEL0 + [x[0] for x in FUELS].index("nga" if j == "dg" else "bio")}'
                else:
                    a = (old(key), cur('gdppc.g'), f'$D{r}', cur('pop.g'), f'$E{r}')
                    f = '=1' if is_base else '=' + (call('GROWINDEX', *a) if lam else
                                                    f'{a[0]}*(1+{a[1]})^{a[2]}*(1+{a[3]})^{a[4]}')
                fmt = '#,##0.0' if fu not in ('liv', 'ric', 'wst') else '0.0000'
            elif var == 'ch4.abt':
                a = (f'$D{r}', f'$E{r}', f'{col}${R_POL["mfee"]}*$F{r}*$G{r}')       # v0.4.12: x fee applies
                f = '=' + (call('ABATE', *a) if lam else f'MIN(1,MAX(0,{a[0]}*({a[2]})^{a[1]}))')
                fmt = '0.0%'
            elif var == 'ch4.int':                 # v0.9.0 (R8.6): intensity index of the source
                a = (f'$D{r}', y)
                f = '=' + (call('INTDECLINE', *a) if lam else f'(1-{a[0]})^MAX(0,{a[1]}-GHGYear)')
                fmt = '0.0000'
            elif var == 'ch4.em':                  # v0.9.0 (R8.7): x intensity index (L135 fixed for liv, ric, wst)
                j = fu
                a = (f'$D{r}', cur(f'ch4.act.{j}'), f'$E${G[f"ch4.src.{j}"]}', cur(f'ch4.int.{j}'), cur(f'ch4.abt.{j}'))
                f = '=' + (call('METHSOURCE', *a) if lam else
                           f'IF({a[2]}=0,0,{a[0]}*{a[1]}/{a[2]}*{a[3]}*(1-{a[4]}))')
            elif var == 'ch4' and sec == 'pow':
                f = '=' + nonco2_formula(f'{col}{R_PW[("pe", fu)]}', r, col, lam)
            elif var == 'ch4.c':
                if sec == 'pow':
                    f = f'=SUM({cur("ch4.pw." + CH4_PW[0])}:{cur("ch4.pw." + CH4_PW[-1])})'
                elif sec == 'all':
                    f = f'=SUM({cur("ch4.c.tra")}:{cur("ch4.c.pow")})'
                else:
                    a_, z_ = spans[sec]
                    f = f'=SUMIF($A${a_}:$A${z_},"ch4",{col}${a_}:{col}${z_})'
            elif key == 'ch4.sup':
                f = f'=SUM({cur("ch4.em." + CH4_FOSSIL[0])}:{cur("ch4.em." + CH4_FOSSIL[-1])})'
            elif key == 'ghg.k':
                a = (f'$D{r}', f'($E{r}+$F{r})*GWPCH4F/ktPerMt')
                f = '=' + (call('CALIBRATE', *a) if lam else f'IF({a[1]}=0,0,{a[0]}/({a[1]}))')
                fmt = '0.0000'
            elif key == 'ghg.flr':
                a = (f'$D{r}', f'$D${G["ch4.em.og"]}', cur('ch4.act.og'), f'$E${G["ch4.src.og"]}', cur('ch4.abt.og'))
                f = '=' + (call('FLARING', *a) if lam else
                           f'IF({a[3]}=0,0,FlareCO2perCH4*{a[0]}*{a[1]}*{a[2]}/{a[3]}*{a[4]}/ktPerMt)')
            elif var == 'ghg' and fu in GHG_GASES and sec in GHG_CATS:
                c_, g_ = sec, fu
                if (c_, g_) == ('enr', 'co2'):
                    f = f'={col}{R_EMI["co2.all"]}+{cur("ghg.flr")}'
                elif (c_, g_) == ('enr', 'ch4'):
                    m = f'({cur("ch4.c.all")}+{cur("ch4.sup")})*GWPCH4F/ktPerMt'
                    f = '=' + (call('SCALEBY', cur('ghg.k'), m) if lam else f'{cur("ghg.k")}*{m}')
                elif g_ == 'ch4' and c_ in ('agr', 'wst'):
                    js = [j for j, *x in CH4_SOURCES if x[4] == c_]
                    m = '(' + '+'.join(cur(f'ch4.em.{j}') for j in js) + ')*GWPCH4NF/ktPerMt'
                    f = '=' + (call('INVORMODEL', h, hist_inv, m) if lam else
                               f'IF({h}>0,INDEX(GHGVal,{h},$D{r}),{m})')
                elif is_base:
                    f = f'=IF({h}>0,INDEX(GHGVal,{h},$D{r}),0)'
                elif (c_, g_) == ('enr', 'n2o'):
                    m = f'{old(key)}*IF({prev}{R_EMI["co2.all"]}=0,1,{col}{R_EMI["co2.all"]}/{prev}{R_EMI["co2.all"]})'
                    f = '=' + (call('INVORMODEL', h, hist_inv, m) if lam else f'IF({h}>0,INDEX(GHGVal,{h},$D{r}),{m})')
                elif c_ == 'ipr':
                    a = (h, hist_inv, old(key), f'{col}${R_POL[GHG_PARAMS[6]]}', cur('ghg.gi'))
                    f = '=' + (call('IPPU', *a) if lam else
                               f'IF({h}>0,INDEX(GHGVal,{h},$D{r}),{a[2]}*(1+IF(LEFT({a[3]},3)="Yes",{a[4]},0)))')
                elif (c_, g_) == ('lucf', 'co2'):
                    dec = f'$E{r}*{col}${R_POL[GHG_PARAMS[7]]}'
                    a = (h, hist_inv, old(key), cur('ghg.m'), old('ghg.m'), dec)
                    f = '=' + (call('LULUCF', *a) if lam else
                               f'IF({h}>0,INDEX(GHGVal,{h},$D{r}),IF({a[2]}<0,{a[2]},{a[2]}/{a[4]}*{a[3]}-{dec}))')
                elif c_ in GHG_DRV:
                    m = f'{old(key)}*{cur("ghg.dr." + c_)}'
                    f = '=' + (call('INVORMODEL', h, hist_inv, m) if lam else f'IF({h}>0,INDEX(GHGVal,{h},$D{r}),{m})')
                else:                                        # enr F-gases, LULUCF non-CO2: held
                    f = '=' + (call('INVORMODEL', h, hist_inv, old(key)) if lam else
                               f'IF({h}>0,INDEX(GHGVal,{h},$D{r}),{old(key)})')
            elif var == 'ghg' and sec == 'all' and fu in GHG_GASES:   # by gas, excluding LULUCF
                f = (f'=SUMIFS({col}${cat0}:{col}${cat1},$B${cat0}:$B${cat1},"{fu}",'
                     f'$C${cat0}:$C${cat1},"<>lucf")')
            elif var == 'ghg' and fu == 'all' and sec in GHG_CATS:
                f = f'=SUMIF($C${cat0}:$C${cat1},"{sec}",{col}${cat0}:{col}${cat1})'
            elif key == 'ghg.all':
                f = f'=SUM({cur("ghg.g." + GHG_GASES[0])}:{cur("ghg.g." + GHG_GASES[-1])})'
            elif key == 'ghg.inc':
                f = f'={cur("ghg.all")}+{cur("ghg.c.lucf")}'
            elif key == 'ghg.ref':
                rr = G['ghg.all']
                f = ref_formula(col, rr)
            elif key == 'ghg.chg':
                f = f'={cur("ghg.all")}-{cur("ghg.ref")}'
            elif key == 'ghg.pct':
                f = f'=IF({cur("ghg.ref")}=0,0,{cur("ghg.all")}/{cur("ghg.ref")}-1)'
                fmt = '0.0%'
            elif var == 'ch4.emf':                 # v0.6.2 (I47): as ch4.em, scenario-1 activity for dg and bm
                j = fu
                if j in CH4S_SRC:
                    a = (f'$D${G["ch4.em." + j]}', f'{col}${R_POL["ch4bs." + j]}', f'$E${G[f"ch4.src.{j}"]}',
                         cur(f'ch4.int.{j}'), cur(f'ch4.abt.{j}'))
                    f = '=' + (call('METHSOURCE', *a) if lam else
                               f'IF({a[2]}=0,0,{a[0]}*{a[1]}/{a[2]}*{a[3]}*(1-{a[4]}))')
                else:
                    f = f'={cur("ch4.em." + j)}'
            elif key == 'ch4bs.chk':                # v0.6.2 (I47): scenario 1: stored activity - own activity (0 = current)
                d_ = '+'.join(f'ABS({col}${R_POL["ch4bs." + j]}-{cur("ch4.act." + j)})' for j in CH4S_SRC)
                f = f'=IF({col}${R_SCEN}=1,{d_},0)'
                fmt = '#,##0.000'
            elif key in ('ch4.rev', 'ch4.revf'):   # v0.4.12 (LD46): sources the fee applies to (abt rows F: GWP, G: 1/0)
                j0, j1 = CH4_SOURCES[0][0], CH4_SOURCES[-1][0]
                ab = lambda k_: f'${k_}${G["ch4.abt." + j0]}:${k_}${G["ch4.abt." + j1]}'
                em_ = 'ch4.em.' if key == 'ch4.rev' else 'ch4.emf.'   # v0.6.2 (I47): revf on the stored activity
                a = (f'{cur(em_ + j0)}:{cur(em_ + j1)}', ab('F'), ab('G'), f'{col}${R_POL["mfee"]}')
                f = '=' + (call('FEEREV', *a) if lam else f'SUMPRODUCT({a[0]},{a[1]},{a[2]})*{a[3]}*tPerKt/USDperM')
                fmt = '#,##0.0'
            else:
                raise ValueError(key)
            put(ws, f'{col}{r}', f, fnt, F_LAMBDA if lam else (F_BASE if is_base else None), fmt)
            if key in GHG_LAM and not is_base:
                lam_row(c, r, var, fu, sec, f if lam else None)
        each_col(gcell)
    put(ws, f'H{R_GHG_NOTE}', 'GHGs (Mt CO2e, GWP100): inventory categories by gas (sheet GHGs) while the inventory has '
                              'the year (ghg.h > 0), then projected: energy CO2 = section 13 + flaring; energy CH4 = '
                              'calibration ghg.k x (combustion + fuel supply); energy N2O with energy CO2; industrial '
                              'processes with industrial energy CO2 (increases only); agriculture, waste and other '
                              'with income and population (elasticities on sheet Constants) and the mitigation effort '
                              'ghg.m; LULUCF CO2 declines by a share of its last value a year. Methane of a source = '
                              'its share of the inventory x activity / activity in GHGYear x (1 - abatement by the '
                              'methane fee along the CH4Inputs curves). ghg (summary line) excludes LULUCF.',
        FONT_NOTE)

    # 14b (v0.3.14): GHG change by category and gas; energy GHGs incl. the forcing of local pollutants
    def c14b(col, r, key, var, fu, sec, is_base, lam):
        if var == 'gchg':
            return chg_of(col, R_GHG[f'ghg.c.{sec}' if fu == 'all' else f'ghg.g.{fu}']), '#,##0.00'
        return f'={col}{R_GHG["ghg.c.enr"]}+{col}{R_AP["apf.all"]}', '#,##0.0'
    sub_blocks(E14B_BLOCKS, R_E14B, R_E14B_LAB, R_E14B_HEAD, c14b)

    # 14c (v0.5.7, item 8B): NDC comparison; legacy bugs L119-L123 fixed (Methods, chapter Emissions)
    def c14c(col, r, key, var, fu, sec, is_base, lam):
        N = lambda k: f'{col}{R_NDC[k]}'
        g1_ = group_cols(1)
        s1 = lambda rr: f'${L(g1_[1])}${rr}:${L(g1_[2][-1])}${rr}'          # scenario-1 range of row rr
        at = lambda rr, y: f'INDEX({s1(rr)},MATCH({y},{s1(R_YEAR)},0))'   # scenario-1 value of row rr in year y
        lk = lambda h: f'IFERROR(INDEX(NDCTab,MATCH({N("ndc.key")},NDCKey,0),MATCH({h},NDCHdr,0)),"")'
        gh = lambda k: f'{col}{R_GHG[k]}'
        if key == 'ndc.key':
            return '=CtryCode&"|"&IF(OR(NDCSub="First round",NDCSub="Second round"),NDCSub,"Latest*")', '@'
        if key == 'ndc.typ':
            return '=' + lk('"type"').replace(',"")', ',"Unquantifiable")'), '@'
        if key == 'ndc.k':
            return f'=IFERROR(MATCH({N("ndc.typ")},NDCTypes,0),COUNTA(NDCTypes))', '0'
        if var == 'ndc.ty' and fu != 'all':
            return '=' + lk(f'"{fu}"'), '0'
        if key == 'ndc.alt':                 # second target year chosen and given
            return f'=AND(NDCTyr<>"Main*",N({N("ndc.ty2")})>0)', 'General'
        if key == 'ndc.ty':
            return f'=IFERROR(MIN(NDCYrCap,IF({N("ndc.alt")},{N("ndc.ty2")},{N("ndc.ty1")})),NDCYrCap)', '0'
        if key == 'ndc.ref':
            return '=' + lk('"ref"'), '0'
        if var == 'ndc.x':                   # target value as in the data (reduction negative; Fixed: Mt CO2e)
            return '=' + lk(f'IF({N("ndc.alt")},"{fu}2","{fu}1")') + '&""', '@'   # text: blank stays blank
        if key == 'ndc.lu':
            return '=' + lk('"lulucf"'), '@'
        if key == 'ndc.gas':
            return f'=IF({lk(chr(34) + "gases" + chr(34))}="CO2","CO2","GHGs")', '@'
        if key == 'ndc.co2':                 # CO2 on the NDC's LULUCF basis, this scenario
            return f'={gh("ghg.g.co2")}+IF({N("ndc.lu")}="Includes",{gh("ghg.lucf.co2")},0)', '#,##0.0'
        if key == 'ndc.bs':
            return (f'=IF({N("ndc.gas")}="CO2",{N("ndc.co2")},IF({N("ndc.lu")}="Includes",{gh("ghg.inc")},'
                    f'{gh("ghg.all")}))'), '#,##0.0'
        if key in ('ndc.bty', 'ndc.bi'):     # BAU (scenario 1) in the target year: NDC basis, GHGs incl. LULUCF
            rr = R_NDC['ndc.bs'] if key == 'ndc.bty' else R_GHG['ghg.inc']
            return f'=IFERROR({at(rr, N("ndc.ty"))},"N/A")', '#,##0.0'
        if key == 'ndc.hk':
            return f'=IF({N("ndc.gas")}="CO2","co2|",IF({N("ndc.lu")}="Includes","inc|","exc|"))&{N("ndc.ref")}', '@'
        if key == 'ndc.hh':
            return f'=IFERROR(INDEX(GHHTab,MATCH(CtryCode,GHHIso,0),MATCH({N("ndc.hk")},GHHHdr,0)),"N/A")', '#,##0.0'
        if key == 'ndc.hc':                  # v0.6.1 (I95): inventory column of the NDC basis
            return (f'=IF({N("ndc.lu")}="Includes","tinc","texc")&IF({N("ndc.gas")}="CO2",".co2",".tot")'), '@'
        if key == 'ndc.hv':                  # v0.6.1 (I95): GHGs inventory (2021-2024) in the reference year
            return (f'=IFERROR(INDEX(GHGVal,MATCH(CtryCode&"|"&{N("ndc.ref")},GHGKey,0),'
                    f'MATCH({N("ndc.hc")},GHGCol,0)),"N/A")'), '#,##0.0'
        if key == 'ndc.h':                   # reference-year emissions: scenario 1 in model years, else inventory,
            v_ = N('ndc.hv')                 # else history (v0.6.1, I95)
            return f'=IFERROR({at(R_NDC["ndc.bs"], N("ndc.ref"))},IF(ISNUMBER({v_}),{v_},{N("ndc.hh")}))', '#,##0.0'
        if var == 'ndc.gdp':                 # real GDP in the reference or target year (fix L123)
            y_ = N('ndc.ref') if fu == 'ref' else N('ndc.ty')
            return (f'=IFERROR(INDEX(WEOData,MATCH(CtryCode&".NGDP_R.A",WEOCode,0),MATCH({y_},WEOYr,0)),"N/A")',
                    '#,##0')               # v0.5.7 (I95): legacy WEO real GDP in LCU, 2000-2040 (only the ratio is used)
        if key == 'ndc.hi':                  # intensity target base: reference intensity x target-year GDP
            return f'=IFERROR({N("ndc.h")}/{N("ndc.gdp.ref")}*{N("ndc.gdp.ty")},"N/A")', '#,##0.0'
        if var == 'ndc.f':                   # 1 + target value (1 - reduction); N/A where the NDC gives none
            return f'=IFERROR(1+VALUE({N("ndc.x." + fu)}),"N/A")', '0.000'
        if var == 'ndc.lv':                  # target level on the NDC basis by type (fixes L119-L123)
            b, f_ = N('ndc.bty'), N('ndc.f.' + fu)
            return (f'=IFERROR(CHOOSE({N("ndc.k")},{b}*{f_},{f_}-1,{N("ndc.h")}*{f_},{N("ndc.hi")}*{f_},{b}),"N/A")',
                    '#,##0.0')
        if var == 'ndc.r' and fu in ('u', 'c'):
            return f'=IFERROR(1-{N("ndc.lv." + fu)}/{N("ndc.bty")},"N/A")', '0.0%'
        if key == 'ndc.r.a':
            return f'=IFERROR(AVERAGE({N("ndc.r.u")},{N("ndc.r.c")}),0)', '0.0%'
        if key == 'ndc.r.sel':
            return (f'=IFERROR(1*CHOOSE(MATCH(NDCCond,{{"Unconditional","Conditional"}},0),{N("ndc.r.u")},'
                    f'{N("ndc.r.c")}),{N("ndc.r.a")})'), '0.0%'
        if var == 'ndc.lvl':                 # target GHGs incl. LULUCF: at most the BAU (legacy 18494-18496)
            b = N('ndc.bi')
            return f'=IFERROR(MIN({b},{b}*(1-{N("ndc.r." + fu)})),"N/A")', '#,##0.0'
        if var == 'ndc.idx':                 # target / GHGs incl. LULUCF of the base year (fix L120)
            return f'=IFERROR({N("ndc.lvl." + fu)}/${L(g1_[1])}${R_GHG["ghg.inc"]},"N/A")', '0.000'
        if key == 'ndc.bau':
            return ref_formula(col, R_GHG['ghg.inc']), '#,##0.0'
        if key == 'ndc.red':                 # reduction of GHGs incl. LULUCF against scenario 1
            return f'=IF({N("ndc.bau")}=0,0,1-{gh("ghg.inc")}/{N("ndc.bau")})', '0.0%'
        if key == 'ndc.gap':                 # share of the required reduction achieved (legacy row 18518)
            return f'=IF({N("ndc.r.sel")}>0,{N("ndc.red")}/{N("ndc.r.sel")},1)', '0%'
        if key == 'ndc.over':                # GHGs incl. LULUCF above the chosen target (legacy G18501)
            return f'=IFERROR({gh("ghg.inc")}-{N("ndc.lvl.sel")},0)', '#,##0.0'
        raise ValueError(key)
    sub_blocks(NDC_BLOCKS, R_NDC, R_NDC_LAB, R_NDC_HEAD, c14c)

    # 15. Local air pollutants (v0.2.9): Methods, chapter Emissions
    band(ws, B_AP, '15. Local air pollutants: outputs to the air pollution module', last)   # v0.9.0 (user 2026-10-29: no copies)
    A = R_AP
    for head, rows_ in AP_BLOCKS:
        subhead(ws, R_AP_HEAD[head], head)   # v0.3.9: sub-heading row (column B)
        outline[R_AP_HEAD[head]] = (1, True)
        label_row(R_AP_LAB[head], A[rows_[0][0]])
    pos = {x[0]: k for k, x in enumerate(SUBSECTORS)}
    reg = 'INDEX(RegVal,MATCH(CtryCode,RegKey,0))'
    for key, var, fu, sec in AP_ROWS:
        r = A[key]
        summary = key == 'ap.pm2.all' or (var in ('ap', 'aps') and sec == 'all')
        fnt = FONT_SUM if summary else FONT
        ids(r, var, fu, sec, fnt)
        codes(r, fnt)
        outline[r] = (0, False) if key == 'ap.pm2.all' else (1, True)
        if var == 'apf' and fu != 'all':
            put(ws, f'D{r}', f'=INDEX(EFVal,MATCH({reg}&".mit.gwp100.{fu}",EFKey,0))', FONT, None, '0.000')

        def acell(c, is_base, is_last, r=r, key=key, var=var, fu=fu, sec=sec, fnt=fnt):
            col = L(c)
            lam = is_last and key in AP_LAM
            w = f'{col}${A["ap.w"]}'
            fmt = '#,##0.0'
            if key == 'ap.w':
                y = f'{col}${R_YEAR}'
                f = '=' + (call('EFWEIGHT', y) if lam else f'EFFinShare*({y}-BaseYr)/(EFEndYear-BaseYr)')
                fmt = '0.000'
            elif var == 'apen':                          # v0.9.0 (F): energy use read by the air-pollution module
                if sec == 'pow':
                    f = f'={col}{R_PW[("pe", fu)]}'
                elif fu == 'ecy':
                    f = f'={col}{SUB_HEAD["res"] + 1}'
                else:
                    f = f'={col}{SUB_HEAD["res"] + VOFF["ener"] + [x[0] for x in FUELS].index(fu)}'
            elif var == 'apco2':                         # v0.9.0 (F): CO2 from energy (section 13 total)
                f = f'={col}{R_EMI["co2.all"]}'
                fmt = '#,##0.00'
            elif var == 'ap' and sec == 'pow':
                q0, q1 = R_PW[('pe', PW_TECH[0][0])], R_PW[('pe', PW_TECH[-1][0])]
                c0, c1 = IPWC[f'ap0_{fu}'], IPWC[f'ap1_{fu}']
                a = (f'{col}{q0}:{col}{q1}', f'Inputs_power!${c0}{IPW_R0}:${c0}{IPW_R1}',
                     f'Inputs_power!${c1}{IPW_R0}:${c1}{IPW_R1}', w)
                f = '=' + (call('POLLUTANT', *a) if lam else f'SUMPRODUCT({a[0]},{a[1]}*(1-{w})+{w}*{a[2]})/tPerKt')
            elif var == 'ap' and sec in pos:
                e0 = SUB_HEAD[sec] + VOFF['ener']
                i0 = IN_R0 + pos[sec] * NF
                c0, c1 = IC[f'ap0_{fu}'], IC[f'ap1_{fu}']
                a = (f'{col}{e0}:{col}{e0 + NF - 1}', f'Inputs!${c0}{i0}:${c0}{i0 + NF - 1}',   # rows relative:
                     f'Inputs!${c1}{i0}:${c1}{i0 + NF - 1}', w)                       # copied across only
                f = '=' + (call('POLLUTANT', *a) if lam else f'SUMPRODUCT({a[0]},{a[1]}*(1-{w})+{w}*{a[2]})/tPerKt')
            elif var == 'aps' and sec == 'all':                 # v0.3.12: every pollutant, total of the sectors
                f = '=' + '+'.join(f'{col}{A[f"aps.{fu}.{s_}"]}' for s_, _n in AP_SECS)
            elif var == 'aps' and fu == 'ch4':                  # v0.3.12: CH4 as legacy (combustion + methane sources)
                ch = lambda s_: f'SUM({col}{SUB_HEAD[s_] + VOFF["ch4"]}:{col}{SUB_HEAD[s_] + VOFF["ch4"] + NF - 1})'
                gh = lambda k_: f'{col}{R_GHG[k_]}'
                f = {'cpp': f'={gh("ch4.pw.coa")}', 'gpp': f'={gh("ch4.pw.nga")}',
                     'opp': f'={gh("ch4.pw.oop")}+{gh("ch4.pw.bio")}', 'rod': f'={ch("rod")}',
                     'gro': f'={ch("res")}+{ch("srv")}+{ch("cst")}',
                     'oth': f'={gh("ch4.c.all")}-{gh("ch4.c.pow")}-{ch("rod")}-{col}{A["aps.ch4.gro"]}-{ch("foo")}'
                            f'+{gh("ch4.sup")}',
                     'foo': f'={ch("foo")}+' + '+'.join(gh(f'ch4.em.{j}') for j, *x in CH4_SOURCES
                                                       if x[4] in ('agr', 'wst'))}[sec]
            elif var == 'aps' and sec in ('cpp', 'gpp') and fu not in ('pom', 'opm'):   # v0.3.0: coal, gas plants
                k = [t for t, _n in PW_TECH].index('coa' if sec == 'cpp' else 'nga')
                c0, c1 = IPWC[f'ap0_{fu}'], IPWC[f'ap1_{fu}']
                a = (f'{col}{R_PW[("pe", PW_TECH[k][0])]}', f'Inputs_power!${c0}{IPW_R0 + k}',
                     f'Inputs_power!${c1}{IPW_R0 + k}', w)
                f = '=' + (call('POLLUTANT', *a) if lam else f'SUMPRODUCT({a[0]},{a[1]}*(1-{w})+{w}*{a[2]})/tPerKt')
            elif var == 'aps' and fu == 'pom' and sec != 'all':
                a = (f'{col}{A[f"aps.oc.{sec}"]}', 'PomPerOC')
                f = '=' + (call('SCALEBY', *a) if lam else f'{a[0]}*{a[1]}')
            elif var == 'aps' and fu == 'opm' and sec != 'all':
                a = tuple(f'{col}{A[f"aps.{q}.{sec}"]}' for q in ('pm2', 'bc', 'pom'))
                f = '=' + (call('OTHERPM', *a) if lam else f'MAX(0,{a[0]}-{a[1]}-{a[2]})')
            elif var == 'aps':                                  # sums of the subsector rows
                g = lambda s_: f'{col}{A[f"ap.{fu}.{s_}"]}'
                f = {'opp': f'={g("pow")}-{col}{A[f"aps.{fu}.cpp"]}-{col}{A[f"aps.{fu}.gpp"]}',
                     'rod': f'={g("rod")}', 'foo': f'={g("foo")}',
                     'gro': f'={g("res")}+{g("srv")}+{g("cst")}',
                     'oth': f'=SUM({g("ral")}:{g("nav")})+SUM({g("mch")}:{g("ftr")})-{g("cst")}+{g("oen")}'}[sec]
            elif var == 'apfd':                          # v0.4.11: food fuel use = food & forestry fuel use x share
                k = [x[0] for x in FUELS].index(fu)
                f = f'={col}{SUB_HEAD["foo"] + VOFF["ener"] + k}*Inputs!${IC["fsh"]}{IN_R0 + pos["foo"] * NF + k}'
            elif var == 'ap' and sec == 'fod':           # v0.4.11: food part of food & forestry (legacy row 6702)
                d0 = A[f'apfd.{FUELS[0][0]}']
                i0 = IN_R0 + pos['foo'] * NF
                c0, c1 = IC[f'ap0_{fu}'], IC[f'ap1_{fu}']
                a = (f'{col}{d0}:{col}{d0 + NF - 1}', f'Inputs!${c0}{i0}:${c0}{i0 + NF - 1}',
                     f'Inputs!${c1}{i0}:${c1}{i0 + NF - 1}', w)
                f = '=' + (call('POLLUTANT', *a) if lam else f'SUMPRODUCT({a[0]},{a[1]}*(1-{w})+{w}*{a[2]})/tPerKt')
            elif var == 'ap' and sec == 'fag':           # v0.4.11: forestry and agriculture = the rest (legacy row 6703)
                f = f'={col}{A[f"ap.{fu}.foo"]}-{col}{A[f"ap.{fu}.fod"]}'
            elif var == 'ap' and sec in AP_GROUPS:
                subs = [x[0] for x in SUBSECTORS if x[2] == sec]
                f = f'=SUM({col}{A[f"ap.{fu}.{subs[0]}"]}:{col}{A[f"ap.{fu}.{subs[-1]}"]})'
            elif var == 'ap':                                # total of the pollutant: subsectors + power
                f = f'=SUM({col}{A[f"ap.{fu}.{SUBSECTORS[0][0]}"]}:{col}{A[f"ap.{fu}.pow"]})'
            elif key == 'apf.all':
                f = f'=SUM({col}{A["apf." + AP_GWP[0]]}:{col}{A["apf." + AP_GWP[-1]]})'
                fmt = '#,##0.00'
            else:                                            # forcing of one pollutant
                a = (f'{col}{A[f"ap.{fu}.all"]}', f'$D{r}/ktPerMt')
                f = '=' + (call('SCALEBY', *a) if lam else f'{a[0]}*{a[1]}')
                fmt = '#,##0.00'
            put(ws, f'{col}{r}', f, fnt, F_LAMBDA if lam else (F_BASE if is_base else None), fmt)
            if key in AP_LAM and not is_base:
                lam_row(c, r, var, fu, sec, f if lam else None)
        each_col(acell)
    put(ws, f'H{R_AP_NOTE}', 'Local air pollutants (kt): per subsector, fuel use of its eight fuels (section 5-8 '
                             'blocks) x emission factor (GAINS, sheet EF_PM via Inputs; base-year factor moving '
                             'linearly to the EFSel final factor in EFEndYear and on, weight ap.w); power: generation fuel use by '
                             'type x the power factors (Inputs_power). Forcing (memo): emissions x GWP100 of the GAINS '
                             'region (sheet EF_GHG, gwp100 rows), not part of the GHG totals of section 14. v0.3.0: the same '
                             'emissions by air-pollution module sector (coal, gas, other power plants; ground level '
                             'road; ground level other; other; food & forestry), primary organic matter (PomPerOC x '
                             'OC) and other PM2.5 (PM2.5 - BC - POM, at least 0) for the air-pollution module.',
        FONT_NOTE)

    # 16. GDP effects (v0.3.1): Methods, chapter Macro and results
    band(ws, B_GDP, '16. GDP effects and external balance', last)   # v0.3.16: renamed (Q39)
    Q = R_GDPS
    for head, rows_ in GDP_BLOCKS:
        subhead(ws, R_GDPS_HEAD[head], head)   # v0.3.9: sub-heading row (column B)
        outline[R_GDPS_HEAD[head]] = (1, True)
        label_row(R_GDPS_LAB[head], Q[rows_[0][0]])
    lag_rows = [Q['fis.imp']] + [Q[f'fis.lag.{k}'] for k in range(1, MULT_LAGS)]
    assert lag_rows == list(range(lag_rows[0], lag_rows[0] + MULT_LAGS))
    lagp_rows = [Q['fis.impp']] + [Q[f'fis.lagp.{k}'] for k in range(1, MULT_LAGS)]   # v0.5.7 (I43)
    assert lagp_rows == list(range(lagp_rows[0], lagp_rows[0] + MULT_LAGS))
    for key, var, fu, sec in GDP_ROWS:
        r = Q[key]
        fnt = FONT_SUM if key == 'gdp.eff' else FONT
        ids(r, var, fu, sec, fnt)
        codes(r, fnt)
        outline[r] = (0, False) if key == 'gdp.eff' else (1, True)
        if var == 'fis.eff':
            put(ws, f'D{r}', fu, FONT)
        if key in GDP_PARAMS:                  # MTInputs row looked up on Mapping (as section 1)
            put(ws, f'D{r}', f'=INDEX(MTRowNum,MATCH($A{r}&"|"&$B{r}&"|"&$C{r},MTRowKey,0))', FONT, None, '0')

        def gcell(c, is_base, is_last, r=r, key=key, var=var, fu=fu, fnt=fnt):
            col, prev = L(c), L(c - 1)
            lam = is_last and key in GDP_LAM
            cur = lambda k: f'{col}{Q[k]}'
            fmt = '0.000%'
            if key in GDP_PARAMS:
                f = mt_lookup(r, col)
                fmt = '0' if key.startswith('EXP') else 'General'
            elif key in ('gdp.base', 'gdp.usd'):
                item = 'gdp_growth' if key == 'gdp.base' else 'gdp_usd'
                f = f'=INDEX(WEOVal,MATCH(CtryCode&"|{item}",WEOKey,0),MATCH({col}${R_YEAR},WEOYear,0))'
                fmt = '0.0%' if key == 'gdp.base' else '#,##0.0'
            elif key == 'fis.rev':
                f = (f'={col}{R_REV["rnet.all"]}+{col}{R_REV["rnew.all"]}+{col}{R_REV["rsr.all"]}'
                     f'+{col}{R_REV["rpsu.all"]}+{col}{R_GHG["ch4.rev"]}')   # v0.4.15 (LD55): as legacy (rev.new.usd)
                # v0.9.0 (I47 reverted, user 2026-10-29): the methane fee on the scenario's own activity, as legacy
                # rows 8018-8025; every reference is to the same year (no circularity: the GDP feedback lags a year).
                # ch4.revf (v0.6.2, the stored scenario-1 activity) stays as a memo row.
                fmt = '#,##0.0'
            elif key == 'fis.ref':
                f = ref_formula(col, Q['fis.rev'])
                fmt = '#,##0.0'
            elif key == 'fis.sp':
                a = (cur('fis.rev'), cur('fis.ref'), cur('gdp.usd'))
                f = '=' + (call('FISCALSPACE', *a) if lam else f'({a[0]}-{a[1]})/({a[2]}*MperBn)')
            elif key == 'fis.imp':   # v0.4.15 (LD55): legacy (row 14356): change in USD / this year's GDP, from GDPStartYear
                y_, st = f'{col}${R_YEAR}', f'{col}${Q["GDPStartYear"]}'
                if is_base:
                    f = f'=IF({y_}<{st},0,{cur("fis.sp")})'
                else:
                    a = (y_, st, cur('fis.sp'), f'{prev}{Q["fis.sp"]}', f'{prev}${R_GDPUSD}', f'{col}${R_GDPUSD}')
                    f = '=' + (call('IMPULSE', *a) if lam else f'IF({a[0]}<{a[1]},0,{a[2]}-{a[3]}*{a[4]}/{a[5]})')
            elif var in ('fis.lag', 'fis.lagp'):       # the impulse k years back: previous column, row above
                f = '=0' if is_base else f'={prev}{r - 1}'
            elif key == 'fis.impp':                    # v0.5.7 (I43): uses apply from CPIntro (legacy rows 96-100)
                f = f'=IF({col}${R_YEAR}<{col}${R_POL["CPIntro"]},0,{cur("fis.imp")})'
            elif key == 'fis.grp':
                a = (f'{col}${Q["MultipliersSource"]}', 'IncomeGrp')
                f = '=' + (call('MULTGROUP', *a) if lam else     # v0.4.15 (LD56): est, man as legacy
                           f'IFERROR(INDEX(MultSrcVal,MATCH(LEFT({a[0]},3),MultSrcKey,0)),LOWER({a[1]}))')
                fmt = '@'
            elif key == 'fis.key':
                a = (cur('fis.grp'), f'{col}${Q["FmAdj"]}')
                f = '=' + (call('MULTPREFIX', *a) if lam else f'{a[0]}&"|"&LOWER(SUBSTITUTE({a[1]},"*",""))&"|"')
                fmt = '@'
            elif var == 'fis.eff':
                mt_ = dict(GDP_USE)[fu]
                sh = '-1' if mt_ is None else f'{col}${Q[mt_]}/PctPerUnit'
                lr = lag_rows if fu == 'exc' else lagp_rows   # v0.5.7 (I43): the uses count impulses from CPIntro
                a = (sh, f'{col}${lr[0]}:{col}${lr[-1]}',
                     f'INDEX(MultVal,0,MATCH({col}${Q["fis.key"]}&$D{r},MultKey,0))')
                f = '=' + (call('FISCALEFFECT', *a) if lam else f'{a[0]}*SUMPRODUCT({a[1]},{a[2]})')
            elif key == 'gdp.eff':
                a = (f'SUM({cur("fis.eff.exc")}:{cur("fis.eff.trns")})', f'{col}${Q["GDPEndogenous"]}')
                f = '=' + (call('GDPEFFECT', *a) if lam else f'{a[0]}*(LEFT({a[1]},3)="Yes")')
            elif key == 'gdp.lvl':
                a = (f'{prev}{Q["gdp.eff"]}',)
                f = '=1' if is_base else '=' + (call('LEVELFACTOR', *a) if lam else f'1+{a[0]}')
                fmt = '0.0000'
            elif var == 'gdpg':          # v0.5.7 (8A): contribution to growth: (1 + base) x change in last year's effect / level
                if is_base:
                    f = '=0'
                else:
                    e1 = f'{prev}{Q[f"fis.eff.{fu}"] if fu != "all" else Q["gdp.eff"]}'
                    e2 = '0' if any(c - 1 == group_cols(g_)[1] for g_ in groups) else (f'{L(c - 2)}' + e1[len(prev):])
                    sw = '' if fu == 'all' else f'*(LEFT({col}${Q["GDPEndogenous"]},3)="Yes")'
                    f = f'=(1+{cur("gdp.base")})*({e1}-{e2})/{prev}{Q["gdp.lvl"]}{sw}'
            elif key == 'gdpy':          # v0.6.0: year of the reform (a row shifted to later columns read forward: circular)
                f = f'={col}${R_YEAR}-{col}${Q["GDPStartYear"]}+1'
                fmt = '0'
            elif key == 'gdp.chg.usd':
                f = f'={cur("gdp.pos.usd")}-{cur("gdp.usd")}'
                fmt = '#,##0.0'
            elif key == 'gdp.pos.usd':
                a = (cur('gdp.usd'), cur('gdp.lvl'))
                f = '=' + (call('SCALEBY', *a) if lam else f'{a[0]}*{a[1]}')
                fmt = '#,##0.0'
            else:
                raise ValueError(key)
            put(ws, f'{col}{r}', f, fnt, F_LAMBDA if lam else (F_BASE if is_base else None), fmt)
            if key in GDP_LAM and not is_base:
                lam_row(c, r, var, fu, sec, f if lam else None)
        each_col(gcell)
    put(ws, f'H{R_GDPS_NOTE}', 'GDP effects (legacy section 17, fixed): fiscal space = total revenue (section 12: '
                               'existing taxes net of subsidies and new policies, as legacy rev.new.usd, methane fee on the scenario\'s own activity, I47; legacy '
                               '(row 8024)) above scenario 1, as a share of baseline GDP; the impulse of a year is the change in '
                               'that revenue (USD) over this year\'s GDP, from GDPStartYear (legacy row 14356; v0.4.15). The revenue counts as an energy-tax increase '
                               '(share -1) and is used as MTInputs rows 197-201 say; each use has multipliers by lag '
                               '(sheet Multipliers: income group, global, the country estimates or Manual inputs; base, '
                               'low or high). GDP effect = sum over uses and years of share x impulse x multiplier at '
                               'the lag (lag 0 in the impulse year; legacy applies lag 1 there, bug L68). Next year\'s GDP growth '
                               '(row 7) is the baseline growth with the GDP level raised by the effect (one-year lag; '
                               'legacy adds the effect to growth every year: L24).',
        FONT_NOTE)

    # 16b (v0.3.16): External balance
    def c16b(col, r, key, var, fu, sec, is_base, lam):
        cur = lambda k: f'{col}{R_EXT[k]}'
        gdp = f'{col}${R_GDPUSD}'
        div = lambda a, b: '=' + (call('SAFEDIV', a, b) if lam else f'IF({b}=0,0,({a})/{b})')
        if var == 'xnim' and sec == 'all' and fu != 'all':
            sp = f'{col}{prow("sp", XPRICE.get(fu, fu + ".all"))}'
            a = (f'{col}{R_E11B["echg.f." + fu]}', 'Settings!$C$13', f'{sp}*$D{r}')
            return '=' + (call('REVENUE', *a) if lam else '*'.join(a)) + '/MperBn', '#,##0.000'
        if var == 'xnim' and sec == 'grp':
            fs = [f for f in CPI_FUELS if XGROUP[f] == fu]
            return ('=' + (f'SUM({cur("xnim." + fs[0])}:{cur("xnim." + fs[-1])})' if len(fs) > 1
                           else cur(f'xnim.{fs[0]}'))), '#,##0.000'
        if var == 'xnim':
            return f'=SUM({cur("xnim.g." + XG[0])}:{cur("xnim.g." + XG[-1])})', '#,##0.000'
        if var == 'xtb' and fu != 'all':
            return (f'=INDEX(WEOVal,MATCH(CtryCode&"|tb_{fu}",WEOKey,0),MATCH({col}${R_YEAR},WEOYear,0))',
                    '#,##0.000')
        if var == 'xtb':
            return f'=SUM({cur("xtb." + XG[0])}:{cur("xtb." + XG[-1])})', '#,##0.000'
        if var == 'xtbp':
            return f'={cur("xtb.all")}-{cur("xnim.all")}', '#,##0.000'
        if var == 'xtb.pct':
            return div(cur('xtbp'), gdp), '0.00%'
        if var in ('bca', 'bca.gdp', 'bca.n'):              # v0.9.0 (R11): typed Egypt values (Inputs, key EGY|...)
            k = {'bca': 'bca', 'bca.gdp': 'bca_gdp', 'bca.n': 'bca_n'}[var]
            return (f'=IFERROR(INDEX(WEOVal,MATCH(CtryCode&"|{k}",WEOKey,0),MATCH({col}${R_YEAR},WEOYear,0)),0)',
                    '#,##0.000')
        if var == 'bca.r':
            return f'={cur("bca")}*{col}${R_CPI}', '#,##0.000'
        if var == 'bca.d':                                  # change in net imports: positive = more imports
            return f'=-{cur("xnim.g." + fu)}', '#,##0.000'
        if var in ('bca.p', 'bca.pp'):
            a, d = ('bca.r', 'bca.d') if var == 'bca.p' else ('bca.gdp', 'bca.dp')
            return '=' + cur(a) + ''.join(f'+{cur(d + "." + g)}' for g in XG), '#,##0.000'
        if var == 'bca.y':                                  # as legacy (I129); 0 without data (no #DIV/0!)
            return f'=IF({cur("bca.gdp")}=0,0,ABS({cur("bca.r")}/{cur("bca.gdp")}))', '#,##0.000'
        if var == 'bca.dp':
            return div(cur('bca.d.' + fu), cur('bca.y')), '0.0000'
        return div(cur('xnim.all'), gdp), '0.00%'
    sub_blocks(EXT_BLOCKS, R_EXT, R_EXT_LAB, R_EXT_HEAD, c16b)
    for f in CPI_FUELS:                                  # import share of the fuel's group (data), parameter column D
        put(ws, f'D{R_EXT["xnim." + f]}', f'=INDEX(WEOVal,MATCH(CtryCode&"|ts_{XGROUP[f]}",WEOKey,0),1)', FONT, None,
            '0.000')
    put(ws, f'H{R_EXT_NOTE}', 'External balance (legacy F11): a change in energy use changes net imports '
                                         'by the change x the supply price of section 2 x the share traded of the '
                                         'fuel group (D; legacy rows 741-743: gas 0.19, oil products 0.47, coal 1). '
                                         'Legacy leaves the share out for oil (bug L49). Current account (v0.9.0, '
                                         'R11): typed WEO values for Egypt (legacy reads them through stale codes, '
                                         'bug L50), held at 2031; the policy changes it by minus the change in net '
                                         'energy imports of each fuel group; % of GDP over the GDP implied by the '
                                         'current account and its share (as legacy); coal included (bug L214).',
        FONT_NOTE)

    # 17. Carbon pricing (v0.3.15): Methods, chapter Macro and results
    band(ws, B_CPR, '17. Carbon pricing', last)
    subs_of = {g: [x[0] for x in SUBSECTORS if x[2] == g] for g in CHG_GROUPS if g != 'pow'}
    subs_of['pow'] = ['pow']

    def c17(col, r, key, var, fu, sec, is_base, lam):
        cur = lambda k: f'{col}{R_CPR[k]}'
        co2 = f'{col}{R_EMI["co2.all"]}'
        fc0, fc1 = R_POL[f'fc.{FUELS[0][0]}'], R_POL[f'fc.{FUELS[-1][0]}']
        div = lambda a, b: '=' + (call('SAFEDIV', a, b) if lam else f'IF({b}=0,0,({a})/{b})')
        if var == 'cpi' and fu != 'all':
            rev = f'{col}{R_FIS["rfu." + fu]}' + (f'+{col}{R_FIS["rfg." + fu]}' if fu in RFG_TECH else '')
            return div(rev, f'{col}{R_EMI["co2.f." + fu]}'), '#,##0.0'
        if var == 'cpi':
            f0, f1 = R_FIS[f'rfu.{CPI_FUELS[0]}'], R_FIS[f'rfu.{CPI_FUELS[-1]}']
            rev = f'SUM({col}{f0}:{col}{f1})' + ''.join(f'+{col}{R_FIS["rfg." + t]}' for t in RFG_TECH if t != 'bio')
            return div(rev, co2), '#,##0.0'
        if var == 'ecr':
            return div(f'{col}{R_REV["rnet.all"]}+{col}{R_REV["rnew.all"]}+{col}{R_REV["rsr.all"]}', co2), '#,##0.0'
        if var == 'cpeff':
            a = (f'{col}${R_POL["cptraj"]}', cur('cov.ct.all'))
            return '=' + (call('SCALEBY', *a) if lam else f'{a[0]}*{a[1]}'), '#,##0.0'
        if var == 'covct':
            on = f'({col}${R_POL["ctr." + sec]}>0)'
            if sec == 'pow':
                terms = '+'.join(f'{col}{R_PW[("co2", t)]}*{col}${R_POL["fc." + t]}' for t in RFG_TECH if t != 'bio')
                return f'=({terms})*{on}', '#,##0.00'
            h = SUB_HEAD[sec] + VOFF['co2']
            return f'=SUMPRODUCT({col}{h}:{col}{h + NF - 1}*{col}${fc0}:{col}${fc1})*{on}', '#,##0.00'
        if var == 'cov.ct':
            ss = [x for g in CHG_GROUPS for x in subs_of[g]] if sec == 'all' else subs_of[sec]
            rr = sorted(R_CPR[f'covct.{x}'] for x in ss)
            return div(f'SUM({col}{rr[0]}:{col}{rr[-1]})' if len(rr) > 1 else f'{col}{rr[0]}', co2), '0.0%'
        if var == 'cov.ets':
            return div(f'{col}{R_EMI["co2.ets"]}', co2), '0.0%'
        return f'={cur("cov.ct.all")}+{cur("cov.ets")}', '0.0%'
    sub_blocks(CPR_BLOCKS + [(None, CPR_SUM)], R_CPR, R_CPR_LAB, R_CPR_HEAD, c17)
    put(ws, f'H{R_CPR_NOTE}', 'Implicit carbon price (cpi) and effective carbon rate (ecr) as legacy: revenue '
                                        'net of subsidies per tonne of CO2, so VAT and subsidies count (issue I36; the '
                                        'OECD rate counts carbon taxes, excises and permit prices only). Biomass has '
                                        'no CO2 and no implicit price (legacy #DIV/0!). Coverage: CO2 of the fuels '
                                        'whose switch is on, in sectors with a carbon tax rate above 0 (ETS sectors '
                                        'not complementary have none).', FONT_NOTE)

    # 17b (v0.9.0, R1; Equations_addendum B): inputs from air pollution and transport co-benefits
    band(ws, B_COB, '17b. Inputs from air pollution and transport co-benefits', last)
    fk = {f[0]: k for k, f in enumerate(FUELS)}

    def refc(col, rr):                       # scenario-1 value of row rr in this column's year (helper row 10)
        return f'INDEX(${L(COL_G0)}{rr}:{col}{rr},{col}${R_REFCOL})'

    def c17b(col, r, key, var, fu, sec, is_base, lam):
        cur = lambda k: f'{col}{R_COB[k]}'
        trr = lambda k: f'{col}{R_TR[k]}'
        if var == 'air.vpm':                 # R1.4 (typed, tab FromAirPollution)
            return f'=IFERROR(INDEX(ApVal,MATCH(CtryCode&$D{r},ApKey,0),MATCH({col}${R_YEAR},ApYear,0)),0)', '0.0000'
        if var in ('tran.acc.km', 'tran.con.km', 'tran.rdm.km'):   # R1.6 (typed, tab FromTransportCB)
            return (f'=IFERROR(INDEX(TcbVal,MATCH(CtryCode&$D{r},TcbKey,0),MATCH({col}${R_YEAR},TcbYear,0)),0)',
                    '0.0000')
        if var == 'airpol.cost':             # R1.1 with marginal damages (v0.9.0 PIGAP, I104 fixed): line average of
            a, b = _ap_line(fu, sec)         # the section-1 subsector costs, weighted by the scenario's own use
            if a == b:                       # power: one cost per fuel
                return f'={col}{a}*$D{r}', '0.0000'
            ss = next(x for f_, S_, x in AP_LINES if (f_, S_) == (fu, sec))
            q0, q1 = cur(f'fus.{fu}.{sec}.{ss[0]}'), cur(f'fus.{fu}.{sec}.{ss[-1]}')
            return (f'=IFERROR(SUMPRODUCT({col}{a}:{col}{b},{q0}:{q1})/SUM({q0}:{q1}),AVERAGE({col}{a}:{col}{b}))'
                    f'*$D{r}', '0.0000')
        if var == 'fus':                     # fuel use of the subsector (section 5-8 ener row), own scenario
            return f'={col}{SUB_HEAD[sec] + VOFF["ener"] + fk[fu]}', '#,##0.0'
        if var == 'airpol.cost.gj':          # R1.2-R1.3
            src = cur(f'apct.{sec}.{fu}')
            if (fu, sec) == ('coa', 'res'):  # L192 fixed: residential coal / buildings fuel use of the year
                return f'={src}*({cur("fuq.bld.coa")}>ApCoalResMin*{col}{SEC_SUM["bld"]})', '0.0000'
            return f'={src}/$D{r}', '0.0000'
        if var == 'fuq':
            a, z = spans[sec]
            return f'=SUMIFS({col}${a}:{col}${z},$A${a}:$A${z},"ener",$B${a}:$B${z},$B{r})', '#,##0.0'
        if var == 'air.con.pm2' and sec == 'mod':   # R1.5: total over the module sectors
            return f'=SUM({cur("apm." + AP_SECS[0][0])}:{cur("apm." + AP_SECS[-1][0])})', '#,##0.00'
        if var == 'air.con.pm2':             # R1.5: coefficients (pollutant column of the sector) x emissions (t)
            a, z = R_AP[f'aps.{APS_POLS[0]}.{sec}'], R_AP[f'aps.{APS_POLS[-1]}.{sec}']   # E, F: the country's rows
            return (f'=IF($E{r},SUMPRODUCT({col}{a}:{col}{z},INDEX(ApKap,$E{r},$D{r}):INDEX(ApKap,$F{r},$D{r}))'
                    f'*tPerKt,0)', '#,##0.00')
        pas, fre, cyc = TR_CLS_ROWS[fu]
        if var == 'tran.cls':                # class use of the engineer model (5b), own scenario
            return '=' + '+'.join(trr(k) for k in (pas, fre, cyc) if k), '0.000'
        if var == 'tran.wcl':                # R1.7: passenger weight of scenario 1 (gasoline: 1)
            if fre is None:
                return '=1', '0.000'
            return f'=IFERROR(1-{refc(col, R_TR[fre])}/{refc(col, R_COB["tcls." + fu])},0)', '0.000'
        if var == 'tran.mrg':                # R1.8 (L193 fixed: 0 without class use); D:G elasticity combinations
            w = cur('twcl.' + fu)
            return f'=IF({refc(col, R_COB["tcls." + fu])}=0,0,($D{r}+{w}*$E{r})/($F{r}+{w}*$G{r}))', '0.000'
        if var == 'tran.fsh':                # R1.9: freight share of the class use, own scenario
            return f'=IF({cur("tcls." + fu)}=0,0,{trr(fre)}/{cur("tcls." + fu)})', '0.000'
        if var in ('tran.acc.cost', 'tran.con.cost', 'tran.rdm.cost'):   # R1.10
            k = var.split('.')[1]
            parts = ([f'{col}${R_COB["tkm." + k]}', trr(TR_FE_ROW[fu]), cur('tmrg.' + fu)]
                     + ([cur('tfsh.' + fu)] if k == 'rdm' else []) + [trr('tran.rsh.' + fu)])
            return '=' + '*'.join(parts), '0.0000'
        if var in ('tran.acc.gj', 'tran.con.gj', 'tran.rdm.gj'):         # R1.11
            return f'={cur("t" + var.split(".")[1] + "." + fu)}/$D{r}', '0.0000'
        raise ValueError(key)
    sub_blocks(COB_BLOCKS + [(None, COB_SUM)], R_COB, R_COB_LAB, R_COB_HEAD, c17b)
    for key, var, fu, sec in [x for _h, rows_ in COB_BLOCKS for x in rows_]:   # parameters (D:G)
        r = R_COB[key]
        vals = []
        if var == 'airpol.cost':             # v0.9.0 (PIGAP): GJ per price unit (USD/GJ -> USD/l for oil products)
            vals = [f'=$F{prow("pset", fu + ".all")}' if sec == 'all' else 1]
        elif var in ('air.vpm', 'tran.acc.km', 'tran.con.km', 'tran.rdm.km'):
            vals = [f'|{var}']
        elif var == 'airpol.cost.gj':
            vals = [f'=$F{prow("pset", fu + ".all")}' if sec == 'all' else 1]
        elif var == 'air.con.pm2':           # sector column; first and last pollutant row of the country
            vals = [f'=MATCH("{sec}",ApKapHdr,0)'] + [   # v1.0.1: position by the sector code (was typed)
                f'=IFERROR(MATCH(CtryCode&"|{p_}",ApKapKey,0),0)' for p_ in (APS_POLS[0], APS_POLS[-1])]
        elif var == 'tran.mrg':
            ug, ud, fg, fd = (TRC(k) for k in ('eldg', 'eldd', 'elfg', 'elfd'))
            vals = [f'={ud}', f'={ug}-{ud}', f'={ud}+{fd}', f'={ug}+{fg}-{ud}-{fd}']
        elif var in ('tran.acc.gj', 'tran.con.gj', 'tran.rdm.gj'):
            vals = [f'=$F{prow("pset", fu + ".all")}']
        for pc_, v_ in zip(PARAM_COLS, vals):
            put(ws, f'{pc_}{r}', v_, FONT, None, '@' if str(v_).startswith('|') else '0.0000')
    put(ws, f'H{R_COB_NOTE}', 'Inputs from the air pollution and transport co-benefits modules (v0.9.0, R1): typed '
                              'Egypt values of the legacy 465 run (tabs FromAirPollution and FromTransportCB; other '
                              'countries 0 until the modules export them, issue I106) and the rows computed from this '
                              'model: air-pollution costs per unit as marginal damages (section 1, by subsector, '
                              'weighted by the scenario\'s own fuel use; I104 fixed), costs per GJ, '
                              'modelled ambient PM2.5 from the emissions of section 15 (summary row), transport costs '
                              'per litre from the engineer road model of section 5b whatever TrModel is (issue I100), '
                              'with the passenger weights of scenario 1 (issue I111) and the road share of the '
                              'switched model. The welfare uses the value of averted PM2.5 x the change in modelled '
                              'PM2.5 (I105).', FONT_NOTE)

    # 18. Welfare and externalities (v0.3.17; v0.9.0: R2, R3.13-R3.22): Methods, chapter Macro and results
    NEW18 = {k for _h, rows_ in WEL_BLOCKS[5:] for k, *_x in rows_} - {'wel.pct', 'wel.cli', 'wel.eff'}
    SUBAB = {v_: a_ for v_, a_, _l in SUB_VARS}

    def c18x(col, r, key, var, fu, sec, is_base, lam):
        cur = lambda k: f'{col}{R_WEL[k]}'
        cob = lambda k: f'{col}{R_COB[k]}'
        ref = lambda rr: refc(col, rr)
        pol = lambda k: f'{col}${R_POL[k]}'
        gdp = f'{col}${R_GDPUSD}'
        pe = lambda t: f'{col}{R_PW[("pe", t)]}'
        q_all = lambda f: (f'({col}{R_FUEL0 + fk["ker"]}+{col}{R_FUEL0 + fk["jfu"]})' if f == 'ker'   # v0.9.0: kerosene
                           else f'{col}{R_FUEL0 + fk[f]}')   # and jet fuel, as legacy row 16879 (jet = kerosene price)
        fq = lambda g, f: cob(f'fuq.{g}.{f}')
        if var == 'vatgen':                  # v0.9.2 (bug M15 fixed): VAT_WEO of the year to LastHistPriceYear, then held
            return f'=INDEX(VatWeo,MATCH(MIN({cy(col)},Settings!$C$10),VatWeoYr,0))', '0.0%'
        if var in ('cc.nat', 'cc.glo'):      # R2.1 ($/GJ)
            return f'={pol("scc." + var[3:])}*$D{r}', '0.0000'
        if var == 'airpol.ecy':              # R2.2 (L177 fixed): fuel cost x fuel use / generation
            a = '+'.join(f'{cob("apcg.pow." + t)}*{pe(t)}' for t in ('coa', 'nga', 'oop'))
            return f'=({a})*PJperKtoe/({col}{R_PW[("gtot", "")]}*MWyMkWh)', '0.00000'
        if var == 'apq':
            return '=' + (pe(fu) if sec == 'pow' else fq(sec, fu)), '#,##0.0'
        if var == 'airpol.cost.gj':          # R2.3 (L178 fixed): use-weighted costs of other uses
            if fu in ('coa', 'nga'):
                a = f'{cob("apcg.ind." + fu)}:{cob("apcg.pow." + fu)}'
                q = f'{cur("apq.ind." + fu)}:{cur("apq.pow." + fu)}'
                return f'=IFERROR(SUMPRODUCT({a},{q})/SUM({q}),AVERAGE({a}))', '0.0000'
            b, q = f'{cob("apcg.pow.oop")}:{cob("apcg.ind.oop")}', f'{cur("apq.pow.oop")}:{cur("apq.ind.oop")}'
            if fu == 'odo':
                q3 = f'{cur("apq.tra.die")}:{cur("apq.ind.oop")}'
                return (f'=IFERROR(({cob("apcg.all.die")}*{cur("apq.tra.die")}+SUMPRODUCT({b},{q}))'
                        f'/SUM({q3}),0)'), '0.0000'
            return f'=IF(SUM({q})=0,0,SUMPRODUCT({b},{q})/SUM({q}))', '0.0000'
        if var == 'tot.ext':                 # R2.4
            ks = ['taccg', 'tcong'] + (['trdmg'] if fu == 'die' else [])
            return '=' + '+'.join([cob(f'apcg.all.{fu}')] + [cob(f'{k}.{fu}') for k in ks]), '0.0000'
        if key == 'wel.air.usd':             # R2.5
            c_ = R_COB['air.con.pm2.mod']
            return f'={col}${R_COB["air.vpm"]}*({ref(c_)}-{col}{c_})', '#,##0.000'
        if var == 'wel.rod':                 # R2.6
            k, v_ = {'aci': ('acc', 5336), 'con': ('con', 5336), 'dmg': ('rdm', 5334)}[sec]
            v_ = R_TR[v_]
            return f'={col}${R_COB["tkm." + k]}*({ref(v_)}-{col}{v_})', '#,##0.000'
        if key == 'wel.air.pct':             # R2.7
            return f'={cur("wel.air.usd")}/{gdp}', '0.00%'
        if key == 'wel.rod.pct':
            return f'=SUM({cur("wel.rod.aci")}:{cur("wel.rod.dmg")})/{gdp}', '0.00%'
        if var == 'ffs.q':                   # R2.9 quantities (ktoe)
            pe = lambda t: f'{col}{R_PW[("pe", t)]}' if ("pe", t) in R_PW else ''
            q = {('coa', 'ind'): fq('ind', 'coa'), ('coa', 'res'): fq('bld', 'coa'), ('coa', 'pow'): pe('coa'),
                 ('nga', 'ind'): fq('ind', 'nga'), ('nga', 'res'): fq('bld', 'nga'), ('nga', 'pow'): pe('nga'),
                 ('gso', 'rd'): fq('tra', 'gso'), ('die', 'rd'): fq('tra', 'die'), ('lpg', 'all'): q_all('lpg'),
                 ('ker', 'all'): q_all('ker'), ('oop', 'pow'): pe('oop'),
                 ('oop', 'ind'): f'{fq("ind", "oop")}+{fq("ind", "die")}',
                 ('coa', 'oth'): f'{fq("tra", "coa")}+{fq("oen", "coa")}',
                 ('nga', 'oth'): f'{fq("tra", "nga")}+{fq("oen", "nga")}',
                 ('gso', 'oth'): f'{q_all("gso")}-{fq("tra", "gso")}',
                 ('die', 'oth'): '+'.join(fq(g, f) for g, f in (('bld', 'die'), ('oen', 'die'), ('tra', 'oop'),
                                                                 ('bld', 'oop'), ('oen', 'oop')))}[(fu, sec)]
            return f'={q}', '#,##0.0'
        if var == 'env.ffs.cost' and sec == 'tot':   # R2.10
            f0, f1 = FFS_LINES[0], FFS_LINES[-1]
            return f'=SUM({cur(f"ffs.{f0[1]}.{f0[0]}")}:{cur(f"ffs.{f1[1]}.{f1[0]}")})', '#,##0.000'
        if var == 'env.ffs.cost':            # R2.9 (L179, L180 fixed; die.oth at the oil-product costs, I107)
            u2 = {('gso', 'rd'): cur('text.gso'), ('die', 'rd'): cur('text.die'), ('lpg', 'all'): cob('apcg.all.lpg'),
                  ('ker', 'all'): cob('apcg.all.ker'), ('coa', 'oth'): cur('apo.oth.coa'),
                  ('nga', 'oth'): cur('apo.oth.nga'), ('gso', 'oth'): cob('apcg.all.gso'),
                  ('die', 'oth'): cur('apo.oth.odo')}.get((fu, sec)) or cob(f'apcg.{sec}.{fu}')
            ccf = 'oop' if (fu, sec) == ('die', 'oth') else fu
            q = R_WEL[f'ffsq.{sec}.{fu}']
            return f'=-({cur("ccg." + ccf)}+{u2})*({col}{q}-{ref(q)})*PJperKtoe/MperBn', '#,##0.000'
        if var == 'wel.ffs':
            return f'={cur("ffs.tot")}-{cur("eff.all")}-{cur("mfc.all")}', '#,##0.000'
        if var in ('expsub.con', 'impsub.con') and sec == 'tot':      # R2.12 totals
            a = SUBAB[var]
            return (f'=SUM({cur(f"{a}.{SUB_LINES[0][1]}.{SUB_LINES[0][0]}")}:'
                    f'{cur(f"{a}.{SUB_LINES[-1][1]}.{SUB_LINES[-1][0]}")})'), '#,##0.000'
        if var in SUBAB:                     # R2.11 (scenario's own prices and use; L181-L187 fixed)
            s = lambda v_, s_=sec: cur(f'{SUBAB[v_]}.{s_}.{fu}')
            pc = f'{fu}.{sec}'
            if sec == 'oth' and var in ('supcost', 'extcost', 'vatext', 'rpsub'):   # L187: use-weighted averages
                cs = ['ind', 'res'] if fu == 'ecy' else ['ind', 'res', 'pow']
                a, q = f'{s(var, cs[0])}:{s(var, cs[-1])}', f'{s("con", cs[0])}:{s("con", cs[-1])}'
                return f'=IFERROR(SUMPRODUCT({a},{q})/SUM({q}),AVERAGE({a}))', '0.0000'
            if var == 'supcost':
                return f'={col}{R_PW[("spe", sec)] if fu == "ecy" else prow("sp", pc)}', '0.0000'   # v0.9.0: spe
            if var == 'rpsub':
                return f'={col}{R_PW[("rp", sec)] if fu == "ecy" else prow("rpn", pc)}', '0.0000'
            if var == 'extcost':
                if fu == 'ecy':
                    return '=0', '0.0000'    # issue I108 (as legacy)
                u2 = (cur(f'text.{fu}') if fu in ('gso', 'die') else cob(f'apcg.all.{fu}') if fu in ('lpg', 'ker')
                      else cur('apo.avg.oop') if fu == 'oop' else cob(f'apcg.{sec}.{fu}'))
                return f'={cur("ccg." + fu)}+{u2}', '0.0000'
            if var == 'vatext':              # D: general VAT rate x household share (issue I109; L184, L185)
                return f'=({s("supcost")}+{s("extcost")})*$D{r}*{cur("vatgen")}', '0.0000'   # v0.9.2: M15
            if var == 'effprice':
                return f'={s("supcost")}+{s("extcost")}+{s("vatext")}', '0.0000'
            if var == 'con':                 # PJ (electricity GWh; L186 fixed)
                if fu == 'ecy':
                    q = {'ind': f'{col}{R_ELD["ind"]}', 'res': f'{col}{R_ELD["bld"]}',
                         'oth': f'({col}{R_ELD["tra"]}+{col}{R_ELD["oen"]})'}[sec]
                    return f'={q}*KtoeGWh', '#,##0.0'
                q = {'all': lambda: q_all(fu), 'ind': lambda: fq('ind', fu), 'res': lambda: fq('bld', fu),
                     'pow': lambda: pe(fu), 'oth': lambda: f'({fq("tra", fu)}+{fq("oen", fu)})'}[sec]()
                return f'={q}*PJperKtoe', '#,##0.0'
            if var == 'expsub.con':
                return f'=MAX(0,{s("supcost")}-{s("rpsub")})*{s("con")}/MperBn', '#,##0.000'
            ep_, rp_, sc_ = s('effprice'), s('rpsub'), s('supcost')
            return f'=({rp_}<={ep_})*({ep_}-MAX({rp_},{sc_}))*{s("con")}/MperBn', '#,##0.000'
        if var in ('expsubgdp.con', 'impsubgdp.con'):   # L188 fixed: GDP of the same year
            return f'={cur(var[:3] + ".tot")}/{gdp}', '0.00%'
        if key == 'apecy.g':                 # R3.15 helper (own scenario; scenario 1 read below), issue I121
            a = '+'.join(f'{cob("apcg.pow." + t)}*{col}{R_PW[("gen", t)]}' for t in ('coa', 'nga', 'oop'))
            return f'=({a})/{col}{R_PW[("gtot", "")]}*KtoeGWh/Thousand', '0.00000'
        if var in ('acc.cost', 'con.cost', 'rdm.cost'):   # R3.14: the scenario's own (mf.2)
            return f'={cob("t" + var[:3] + "." + fu)}', '0.0000'
        ep = lambda v_: cur(f'ep.{v_}.{sec}.{fu}')
        pc = f'{fu}.{sec}'
        if var in ('pig.co2e', 'app') and sec == 'avg':   # R3.22
            v_, (f0, s0), (f9, s9) = var, EP_FUELS[0], EP_FUELS[9]
            a, q = f'{cur(f"ep.{v_}.{s0}.{f0}")}:{cur(f"ep.{v_}.{s9}.{f9}")}', f'{cur(f"epq.{s0}.{f0}")}:{cur(f"epq.{s9}.{f9}")}'
            return f'=IF(SUM({q})=0,0,SUMPRODUCT({a},{q})/SUM({q}))', '#,##0.00'
        if var == 'effp.q':
            return '=' + {'all': lambda: q_all(fu), 'ind': lambda: fq('ind', fu), 'res': lambda: fq('bld', fu),
                          'pow': lambda: pe(fu)}[sec](), '#,##0.0'
        if var == 'sup.cost':                # R3.13: scenario 1 x GJ per price unit (D)
            return f'={ref(R_PW[("spe", sec)] if fu == "ecy" else prow("sp", pc))}*$D{r}', '0.0000'   # v0.9.0: spe
        if var == 'airpol.cost.s':           # R3.14-R3.15
            if fu == 'ecy':
                return f'={ref(R_WEL["apecy.g"])}', '0.00000'
            return '=' + cob(f'apct.all.{fu}' if sec == 'all' else f'apcg.{sec}.{fu}'), '0.0000'
        if var == 'scc.cost':
            return ('=0' if fu == 'ecy' else f'={col}{R_POL["cc.code." + pc]}'), '0.0000'
        if var == 'pig':                     # R3.20
            parts = [ep('airpol.cost.s'), ep('scc.cost')] + [cur(f'ep.{v_}.{fu}') for v_, fs in EP_ROAD if fu in fs]
            return '=' + '+'.join(parts), '0.0000'
        if var == 'vat.cost':                # R3.16 (issue I120): D = general VAT rate of the base year or 0
            return (f'=({ep("sup.cost")}+{ep("pig")}*(LEFT({pol("ExternalityAddVAT")},3)="Yes"))*$D{r}'
                    f'*{cur("vatgen")}'), '0.0000'   # v0.9.2: M15
        if var == 'eff.price':               # R3.17
            return f'={ep("sup.cost")}+{ep("pig")}+{ep("vat.cost")}', '0.0000'
        if var == 'rp.eff':                  # R3.18
            return f'={col}{R_PW[("rp", sec)] if fu == "ecy" else prow("rpn", pc)}*$D{r}', '0.0000'
        if var == 'tgap':                    # R3.19
            return f'={ep("rp.eff")}-{ep("eff.price")}', '0.0000'
        if var == 'pig.co2e':                # R3.21
            return f'=IFERROR({ep("pig")}*{pol("scc.glo")}/{ep("scc.cost")},0)', '#,##0.00'
        if var == 'app':
            return f'=IFERROR({ep("pig.co2e")}*{ep("airpol.cost.s")}/{ep("pig")},0)', '#,##0.00'
        if var == 'txo.co2e':                # L203 fixed: 0 where there is no climate cost
            if fu == 'ecy':
                return '=0', '#,##0.00'
            return f'=IFERROR({ref(prow("txo", pc))}*$D{r}*{pol("scc.glo")}/{ep("scc.cost")},0)', '#,##0.00'
        raise ValueError(key)

    # 18. Welfare and externalities, climate part (v0.3.17): Methods, chapter Macro and results
    band(ws, B_WEL, '18. Welfare and externalities', last)
    cy = lambda col: f'{col}${R_YEAR}'
    lvl18 = {**{f: R_FUEL0 + i for i, (f, *_x) in enumerate(FUELS)}, 'ecy': R_ELD['all']}
    G18 = R_GHG

    def c18(col, r, key, var, fu, sec, is_base, lam):
        if key in NEW18:                     # v0.9.0: R2 and the efficient prices
            return c18x(col, r, key, var, fu, sec, is_base, lam)
        cur = lambda k: f'{col}{R_WEL[k]}'
        gdp = f'{col}${R_GDPUSD}'
        ref = lambda rr: f'INDEX(${L(COL_G0)}{rr}:{col}{rr},{col}${R_REFCOL})'   # helper row 10 counts from COL_G0
        div = lambda a, b: '=' + (call('SAFEDIV', a, b) if lam else f'IF({b}=0,0,({a})/{b})')
        grow = lambda lv, yrs: '=' + (call('GROWPATH', lv, 'SCCGr', yrs) if lam else f'{lv}*(1+SCCGr)^({yrs})')
        if var == 'scc':
            if fu == 'tgt':
                return grow('SCCTgt', f'{cy(col)}-SCCTgtYr'), '#,##0.00'
            if fu in ('rkn', 'rkg'):
                return grow(f'INDEX(SCCVal,MATCH(Ricke{"N" if fu == "rkn" else "G"},SCCKey,0))', f'{cy(col)}-BaseYr'), \
                    '#,##0.00'
            if fu == 'epa':
                return grow('SCCEpa', f'{cy(col)}-BaseYr'), '#,##0.00'
            if fu == 'man':
                return (f'=INDEX(SCCManVal,MATCH({cy(col)},SCCManYear,0))',   # v0.5.2 (L103 fixed): Manual inputs
                        '#,##0.00')                                             # row 237, not legacy row 17683
            src = 'NSCCSrc' if fu == 'nat' else 'GSCCSrc'
            opts = ','.join(cur(f'scc.{k}') for k in ('tgt', 'rkn' if fu == 'nat' else 'rkg', 'man', 'epa'))
            o4 = opts.split(',')                     # v0.5.6: legacy option texts (Target*, Ricke et al., Manual, US EPA)
            return f'=CHOOSE(MATCH(LEFT({src},1),{{"T","R","M","U","E"}},0),{opts},{o4[-1]})', '#,##0.00'
        if var == 'dmg':
            a = (cur(f'scc.{fu}'), f'{col}{G18["ghg.all"]}/MperBn')
            return '=' + (call('SCALEBY', *a) if lam else f'{a[0]}*{a[1]}'), '#,##0.00'
        if var == 'wcli':
            rr = R_WEL[f'dmg.{fu}']
            return f'={ref(rr)}-{col}{rr}', '#,##0.000'
        if var == 'wdg':
            if fu == 'ecy':
                rev = f'{col}{R_FIS["rfu.ecy"]}'
            else:
                rev = f'{col}{R_FIS["rfu." + fu]}' + (f'+{col}{R_FIS["rfg." + fu]}' if fu in RFG_TECH else '')
            return div(rev, f'{col}{lvl18[fu]}'), '#,##0.000'
        if var == 'eff' and fu != 'all':
            w = R_WEL[f'wdg.{fu}']
            dq = (f'{col}{R_E11B["echg.f." + fu]}' if fu != 'ecy'
                  else f'({col}{lvl18["ecy"]}-{ref(lvl18["ecy"])})')
            a = (f'{col}{w}', ref(w), dq)
            return '=' + (call('TRAPEZOID', *a) if lam else f'-AVERAGE({a[0]},{a[1]})*{a[2]}/MperBn'), '#,##0.000'
        if var == 'eff':
            return f'=SUM({cur("eff." + WDG_FUELS[0])}:{cur("eff." + WDG_FUELS[-1])})', '#,##0.000'
        if var == 'mfp':
            ab = G18[f'ch4.abt.{fu}']
            a = (f'$D${ab}', f'$E${ab}', f'{col}${R_POL["mfee"]}*$F${ab}*$G${ab}')   # v0.4.12: x fee applies
            return '=' + (call('MFEEPRICE', *a) if lam else
                          f'IF({a[0]}=0,0,MIN({a[2]},IFERROR({a[0]}^(-1/{a[1]}),{a[2]})))'), \
                '#,##0.00'   # v0.9.2 (M21): no cap where b = 0 or the cap overflows (b ~ 1e-14 in the data)
        if var == 'mfc' and fu != 'all':
            em, ab, src = G18[f'ch4.em.{fu}'], G18[f'ch4.abt.{fu}'], G18[f'ch4.src.{fu}']
            base = f'IF($E${src}=0,0,$D${em}*{col}{G18["ch4.act." + fu]}/$E${src})'
            a = (base, f'{col}{ab}', cur(f'mfp.{fu}'), f'$E${ab}')
            return '=' + (call('MFEECOST', *a) if lam else f'{a[0]}*{a[1]}*{a[2]}*{a[3]}/(1+{a[3]})/Million'), \
                '#,##0.0000'
        if var == 'mfc':
            j0, j1 = CH4_SOURCES[0][0], CH4_SOURCES[-1][0]
            return f'=SUM({cur("mfc." + j0)}:{cur("mfc." + j1)})', '#,##0.0000'
        if fu == 'usd':                      # v0.9.0 (R2.8): + air pollution and road transport co-benefits
            return (f'={cur("wcli.nat")}+{cur("wel.air.usd")}+SUM({cur("wel.rod.aci")}:{cur("wel.rod.dmg")})'
                    f'-{cur("eff.all")}-{cur("mfc.all")}'), '#,##0.000'
        x = {'pct': cur('wel.usd'), 'cli': cur('wcli.nat'), 'eff': f'{cur("eff.all")}+{cur("mfc.all")}'}[fu]
        return div(x, gdp), '0.00%'
    sub_blocks(WEL_BLOCKS + [(None, WEL_SUM)], R_WEL, R_WEL_LAB, R_WEL_HEAD, c18)
    for key, var, fu, sec in [x for _h, rows_ in WEL_BLOCKS for x in rows_]:   # v0.9.0: parameters (D:G)
        r, pc = R_WEL[key], f'{fu}.{sec}'
        v_ = None
        if var in ('cc.nat', 'cc.glo'):
            v_ = f'=IFERROR(INDEX(EFGen,MATCH($B{r},EFGenKey,0)),0)'
        elif var == 'vatext' and sec != 'oth':   # v0.9.2 (M15): D = consumer flag x household share; rate: row vatgen
            v_ = (f'=Inputs_prices!${IPC["osh"]}${IP_R0 + [x for x, _l in PRICES].index(pc)}'
                  if pc in OIL_SHARE else 1 if sec == 'res' else 0)
        elif var in ('sup.cost', 'rp.eff', 'txo.co2e'):
            v_ = 1 if fu == 'ecy' else f'=$F{prow("pset", pc)}'
        elif var == 'vat.cost':
            v_ = 1 if pc in OIL_SHARE or sec == 'res' else 0
        if v_ is not None:
            put(ws, f'D{r}', v_, FONT, None, '0.0000')
    put(ws, f'H{R_WEL_NOTE}', 'Climate part of legacy F10. SCC options and default (target-consistent price) '
                                        'as legacy; damages = SCC x GHG excl. LULUCF (section 14). Efficiency costs '
                                        'by fuel: trapezoid on the tax wedge (revenue net of subsidies per unit), so '
                                        'with subsidies a fall in use is a gain; legacy bugs not replicated: LPG '
                                        'pre-existing tax row empty, diesel and kerosene conversion, coal row offset, '
                                        'non-road oil #N/A. Air pollution and transport co-benefits come with their '
                                        'modules (NORMS 3c, no zero placeholders).', FONT_NOTE)

    # Outline (v0.0.15): summary / group button below each row group; everything opens rolled up.
    ws.sheet_properties.outlinePr.summaryBelow = True
    ws.sheet_format.outlineLevelRow = 1          # v0.2.4: one level of row groups (no nesting)
    level = {r: 1 for b, t, z in SECTION_GROUPS for r in range(b + 1, (t or z + 1))}   # v0.2.6: one group per section
    level.update({r: 1 for r in range(R_SCEN + 1, R_GDP)})   # v0.4.1: section 0 rolls up below the frozen rows
    for t in [t for _b, t, _z in SECTION_GROUPS if t] + sorted(SUMMARY2):   # v0.2.7: summary rows without decimals
        for g in groups:
            _, base, years = group_cols(g)
            for c in [base] + years:
                ws.cell(t, c).number_format = '#,##0'
    sums = {t for _b, t, _z in SECTION_GROUPS if t} | SUMMARY2 | BOLD_ROWS
    max_col = ws.max_column                      # v0.4.9: once (openpyxl scans every cell for it; was per row)
    for r in range(B_POL + 1, ws.max_row + 1):   # v0.2.7: bold only on the summary rows (values), never on names
        if r in BAND_ROWS or r in HEAD_ROWS or r in LABEL_ROWS:     # v0.3.9: headings and header rows keep bold
            continue
        for c in range(1, max_col + 1):
            cell = ws.cell(r, c)
            if cell.font.b and not (r in sums and c > 3):
                cell.font = cell.font.copy(bold=False)
    for r in range(R_YEAR + 1, ws.max_row + 1):   # v0.2.7: variable names (column A) in light green text
        if r not in BAND_ROWS and ws.cell(r, 1).value and not str(ws.cell(r, 1).value)[:1].isdigit():
            ws.cell(r, 1).font = ws.cell(r, 1).font.copy(color=C_VARNAME)
    for r in range(1, ws.max_row + 1):           # v0.2.6: one colour in D:G (no grey or beige; bands keep theirs)
        if r not in BAND_ROWS:
            for pc in PARAM_COLS:
                ws[f'{pc}{r}'].fill = PatternFill(fill_type=None)
    for r in range(B_POL + 1, ws.max_row + 1):   # v0.3.9: thin border on every parameter cell (D:G) of a calc row
        if r in BAND_ROWS or r in LABEL_ROWS or r in HEAD_ROWS or not ws.cell(r, 1).value:
            continue
        for pc in PARAM_COLS:
            cell = ws[f'{pc}{r}']
            if cell.value is not None:
                cell.border = Border(left=THIN, right=THIN, top=THIN, bottom=THIN)
    for r in PRICE_TOTAL_ROWS:                   # v0.6.3: post-tax price: thin top, thick bottom, titles and numbers
        for c in range(1, max_col + 1):
            ws.cell(r, c).border = Border(top=THIN, bottom=THICK)
    for c in range(COL_G0, ws.max_column + 1):  # v0.3.9: helper rows (last historical year, scenario-1 column) grey
        for hr in (R_LHCOL, R_REFCOL):
            if ws.cell(hr, c).value is not None:
                ws.cell(hr, c).font = FONT_HELP
    for r, lvl in level.items():
        ws.row_dimensions[r].outlineLevel = lvl
        ws.row_dimensions[r].hidden = True
    for r in sorted(level):                  # the row after a group's last row carries its collapsed flag
        if level.get(r + 1, 0) < level[r]:
            ws.row_dimensions[r + 1].collapsed = True
    ws.freeze_panes = f'{L(COL_G0 + 1)}{R_SCEN + 1}'
    for col, w in {'A': 11, 'B': 5, 'C': 5, 'H': 44, 'I': 9, 'J': 18}.items():
        ws.column_dimensions[col].width = w
    for g in groups:
        code, base, years = group_cols(g)
        ws.column_dimensions[L(code)].width = 24
        for c in [base] + years:
            ws.column_dimensions[L(c)].width = COL_W
        ws.column_dimensions[L(years[-1] + 1)].width = 3          # blank spacer column between scenario groups
    ycols = [c for g in groups for c in group_cols(g)[2] if COL_YEARS_GROUP[0] <= year_of(c) <= COL_YEARS_GROUP[1]]
    for col in list(COL_OUTLINE) + [L(c) for c in ycols]:   # one level: B:G, I:K, 2030-2039 per scenario; rolled up
        ws.column_dimensions[col].outline_level = 1
        ws.column_dimensions[col].hidden = True
    after = ['H', L(COL_G0 + 1)] + [L(c + 1) for c in ycols if year_of(c) == COL_YEARS_GROUP[1]]
    for col in after:                        # columns right of each group carry the collapsed flag
        ws.column_dimensions[col].collapsed = True
    ws.sheet_format.outlineLevelCol = 1
    ws.sheet_view.zoomScale = 75
    return last


# ---------------------------------------------------------------- ReadMe
# v0.4.2: the About table (tab Version Log, About, and Diff): category, topic, text
def about_rows(B):
    S = B
    code2 = S.group_cols(2)[0]
    L = S.L
    return [
        ('About', 'Name', f'{S.NAME} v{S.VERSION}: the mitigation module of the Climate Policy Assessment Tool (CPAT), '
                          'rebuilt by AI as one readable, copy-pasteable Excel workbook for one country at a time.'),
        ('About', 'Purpose', 'An auditable replacement of the CPAT mitigation chain (policies -> prices -> fuel use -> '
                             'revenue, emissions and economic effects). Each variable has one formula across '
                             'subsectors, fuels and years; a scenario is a column group that can be copied.'),
        ('About', 'Coverage', f'2022-{S.LAST_YEAR}. Policies: carbon tax, new ETS, fuel price reform, feebates, methane '
                              'fee, existing carbon pricing. Prices by fuel and sector; power engineer model; fuel '
                              'use of 16 subsectors and 8 fuels; road engineer model (switch); revenue, CO2, GHGs, '
                              'local air pollutants, GDP effects, external balance, carbon pricing and welfare.'),
        ('About', 'Tabs', 'Cover first (contents, colours). MAIN: Mitigation, outputs, stored results, comparison, '
                          'charts. INPUTS: MTInputs (scenarios), Settings, Inputs (data step). DATA: mitigation data '
                          'as legacy, then other data. REF: this tab, and Check, Variables, Lambdas. Each divider tab '
                          'lists its tabs and whether legacy CPAT has them.'),
        ('About', 'Differences with legacy', 'Table Differences with legacy CPAT below: every departure, with its '
                                             'register code, whether it is a bug or an issue, and its status.'),
        ('Layout', 'Mitigation sections', 'Numbered as legacy (0 scenario assumptions; 1 policies; 2 prices; 3 power; '
                                          '5-8 sectors, 5b road engineer model; 11 energy; 12 revenue; 13 CO2; 14 GHGs; '
                                          '15 air pollutants; 16 GDP and external balance; 17 carbon pricing; 18 '
                                          'welfare). The sheet opens rolled up: bands and summary rows only.'),
        ('Layout', 'Rows', 'Down: section > subsector > variable > fuel. Each block of rows has a label row (bold, '
                           'bottom border): H names the variable, D:G its parameters. Columns C:G, I:K and 2030-2039 '
                           'roll up.'),
        ('Layout', 'Scenario groups', 'Across: scenario (outer) > year (inner). Each group: code column, base year, '
                                      f'projection years, spacer. Group 1 (columns {L(S.COL_G0)}-{L(S.COL_G0 + S.GW - 1)}) '
                                      'is the baseline, always scenario 1; differences are against it.'),
        ('Layout', 'Add a scenario', f'MTInputs: copy the last scenario column one column right and edit it. '
                                     f'Mitigation: copy columns {L(code2)}:{L(code2 + S.GW - 1)} and paste at '
                                     f'{L(code2 + S.GW)}; the scenario number, codes, inputs and differences follow.'),
        ('Layout', 'Codes', 'country.mit.<variable>.<sector>.<fuel>.<suffix>.<scenario> in the code column of each '
                            'group (e.g. egy.mit.ener.rod.gso.e.1); MTOutputs and the macros find results by code.'),
        ('Layout', 'Data tabs', 'Grouped and ordered as legacy (DATA_MITIGATION, DATA_DISTN, DATA_TRAN, DATA_OUTPUT; '
                                'DATA_OTHER last). Tabs that match a legacy data table hold it unchanged from A4 '
                                '(header row 3; key formula column right of the table where needed): paste the full '
                                'legacy data rows (all countries) at A4. Prices_dom: paste legacy rows 4 onwards at '
                                'A1. Tables with Egypt only are alone on their tab or at the bottom. See '
                                'Methods, chapter Data tabs.'),
        ('Layout', 'Inputs', 'MTInputs is the main input sheet (one column per scenario, rows as legacy). Manual inputs '
                             'is the second source: the legacy tab of that name at its legacy addresses (paste the '
                             'legacy tab from row 3); the note on each block\'s title row says what reads it (v0.5.2).'),
        ('Assumptions', 'Units', 'Prices, taxes and policy values are real US dollars of the results year (MTInputs '
                                 'ResultsYear, Settings), per GJ; fuel use in ktoe; emissions in Mt; money in USD m '
                                 'or bn as labelled.'),
        ('Assumptions', 'Deflators', f'Row {S.R_CPI} (infl, US CPI) converts nominal domestic data and nominal policy '
                                     f'inputs; row {S.R_DEFL} (defl, US GDP deflator) converts international prices, as '
                                     'legacy. MTInputs policy values are real unless NomorReal = Nominal (carbon '
                                     'price only).'),
        ('Assumptions', 'History', 'Prices up to the last historical price year (Settings) are data; later years are '
                                   'projected. Base-year fuel use is data; later fuel use is modelled.'),
        ('Assumptions', 'Global vs scenario', 'Global (Settings, MTInputs scenario 1): results year, price controls, '
                                              'last historical year, gas market. Per scenario (MTInputs column): '
                                              'international price source, carbon price, ETS, fuel price reform, '
                                              'feebates, coverage, methane fee, revenue use.'),
        ('Assumptions', 'Changed data', 'Bright yellow cells with red text (Prices_dom, Inputs) are data corrected by '
                                        'the user or set by assumption (VAT rate where blank; other oil products as '
                                        'the other oil products).'),
        ('Assumptions', 'Signs', 'Subsidies are negative: net revenue = taxes + subsidies.'),
        ('Algorithm', 'Prices', 'sp = fixed part + (sp(t-1) - fixed part) x gp(t)/gp(t-1); txo with the legacy '
                                'pass-through rule; rpb = (sp + txo) x (1 + VAT). By subsector, atp = max(rpb + new '
                                'policies x (1 + VAT), 0.01). Each price block shows the full retail price, the build-up '
                                'and the new taxes and subsidies weighted by subsector fuel use.'),
        ('Algorithm', 'Fuel use', 'CPAT eq. 3.3.3: last year x GDP growth^eps_Y x (atp ratio)^eps_U x ((atp + shadow '
                                  'price) ratio)^efficiency exponent x autonomous efficiency x shock factor.'),
        ('Algorithm', 'Policies', 'Carbon tax on covered fuels and sectors; new ETS: cap-based permit price (fast '
                                  'estimate, override row, goal seek ets_goalseek), benchmarks give the output-based '
                                  'share; feebates and regulations act as shadow prices on the efficiency margin.'),
        ('Algorithm', 'Power', 'Engineer model as legacy (bugs fixed): demand, dispatch, retirement, investment, '
                               'generation costs and electricity prices.'),
        ('Algorithm', 'Results', 'Revenue = fuel use x unit taxes (existing, subsidies, new); CO2 = fuel use x EF; '
                                 'GHGs by inventory category; differences against scenario 1 are formulas of each '
                                 'group; price changes are price indices, never ratios of unit values.'),
        ('Algorithm', 'LAMBDA test group', f'Scenario groups 1 and 2 hold plain formulas of at most 100 characters in '
                                           f'every year 2022-{S.LAST_YEAR}, so they work in any Excel and in '
                                           f'LibreOffice. Group {S.LAMBDA_GROUP} (light beige, dark red text) runs the '
                                           'scenario of group 2 with the named LAMBDA of every calculated row in every '
                                           'year (Excel 365); the spacer column of group 2 compares the two (0 = same '
                                           'results; largest difference in row 4). Tab Check, Variables, Lambdas lists '
                                           'the LAMBDA formulas.'),
        ('Algorithm', 'Distribution', 'Household incidence in one analysis year (MTInputs YearDistn), deciles '
                                     'across: price changes from Mitigation (household fuels; consumption categories '
                                     'through GTAP), budget shares, effects, survey to national accounts, revenue '
                                     'recycling, net effect, compensation, Gini; legacy codes in MTOutputs '
                                     '(Methods, chapter Distribution).'),
        ('Use', 'More scenarios', 'Up to five policy scenarios: copy scenario group 2 of Mitigation and of '
                                  'Distribution into the next free group (right of the LAMBDA test group); each '
                                  'numbers itself and reads its MTInputs definition (1-6).'),
        ('Use', 'First run', 'Enable macros (unblock the file first if downloaded), run CheckBatchRun (Alt+F8); '
                             'MacroCheck shows PASS when the macros work and Excel reproduces the stored results.'),
        ('Use', 'Batch runs', 'MTInputs: J = baseline, K = live policy scenario, L onwards = definitions (Run? = Yes). '
                              'Macro RunAllScenarios stores each definition in StoredResults; ScenarioCompare '
                              'compares stored scenarios in one year.'),
        ('Version notes', 'Version log', 'Table above: one row per version, newest last; each task is also logged in '
                                         'the repository CAVEATS.md.'),
        ('Version notes', 'Documents', 'Method notes *_Method.md, Equations, the '
                                       'Word documentation and the register of bugs, issues and upgrades sit next to '
                                       'the builder build.py.'),
    ]


def build_readme(wb):
    """v0.4.2: About this workbook (category, topic, text; column C wide)."""
    ws = wb['Sheet']                                # the workbook's first sheet (the Cover sits before it)
    ws.title = 'ReadMe'
    title(ws, 'About this workbook', 3)
    for j, h in enumerate(['Category', 'Topic', 'Text'], 1):
        put(ws, f'{L(j)}3', h, FONT_B)
    for i, (cat, k, v) in enumerate(about_rows(sys.modules[__name__]), 4):
        put(ws, f'A{i}', cat)
        put(ws, f'B{i}', k, FONT_B)
        c = put(ws, f'C{i}', v)
        for col in 'ABC':
            ws[f'{col}{i}'].alignment = Alignment(wrap_text=True, vertical='top')
    assert c




def expand_save(wb):
    """v0.4.9: the copy of the workbook that LibreOffice recalculates, written from the workbook in memory: Distribution
    blanked, the other cells that call a LAMBDA expanded (as check variant 'expand'), the file saved,
    the cells restored (no save and reload of the full workbook)."""
    import tempfile
    import check_full as C
    keep = []
    # v0.4.9: blanked in the copy, as the stored results do not read it: the Distribution sheet (no LiveOutputs
    # indicator reads it). v0.6.7: group 2 is the live scenario (LAMBDAs), so it is kept (v0.4.9-v0.6.5 blanked the LAMBDA
    # test group 3; v0.6.6 blanked group 2 by mistake, so its stored definitions were empty)
    ws_d = wb['Distribution']
    for ws, c0, c1 in ((ws_d, 1, ws_d.max_column),):
        for row in ws.iter_rows(min_col=c0, max_col=c1):
            for cell in row:
                if cell.value is not None:
                    keep.append((cell, cell.value))
                    cell.value = None
    data_tabs = {t for _div, tabs in DATA_GROUPS for t in tabs}           # key formulas only, no LAMBDA calls
    for ws in [w for w in wb.worksheets if w.title not in data_tabs]:
        for row in ws.iter_rows():
            for cell in row:
                v = cell.value
                if isinstance(v, str) and v.startswith('=') and C.LAMBDA_CALL.search(v):
                    keep.append((cell, v))
                    cell.value = C.expand(v)
    path = os.path.join(tempfile.mkdtemp(), 'expand.xlsx')
    try:
        wb.save(path)
    finally:
        for cell, v in keep:
            cell.value = v
    return path


LO_SESSIONS = int(os.environ.get('LO_SESSIONS', 3))   # v0.4.9: parallel LibreOffice sessions (0.9 GB, one core each)


def fast_batch(wb, log=print, sessions=LO_SESSIONS):
    """v0.4.9 (user rule 2026-10-17: the full build as fast as possible): the baseline CO2 refresh and the Python
    emulation of RunAllScenarios (no ETS goal seek) in parallel LibreOffice sessions, one spawned process each
    (lo_session.run_worker), started in the background; returns a function that waits and returns the
    StoredResults rows. Each session loads the LAMBDA-expanded workbook once (loading recalculates). Session 1 reports
    scenario 1's CO2 by ETS sector (raw: EFCalib = 1 in this pass); from it the baseline CO2 data (DATA_VALUES,
    CALIB) are set here and sent to every session, which writes it into BaselineCO2 and runs its share: the
    baseline, or a definition with Run? = Yes copied into the live column (rows 8-MT_END except the formula rows 10
    and 12, and its name), recalculated in memory; only MTOutputs blocks 1-2 are read. The caller writes BaselineCO2
    into the workbook (write_bco2) after the wait."""
    import multiprocessing as mp
    import lo_session as LO
    stamp = 'build (Python emulation of RunAllScenarios, no ETS goal seek)'
    path = expand_save(wb)
    _, base, years = group_cols(1)
    c0, c1 = base, years[-1]
    live = MT_COL0 + 1
    runs = [(None, [])] + [((num, name), [('ScenarioDefinition', r0, r1, MT_COL0 + num - 1, live) for r0, r1 in
                                          ((8, 9), (11, 11), (13, MT_END), (MT_ROW_NAME, MT_ROW_NAME))])
                           for num, name, run, _e in DEFINITIONS if run == 'Yes']      # None: the baseline
    spec = {'first': [('Settings', 26, 3, 29, 3)] + [('Mitigation', R_EMI[f'co2.sec.{x}'], c0, R_EMI[f'co2.sec.{x}'], c1)
                                                       for x in COV_SECTORS]
                     + [('Mitigation', R_GHG[k_], c0, R_GHG[k_], c1) for _j, k_, _l in CH4S_STORE],
            'read': ('LiveOutputs', MTO_R0, 1, MTO_R0 + 2 * MTO_BLOCK, MTO_C0 + NY - 1),
            'plan': [runs[k::sessions] for k in range(sessions)]}
    ctx = mp.get_context('spawn')
    outbox, inboxes = ctx.Queue(), [ctx.Queue() for _ in range(sessions)]
    procs = [ctx.Process(target=LO.run_worker, args=(k, path, spec, inboxes[k], outbox), daemon=True)
             for k in range(sessions)]
    for p_ in procs:
        p_.start()

    def baseline_co2(data):
        st = LO.Grid(26, 3, data[0])
        assert abs(st.cell(29, 3).value - 1) < 1e-12, st.cell(29, 3).value
        n4 = 1 + len(COV_SECTORS) + len(CH4S_STORE)
        for j, row in zip([x[0] for x in CH4S_STORE], data[1 + len(COV_SECTORS):n4]):  # v0.6.2 (I47, ghg.k)
            for c, v in zip(range(c0, c1 + 1), row[0]):
                assert isinstance(v, (int, float)), (j, c, v)
                DATA_VALUES[(f'ch4bs.{j}', year_of(c))] = v
        for x, row in zip(COV_SECTORS, data[1:1 + len(COV_SECTORS)]):
            for c, v in zip(range(c0, c1 + 1), row[0]):
                assert isinstance(v, (int, float)), (x, c, v)
                DATA_VALUES[(f'bco2.{x}', year_of(c))] = v
        raw = {y: sum(DATA_VALUES[(f'bco2.{x}', y)] for x in COV_SECTORS) for y in [BASE_YEAR] + YEARS}
        gy = BASE_YEAR                           # v0.4.11: legacy calibrates the base-year estimate (C30, C28)
        k = st.cell(28, 3).value / raw[gy] if str(st.cell(27, 3).value)[:3] == 'Yes' else 1.0
        CALIB['k'], CALIB['raw'], CALIB['year'], CALIB['inv'] = k, raw[gy], gy, st.cell(28, 3).value
        for key in list(DATA_VALUES):
            if key[0].startswith('bco2.'):
                DATA_VALUES[key] *= k
        CALIB['raw_all'] = raw
        cells = [('BaselineCO2', 4 + i, 4 + j, DATA_VALUES[(f'bco2.{x}', y)])
                 for i, x in enumerate(COV_SECTORS) for j, y in enumerate([BASE_YEAR] + YEARS)]
        cells += [('BaselineCO2', BCO2_RAW + 1 + i, 4 + j, DATA_VALUES[(f'ch4bs.{x}', y)])   # v0.6.2 (I47)
                  for i, (x, *_r) in enumerate(CH4S_STORE) for j, y in enumerate([BASE_YEAR] + YEARS)]
        return cells + [('BaselineCO2', BCO2_RAW, 4 + j, raw[y]) for j, y in enumerate([BASE_YEAR] + YEARS)]

    def wait():
        out, done = {}, 0
        try:
            while done < sessions:
                msg = outbox.get(timeout=1800)
                if msg[0] == 'first':
                    cells = baseline_co2(msg[1])
                    for q in inboxes:
                        q.put(('set', cells))
                elif msg[0] == 'grid':
                    key, vals = msg[1], {'LiveOutputs': LO.Grid(MTO_R0, 1, msg[2])}
                    out[key] = (stored_rows(vals, 1, 1, None, stamp) if key is None
                                else stored_rows(vals, key[0], 2, key[1], stamp))
                elif msg[0] == 'done':
                    done += 1
                else:
                    raise RuntimeError(f'LibreOffice session {msg[1]} failed:\n{msg[2]}')
        finally:
            for q in inboxes:
                q.put(('stop',))
            for p_ in procs:
                p_.join(30)
                if p_.is_alive():
                    p_.terminate()
        for key, _c in runs[1:]:
            log(f'  definition {key[0]}: recalculated')
        return [row for key, _c in runs for row in out[key]]
    return wait

BUILD_CACHE = os.path.join(HERE, '.buildcache')
DOC_SHEETS = {'VersionLog', 'ReadMe', 'LegacyDiff', 'Variables', 'Lambdas', 'MacroCheck'}
CACHE_CODE = ['check_full.py', 'lo_session.py', 'power_model_ref.py', 'transport_model_ref.py']   # v0.4.9


def model_fingerprint(wb):
    """v0.3.6: hash of every cell of the workbook before the baseline-CO2 refresh, and of the Python code the refresh
    and the batch emulation run: same hash = same baseline CO2 and same stored results."""
    import hashlib
    h = hashlib.sha256()
    for ws in wb.worksheets:
        if ws.title in DOC_SHEETS:                   # documentation only: no effect on the values
            continue
        h.update(ws.title.encode())
        for row in ws.iter_rows(values_only=True):
            h.update(repr(row).encode())
    for f in CACHE_CODE:
        h.update(open(os.path.join(HERE, f), 'rb').read())
    return h.hexdigest()


def build_cache(fp, value=None):
    """v0.3.6: read (value None) or write the cached results of the slow build steps for fingerprint fp."""
    import pickle
    path = os.path.join(BUILD_CACHE, f'{fp}.pkl')
    if value is None:
        if os.environ.get('FORCE') or not os.path.exists(path):
            return None
        with open(path, 'rb') as f:
            return pickle.load(f)
    os.makedirs(BUILD_CACHE, exist_ok=True)
    with open(path, 'wb') as f:
        pickle.dump(value, f)


def write_bco2(wb, raw):
    """Baseline CO2 values (DATA_VALUES) and the raw row on sheet BaselineCO2."""
    ws = wb['BaselineCO2']                   # v0.2.4: data sheet; Mitigation rows bco2 look it up
    for i, s in enumerate(COV_SECTORS):
        for j, y in enumerate([BASE_YEAR] + YEARS):
            put(ws, f'{L(4 + j)}{4 + i}', DATA_VALUES[(f'bco2.{s}', y)], FONT, F_INPUT, '#,##0.000')
    for j, y in enumerate([BASE_YEAR] + YEARS):
        put(ws, f'{L(4 + j)}{BCO2_RAW}', raw[y], FONT, F_INPUT, '#,##0.000')
        for i, (x, *_r) in enumerate(CH4S_STORE):                       # v0.6.2 (I47, ghg.k)
            put(ws, f'{L(4 + j)}{BCO2_RAW + 1 + i}', DATA_VALUES[(f'ch4bs.{x}', y)], FONT, F_INPUT, '#,##0.000')


SR_HEAD, SR_FIRST, SR_Y0 = 5, 6, 8      # StoredResults: header row, first data row, first year column (H)
SR_LAST = 5000
SR_COLS = ['Scenario ID', 'Scenario name', 'Code stem', 'Output code', 'Description', 'Unit', 'Stored']
SC_SLOTS = 10                           # v0.6.7: ScenarioCompare scenario slots (ScenarioDefinition columns J..S)
SC_YEAR = 2030
SC_KEY = [  # v0.6.7: key results table (code stem, label); level, difference and % difference vs the baseline
    ('mit.co2.all.all.e', 'Energy CO2 emissions'), ('mit.ghg.all.all', 'GHG emissions excluding LULUCF'),
    ('mit.rpct.all.tot', 'Revenue (share of GDP)'), ('mit.gdp.eff.all.all', 'GDP effect of revenue use'),
    ('mit.wel.all.pct', 'Net welfare effect (share of GDP)')]
