TABMAP_FILE = os.path.join(HERE, 'tabs.json')
_CELLREF = re.compile(r"^(\$?[A-Z]{1,3}\$?\d+)(:\$?[A-Z]{1,3}\$?\d+)?$")
_CELL = re.compile(r"(\$?[A-Z]{1,3}\$?)(\d+)")


def _shift(ref, off):
    return _CELL.sub(lambda m: f'{m.group(1)}{int(m.group(2)) + off}', ref) if off else ref


def _qsheet(name):
    return f"'{name}'" if re.search(r"[^A-Za-z0-9_]", name) else name


def translate(formula, host, tmap):
    """Re-point a formula after the merge: references to a merged sheet go to its tab with the block's row offset;
    unqualified references of a formula that moves with its block shift by the block's offset."""
    from openpyxl.formula.tokenizer import Tokenizer
    if not (isinstance(formula, str) and formula.startswith('=')):
        return formula
    if '!' not in formula and not (host in tmap and tmap[host][1]):
        return formula
    tok = Tokenizer(formula)
    changed = False
    for t in tok.items:
        if t.type != 'OPERAND' or t.subtype != 'RANGE':
            continue
        v = t.value
        if '!' in v:
            sh, ref = v.rsplit('!', 1)
            shn = sh.strip("'")
            if shn in tmap and _CELLREF.match(ref):
                new, off = tmap[shn][0], tmap[shn][1]
                t.value, changed = f'{_qsheet(new)}!{_shift(ref, off)}', True
        elif host in tmap and tmap[host][1] and _CELLREF.match(v):
            t.value, changed = _shift(v, tmap[host][1]), True
    return tok.render() if changed else formula


def merge_tabs(wb):
    """v0.3.6 (user request): stack the blocks of each merged tab top to bottom (MERGE_GAP blank rows between them),
    re-point every formula and defined name, put the reference tabs last and write the tab map (old sheet -> tab,
    row offset, block height) next to the workbook for the check and the document scripts."""
    from copy import copy
    import json
    tmap = {}
    for target, blocks in MERGES:
        off = 0
        for b in blocks:
            h = wb[b].max_row
            tmap[b] = [target, off, h]
            off += h + MERGE_GAP
    gone = {b for _t, blocks in MERGES for b in blocks if tmap[b][0] != b}
    stale = [k for k, (_n, body) in LAMBDAS.items() if any(f'{g}!' in body for g in gone)]
    assert not stale, f'LAMBDA bodies name a merged sheet (use a defined name): {stale}'
    appended = {b for _t, blocks in MERGES for b in blocks[1:]}
    for ws in wb.worksheets:                         # formulas of every sheet that stays in place
        if ws.title in appended:
            continue
        for row in ws.iter_rows():
            for c in row:
                if isinstance(c.value, str) and c.value.startswith('='):
                    c.value = translate(c.value, ws.title, tmap)
                elif ws.title == 'Lambdas' and c.column == 3 and c.row > 4 and isinstance(c.value, str):
                    c.value = translate('=' + c.value, 'Mitigation', tmap)[1:]   # v0.3.13: formula texts (bug M12)
    for target, blocks in MERGES:
        wt = wb[blocks[0]]
        for b in blocks[1:]:
            ws, off = wb[b], tmap[b][1]
            for row in ws.iter_rows():
                for c in row:
                    if c.value is None and not c.has_style:
                        continue
                    tc = wt.cell(c.row + off, c.column)
                    if (b == 'Lambdas' and c.column == 3 and c.row > 4 and isinstance(c.value, str)
                            and not c.value.startswith('=')):   # v0.5.2: formula texts, host Mitigation (M12 again:
                        tc.value = translate('=' + c.value, 'Mitigation', tmap)[1:]   # Lambdas is appended since v0.4.2)
                    else:
                        tc.value = translate(c.value, b, tmap)
                    if c.has_style:
                        tc._style = copy(c._style)
            for r, d in ws.row_dimensions.items():
                if d.height is not None:
                    wt.row_dimensions[r + off].height = d.height
            for col, d in ws.column_dimensions.items():
                if d.width and d.width > (wt.column_dimensions[col].width or 0):
                    wt.column_dimensions[col].width = d.width
            for m in list(ws.merged_cells.ranges):
                wt.merge_cells(_shift(m.coord, off))
            del wb[b]
        wt.title = target
    for name, dn in list(wb.defined_names.items()):
        if dn.attr_text and '!' in dn.attr_text and not dn.attr_text.startswith('_xlfn'):
            dn.attr_text = translate('=' + dn.attr_text, None, tmap)[1:]
    data = [w.title for w in wb.worksheets if w.title not in TAB_ORDER and w.title not in DIVIDERS
            and w.title not in {t for t, _b in MERGES}]
    tabs = [t for _d, tabs_ in DATA_GROUPS for t in tabs_]
    assert set(data) == set(tabs), set(data) ^ set(tabs)          # v0.4.2: every data tab in a group
    wb._sheets = [wb[n] for n in TAB_ORDER + DATA_MIT + [t for div, tabs_ in DATA_GROUPS[1:] for t in [div] + tabs_]
                  + ['REF->>']
                  + [t for t, _b in MERGES[2:]]]
    style_tabs(wb, tmap)                             # v0.4.2: title bars, sub-heading bars, header fills, widths
    wb.active = wb.sheetnames.index('ScenarioCompare')
    with open(TABMAP_FILE, 'w', encoding='utf-8') as f:
        json.dump(tmap, f, indent=1)


