def fill_divider(ws):
    """v0.4.2: divider tab: title bar and the table of contents of its group."""
    div = ws.title
    w = 4
    bar(ws, 2, DIVIDER_TITLE[div], w, F_TITLE, FONT_T)
    put(ws, 'A3', 'The tabs of this group (following this divider). In legacy CPAT: Yes = the same tab, Partly = '
                  'a tab with part of this content, No = new in this workbook.')
    for j, h in enumerate(['Tab', 'Content', 'In legacy CPAT', 'Legacy tab'], 1):
        put(ws, f'{L(j)}5', h, FONT_B).border = Border(bottom=THIN)
    r = 6
    for d_, tab, content, leg, ltab in TAB_INFO:
        if d_ == div:
            for j, v in enumerate([tab, content, leg, ltab], 1):
                put(ws, f'{L(j)}{r}', v)
            r += 1
    for col, wd in {'A': 30, 'B': 80, 'C': 16, 'D': 44}.items():
        ws.column_dimensions[col].width = wd
    ws.sheet_properties.tabColor = F_TABDIV


def style_tabs(wb, tmap, only=None):
    """v0.4.2 (NORMS 2.7): every tab but Mitigation, MTInputs and Prices_dom (legacy layouts): a dark green title bar
    in row 2 with what the tab is about, light green sub-heading bars for the blocks of a merged tab, all across the
    same width (the tab's used columns); table headers bold with a bottom border and no fill; tab colours."""
    keep_layout = {'Mitigation', 'Distribution', 'ScenarioDefinition', 'Prices_dom', 'Cover'}
    merged = {t: blocks for t, blocks in MERGES}
    group_col = {}
    cur = None
    for ws in wb.worksheets:
        if ws.title in DIVIDERS:
            cur = ws.title
        group_col[ws.title] = cur
    colours = {'MAIN->>': '00AE49', 'INPUTS->>': '92D050', 'DATA_MITIGATION->>': 'DCE6F1', 'DATA_DISTN->>': 'DCE6F1',
               'DATA_TRAN->>': 'DCE6F1', 'DATA_OUTPUT->>': 'DCE6F1',
               'DATA_OTHER->>': 'DCE6F1', 'REF->>': 'F2F2F2'}
    for ws in wb.worksheets:
        if only is not None and ws.title not in only:   # v0.4.9: one tab rebuilt after the merge (StoredResults)
            continue
        if ws.title in DIVIDERS:
            fill_divider(ws)
            continue
        if group_col.get(ws.title):
            ws.sheet_properties.tabColor = colours[group_col[ws.title]]
        if ws.title in keep_layout:
            continue
        width = max(ws.max_column, 4)
        for row in ws.iter_rows():                   # table headers: bold, no fill (inputs keep the light green)
            for c in row:
                if c.font and c.font.b and c.fill and c.fill.fgColor and str(c.fill.fgColor.rgb).endswith('EBF1DE'):
                    c.fill = PatternFill(fill_type=None)
                    c.border = Border(bottom=THIN)
        blocks = merged.get(ws.title, [ws.title])
        first_title = ws['A2'].value
        expl = TAB_EXPL.get(ws.title)
        bar(ws, 2, expl or first_title, width, F_TITLE, FONT_T)
        for b in blocks[1:]:
            r = tmap[b][1] + 2
            bar(ws, r, ws[f'A{r}'].value, width, F_BAND, FONT_SUBBAR)
        for r in range(3, ws.max_row + 1):          # existing light green bars (e.g. MTOutputs blocks): full width
            a = ws.cell(r, 1)
            if a.fill and a.fill.fill_type and str(a.fill.fgColor.rgb).endswith('92D050'):
                for j in range(1, width + 1):
                    ws.cell(r, j).fill = F_BAND
        if blocks[0] in BLOCK1_BAR:
            bar(ws, 3, BLOCK1_BAR[blocks[0]], width, F_BAND, FONT_SUBBAR)
        if ws.title == 'Settings':                   # mapping tables are structure, not inputs: no fill
            off = tmap['Mapping'][1]
            for row in ws.iter_rows(min_row=off + 1):
                for c in row:
                    if c.fill and c.fill.fgColor and str(c.fill.fgColor.rgb).endswith('EBF1DE'):
                        c.fill = PatternFill(fill_type=None)
        for col, wd in TAB_WIDTHS.get(ws.title, {}).items():
            ws.column_dimensions[col].width = wd


def tab_map():
    """v0.3.6: old sheet name -> [tab, row offset, block height] of the last build."""
    import json
    with open(TABMAP_FILE, encoding='utf-8') as f:
        return json.load(f)


class Tab:
    """v0.3.6: a merged block seen as the old sheet: rows count from the block's first row (wb[old] before v0.3.6)."""

    def __init__(self, wb, old):
        new, self.off, self.height = tab_map().get(old, [old, 0, None])
        self.ws, self.title, self.parent = wb[new], new, wb

    @property
    def max_row(self):
        return self.height if self.height is not None else self.ws.max_row

    @property
    def max_column(self):
        return self.ws.max_column

    def cell(self, row, column, value=None):
        c = self.ws.cell(row + self.off, column)
        if value is not None:
            c.value = value
        return c

    def __getitem__(self, coord):
        m = _CELL.fullmatch(coord.replace('$', ''))
        return self.ws[f'{m.group(1)}{int(m.group(2)) + self.off}']

    def iter_rows(self, min_row=1, max_row=None, min_col=None, max_col=None, values_only=False):
        return self.ws.iter_rows(min_row=min_row + self.off, max_row=(max_row or self.max_row) + self.off,
                                 min_col=min_col, max_col=max_col, values_only=values_only)


def tab(wb, old):
    """v0.3.6: the block of the old sheet `old` (a Tab), or the sheet itself when it was not merged."""
    return Tab(wb, old) if old in tab_map() else wb[old]


MACRO_BUTTONS = [  # v0.6.7: the core buttons on ScenarioCompare (label, macro), green
    ('Recalculate now', 'RecalculateNow'), ('Recalculation on/off', 'ToggleRecalculation'),
    ('Run stored scenarios', 'RunAllScenarios'), ('Update data tables', 'UpdateDataTables')]
MORE_BUTTONS = [  # v0.6.7: the other buttons, grey, below the core ones
    ('Store baseline', 'StoreBaseline'), ('Store live scenario', 'StoreLiveScenario'),
    ('Solve ETS (live scenario)', 'SolveETSLive'), ('Clear stored scenarios', 'ClearStoredScenarios'),
    ('Sort stored outputs', 'SortStoredOutputs'), ('Group blank scenarios', 'GroupBlankScenarios'),
    ('Refresh dashboard charts', 'RefreshDashboard'), ('First-run test', 'CheckBatchRun')]
BTN_MORE_ROW = 6                        # v0.6.7: first row (0-based) of the other buttons
BTN_COL0, BTN_COL1 = 10, 13              # v0.6.7: ScenarioCompare columns K.. (0-based anchors), three columns each
BTN_ACROSS, BTN_ROWS = 4, 2              # v0.6.7: four across, two rows high; core buttons in rows 4-5
BTN_ROW0 = 3                             # v0.6.7: first row (0-based) of the core buttons


def add_macro_buttons(path, sheet='ScenarioCompare', buttons=None, col0=BTN_COL0, row0=BTN_ROW0, colour='00B050',
                      across=None):
    """v0.2.7: add one rounded-rectangle shape per macro to the sheet (DrawingML shapes with macro="[0]!Name", as Excel
    writes an Insert > Shape with Assign Macro). openpyxl cannot write shapes, so the drawing part is added to the
    saved file: drawing XML, its content type, the sheet relationship and the <drawing> element of the sheet. v0.6.4:
    a sheet with charts already has a drawing part: the shapes are appended to it."""
    import shutil
    import tempfile
    import zipfile
    from xml.sax.saxutils import escape
    zin = zipfile.ZipFile(path)
    parts = {n: zin.read(n) for n in zin.namelist()}
    zin.close()
    wbx, rels = parts['xl/workbook.xml'].decode(), parts['xl/_rels/workbook.xml.rels'].decode()
    buttons = MACRO_BUTTONS if buttons is None else buttons
    rid = re.search(rf'<sheet [^>]*name="{re.escape(sheet)}"[^>]*r:id="(rId\d+)"', wbx).group(1)
    target = re.search(rf'<Relationship [^>]*Id="{rid}"[^>]*/>', rels).group(0)
    sheet_part = re.search(r'Target="/?(?:xl/)?([^"]+)"', target).group(1)
    sheet_part = 'xl/' + sheet_part.lstrip('/').replace('xl/', '')
    n_draw = 1 + sum(1 for n in parts if re.match(r'xl/drawings/drawing\d+\.xml$', n))
    draw_part = f'xl/drawings/drawing{n_draw}.xml'
    srels = sheet_part.replace('worksheets/', 'worksheets/_rels/') + '.rels'
    sx = parts[sheet_part].decode()
    old = re.search(r'<drawing\b[^>]*\br:id="([^"]+)"', sx)
    if old:                                        # v0.6.4: the sheet's chart drawing takes the shapes
        tgt = re.search(rf'<Relationship [^>]*Id="{old.group(1)}"[^>]*/>', parts[srels].decode()).group(0)
        draw_part = 'xl/drawings/' + re.search(r'Target="[^"]*/([^"/]+)"', tgt).group(1)
    ns = ('xmlns:xdr="http://schemas.openxmlformats.org/drawingml/2006/spreadsheetDrawing" '
          'xmlns:a="http://schemas.openxmlformats.org/drawingml/2006/main"')
    anchors = []
    w = BTN_COL1 - BTN_COL0
    across = across or BTN_ACROSS
    for k, (label, macro) in enumerate(buttons):
        c0, r0 = col0 + (k % across) * w, row0 + (k // across) * BTN_ROWS
        anchors.append(
            f'<xdr:twoCellAnchor {ns} editAs="absolute"><xdr:from><xdr:col>{c0}</xdr:col>'
            f'<xdr:colOff>38100</xdr:colOff><xdr:row>{r0}</xdr:row><xdr:rowOff>19050</xdr:rowOff></xdr:from><xdr:to>'
            f'<xdr:col>{c0 + w}</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>{r0 + BTN_ROWS}</xdr:row><xdr:rowOff>0'
            f'</xdr:rowOff></xdr:to><xdr:sp macro="[0]!{macro}" textlink=""><xdr:nvSpPr><xdr:cNvPr '
            f'id="{1001 + k + (0 if colour == "00B050" else 100)}" name="btn{macro}"/>'
            f'<xdr:cNvSpPr/></xdr:nvSpPr><xdr:spPr><a:prstGeom prst="roundRect"><a:avLst/></a:prstGeom>'
            f'<a:solidFill><a:srgbClr val="{colour}"/></a:solidFill><a:ln><a:noFill/></a:ln></xdr:spPr>'
            f'<xdr:txBody><a:bodyPr vertOverflow="clip" horzOverflow="clip" lIns="0" tIns="0" rIns="0" bIns="0" '
            f'rtlCol="0" anchor="ctr"/><a:lstStyle/>'
            f'<a:p><a:pPr algn="ctr"/><a:r><a:rPr lang="en-GB" sz="900" b="1"><a:solidFill><a:srgbClr val="FFFFFF"/>'
            f'</a:solidFill><a:latin typeface="Arial"/></a:rPr><a:t>{escape(label)}</a:t></a:r></a:p></xdr:txBody>'
            f'</xdr:sp><xdr:clientData/></xdr:twoCellAnchor>')
    if old:
        dx = parts[draw_part].decode()
        close = re.search(r'</(?:\w+:)?wsDr>\s*$', dx)
        parts[draw_part] = (dx[:close.start()] + ''.join(anchors) + dx[close.start():]).encode()
    else:
        parts[draw_part] = (f'<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<xdr:wsDr {ns}>'
                            + ''.join(anchors) + '</xdr:wsDr>').encode()
        ct = parts['[Content_Types].xml'].decode()
        ct = ct.replace('</Types>', f'<Override PartName="/{draw_part}" '
                        'ContentType="application/vnd.openxmlformats-officedocument.drawing+xml"/></Types>')
        parts['[Content_Types].xml'] = ct.encode()
        rel = (f'<Relationship Id="rIdBtn1" Type="http://schemas.openxmlformats.org/officeDocument/2006/'
               f'relationships/drawing" Target="../drawings/drawing{n_draw}.xml"/>')
        if srels in parts:
            parts[srels] = parts[srels].decode().replace('</Relationships>', rel + '</Relationships>').encode()
        else:
            parts[srels] = ('<?xml version="1.0" encoding="UTF-8" standalone="yes"?>\n<Relationships '
                            'xmlns="http://schemas.openxmlformats.org/package/2006/relationships">' + rel
                            + '</Relationships>').encode()
        if 'xmlns:r=' not in sx[:600]:
            sx = sx.replace('<worksheet ', '<worksheet xmlns:r="http://schemas.openxmlformats.org/officeDocument/'
                            '2006/relationships" ', 1)
        el = '<drawing r:id="rIdBtn1"/>'
        for tag in ('<legacyDrawing', '<legacyDrawingHF', '<picture', '<oleObjects', '<controls',
                    '<webPublishItems', '<tableParts', '<extLst', '</worksheet>'):
            if tag in sx:
                sx = sx.replace(tag, el + tag, 1)
                break
        parts[sheet_part] = sx.encode()
    tmp = tempfile.mktemp(suffix='.xlsm')
    with zipfile.ZipFile(tmp, 'w', zipfile.ZIP_DEFLATED) as zo:
        for n, d in parts.items():
            zo.writestr(n, d)
    shutil.move(tmp, path)


def vba_module_source():
    """The module text of CPATScenarios.bas without its Attribute VB_Name line (added by the VBA writer)."""
    text = open(BAS, encoding='cp1252').read()
    assert text.startswith('Attribute VB_Name = "CPATScenarios"')
    m = re.search(r'Private Const NYEARS As Long = (\d+)', text)     # v0.2.3: the macros read this many year columns
    assert m and int(m.group(1)) == NY, f'CPATScenarios NYEARS {m and m.group(1)} differs from the {NY} model years'
    chk = tab_map()['MacroCheck']                                              # v0.3.6: MacroCheck block
    text = re.sub(r'Private Const SH_CHECK As String = "[^"]*"', f'Private Const SH_CHECK As String = "{chk[0]}"', text)
    text = re.sub(r'Private Const CHK_FIRST As Long = \d+', f'Private Const CHK_FIRST As Long = {chk[1] + CHK_FIRST}',
                  text)
    with open(BAS, 'w', encoding='cp1252', newline='') as f:                  # keep the importable module in step
        f.write(text)
    for const, want in (('MT_LAST', MT_END), ('MIT_MAX_ROW', MIT_MAX)):        # v0.3.5: transport rows
        m = re.search(rf'Private Const {const} As Long = (\d+)', text)
        assert m and int(m.group(1)) == want, f'CPATScenarios {const} {m and m.group(1)} differs from {want}'
    return text.split('\n', 1)[1]


